-- 중독백과 영어화: definition_en/example_en/body_en/advanced_en 주입
-- 한국어 컬럼 미변경. id 기준 UPDATE. 주석은 -- 만 사용.
-- 실행: psql -h localhost -U postgres -d addiction_news -f backend/translate_en/inject_english.sql
BEGIN;
UPDATE encyclopedia_terms SET definition_en='A chronic, relapsing brain condition characterized by compulsive repetition of substance use or behavior despite harmful consequences, with loss of control. Core features include craving, tolerance, withdrawal, and relapse tendency. The underlying mechanism is neuroadaptation, where repeated stimulation alters brain circuits involved in reward, motivation, and judgment. Initially driven by pleasure seeking, behavior becomes dominated by withdrawal avoidance and compulsive habits, making self-control difficult. Modern diagnostic systems define addiction as a preventable and treatable disease, not a moral failing.', example_en='Example: A person who initially drinks only on weekends to relieve stress may, after several years, experience hand tremors and difficulty concentrating without alcohol, leading to drinking from morning onward.', body_en='[{"h": "What It Is", "p": "Addiction is a chronic condition involving compulsive repetition of substance use or specific behaviors despite harmful consequences, with loss of control. Core features include craving, tolerance, withdrawal, and relapse, encompassing both substance and behavioral addictions."}, {"h": "Not a Matter of Willpower", "p": "Addiction is often misunderstood as weak willpower, but it results from repeated use altering the brain''s reward, motivation, and control circuits. Even with strong will to stop, the altered brain makes it difficult, which is the key point."}, {"h": "How It Progresses", "p": "Starting from initial pleasure seeking, motivation gradually shifts to compulsive use to avoid withdrawal and distress. Voluntary choice transforms into habitual, automatic behavior, making control difficult."}, {"h": "Recovery Potential", "p": "Addiction is chronic and relapsing but recoverable. Thanks to brain plasticity, recovery can occur through new learning and supportive environments. Relapse is not failure but a signal that management is needed."}]'::jsonb, advanced_en='[{"h": "Disease Model and Beyond", "p": "Modern understanding of addiction centers on the disease model viewing addiction as a brain disease, but has expanded to a biopsychosocial model integrating psychological, social, and environmental factors. Debates continue between pure brain disease perspectives and learning/context perspectives."}, {"h": "Motivation Shift", "p": "A key transition in addiction is from ''liking'' to ''needing.'' Pleasure seeking shifts to pain avoidance, and wanting becomes separated from liking, explaining the paradox of addiction."}, {"h": "Stigma and the Politics of Definition", "p": "What is defined as addiction involves not only science but also social values. The expansion of the concept (e.g., behavioral addictions) and issues of stigma remain ongoing controversies surrounding the definition of addiction."}]'::jsonb, updated_at=now() WHERE id='addiction';
UPDATE encyclopedia_terms SET definition_en='A popular concept suggesting that certain personality types are particularly vulnerable to addiction. However, the existence of a single ''addictive personality'' common to all addicts is scientifically controversial; the current view is that several traits such as high impulsivity, sensation-seeking, negative emotionality, and low conscientiousness partially increase risk. This concept is prone to misuse as a tool for stigmatizing individuals and requires careful use.', example_en='Example: A tendency to strongly seek new stimuli and have difficulty controlling impulses, often appearing alongside multiple risk behaviors.', body_en='[{"h": "What is it?", "p": "Addictive personality is a popular concept suggesting that certain personality types are particularly vulnerable to addiction. However, the existence of a single ''addictive personality'' common to all addicts is scientifically controversial."}, {"h": "What is true?", "p": "Although there is no single addictive personality, it is true that certain traits such as impulsivity, sensation-seeking, and negative emotionality increase addiction risk alongside multiple risk behaviors. This is a matter of ''traits'' rather than ''types''."}, {"h": "Why is the misunderstanding dangerous?", "p": "The concept of ''addictive personality'' is easily misused as a tool for stigmatizing individuals and can lead to resignation such as ''I am just that kind of person.'' It is dangerous because it frames personality as a fixed destiny."}, {"h": "What should we consider?", "p": "Addiction vulnerability arises not from a single personality but from the interaction of multiple traits, environments, and experiences. Rather than categorizing individuals, it is useful to examine specific risk factors and strengths together."}]'::jsonb, advanced_en='[{"h": "The myth of a single type", "p": "Research does not support a single personality profile common to all individuals with addiction. ''Addictive personality'' is closer to a popular belief than a scientific construct."}, {"h": "Contribution of trait dimensions", "p": "Instead, trait dimensions such as impulsivity, sensation-seeking, negative emotionality, and low conscientiousness partially contribute to addiction risk. These are continuous traits, not dichotomous types."}, {"h": "Risk of becoming a tool for stigmatization", "p": "The label ''addictive personality'' can essentialize and stigmatize individuals, and may foster pessimism about recovery potential. This is why careful use is required."}]'::jsonb, updated_at=now() WHERE id='addictive-personality';
UPDATE encyclopedia_terms SET definition_en='Attention-deficit/hyperactivity disorder (ADHD) is a representative comorbid condition that increases the risk of substance and behavioral addictions due to its association with impulsivity. Research indicates that appropriate treatment may actually lower addiction risk, making diagnosis and integrated treatment important.', example_en='Example: An untreated adult with ADHD may use substances self-medicatively to achieve stimulant effects.', body_en='[{"h": "What is it", "p": "ADHD (attention-deficit/hyperactivity disorder) is a neurodevelopmental disorder characterized by inattention, hyperactivity, and impulsivity, and is a major risk factor for and comorbid condition with addiction."}, {"h": "How are they connected", "p": "The impulsivity and reward sensitivity of ADHD increase the risk of substance and behavioral addictions. Additionally, untreated adults with ADHD may use substances self-medicatively to achieve stimulant effects."}, {"h": "Treatment reduces risk", "p": "Research suggests that appropriate ADHD treatment may actually lower addiction risk. Untreated ADHD is more dangerous, and diagnosis and treatment can contribute to addiction prevention."}, {"h": "What to consider", "p": "When ADHD and addiction co-occur, integrated treatment is necessary. The management of stimulant medication misuse and the treatment of ADHD itself must be balanced."}]'::jsonb, advanced_en='[{"h": "Shared neural basis", "p": "ADHD and addiction share vulnerabilities in reward and executive function circuits. This common neural basis, along with high comorbidity rates, provides the neurological background that makes ADHD a risk factor for addiction."}, {"h": "Dilemma of medication misuse", "p": "Concerns that stimulants used for ADHD treatment may be misused are in tension with evidence that treatment lowers addiction risk. Balancing prescription management and appropriate treatment is a clinical challenge."}, {"h": "Problem of underdiagnosis", "p": "Especially when adult ADHD is underdiagnosed and left untreated, it can lead to self-medicative substance use. Accurate diagnosis becomes a pathway to addiction prevention."}]'::jsonb, updated_at=now() WHERE id='adhd-addiction';
UPDATE encyclopedia_terms SET definition_en='A mutual support group for family members and friends of individuals with addiction, helping them break free from codependency and care for their own lives. It demonstrates that recovery is not solely the task of the affected individual.', example_en='Example: A group where family members of an addicted person learn to take care of themselves and establish healthy boundaries.', body_en='[{"h": "What is it?", "p": "Al-Anon is a mutual support group for family members and friends of individuals with addiction, helping them break free from codependency and care for their own lives."}, {"h": "What does it address?", "p": "Rather than focusing on changing the addicted person, it teaches family members to set healthy boundaries and care for themselves. It emphasizes letting go of what one cannot control."}, {"h": "Why is it needed?", "p": "Addiction affects not only the individual but the entire family, and family members also need recovery. Al-Anon shows that recovery is not solely the task of the affected individual."}, {"h": "What should be considered?", "p": "Al-Anon demonstrates that family recovery is necessary independently of and in support of the affected individual''s recovery. It is a self-help resource addressing family burnout and codependency."}]'::jsonb, advanced_en='[{"h": "Institutionalization of family recovery", "p": "Al-Anon is a representative example of institutionalizing the recognition that families also need recovery. It aligns with the perspective that addiction is not just an individual issue but a family system problem."}, {"h": "Addressing codependency", "p": "Al-Anon helps families break free from codependency, where they become overly entangled in the addicted person''s problems. Healthy boundaries and self-care are key themes."}, {"h": "Relationship with family therapy", "p": "Family self-help groups like Al-Anon are complementary to professional family therapy. They form part of community-based recovery by transforming families into resources for recovery."}]'::jsonb, updated_at=now() WHERE id='al-anon';
UPDATE encyclopedia_terms SET definition_en='The most widely used and legal depressant, which impairs judgment and motor skills even in small amounts, and can lead to alcohol use disorder with repeated or excessive use. Socially accepted, so problem recognition is delayed, and withdrawal can be dangerous with seizures and delirium. It is one of the substances with the highest global disease burden.', example_en='Example: ''Everyone drinks'' alcohol, making it hard to admit the problem, a typical case where treatment is delayed.', body_en='[{"h": "What It Is", "p": "Alcohol is the most widely used and legal depressant, which impairs judgment and motor skills even in small amounts, and can lead to alcohol use disorder with repeated or excessive use. It is one of the substances with the highest global disease burden."}, {"h": "Why Problem Recognition Is Delayed", "p": "Alcohol is socially accepted and deeply embedded in daily life, so it takes a long time to recognize the problem and seek help. The perception that ''everyone drinks'' makes early intervention for alcohol use disorder difficult."}, {"h": "Dangers of Withdrawal", "p": "Alcohol withdrawal can be life-threatening with seizures and delirium (delirium tremens), representing a classic high-risk withdrawal. People who have drunk heavily for a long time should not stop abruptly but must do so under medical supervision."}, {"h": "Treatment", "p": "Alcohol use disorder is managed with psychotherapy, self-help groups, and medications (e.g., naltrexone, acamprosate). Early detection and a non-stigmatizing approach increase treatment entry."}]'::jsonb, advanced_en='[{"h": "Broad Health Burden", "p": "Alcohol is linked to a wide range of health and social harms, including liver disease, cancer, cardiovascular conditions, accidents, and violence. The common belief that ''moderate drinking is good for health'' has been challenged by recent evidence, and debate over safe drinking levels continues."}, {"h": "Policy Levers", "p": "Price (alcohol taxes), availability, and advertising regulation are considered effective policy levers to reduce alcohol-related harms. As a legal and universal substance, population-level policies play a greater role beyond individual treatment."}, {"h": "Social Costs", "p": "The social costs of alcohol extend beyond medical expenses to productivity loss, accidents, and family breakdown. Because of its legality, risks are underestimated, but the actual disease burden surpasses that of most illegal substances."}]'::jsonb, updated_at=now() WHERE id='alcohol';
UPDATE encyclopedia_terms SET definition_en='The world''s largest mutual aid group for alcohol recovery, founded in 1935, which helps members achieve sobriety through the 12 steps, sponsorship, and a community of meetings. It later became the prototype for numerous 12-step programs.', example_en='Example: A recovery community where members support each other''s sobriety through regular meetings and sponsor relationships.', body_en='[{"h": "What Is It", "p": "Alcoholics Anonymous (AA) is the world''s largest mutual aid group for alcohol recovery, founded in 1935, which helps members achieve sobriety through the 12 steps, sponsorship, and a community of meetings."}, {"h": "How It Works", "p": "Members share their stories at regular meetings and work through the 12 steps under the guidance of a sponsor who has already recovered. The core principle is that peers with shared experiences help each other."}, {"h": "What Makes It Special", "p": "It is led by peers rather than professionals, free of charge, and widely accessible. It provides a sense of belonging and identity restoration, and later became the prototype for numerous 12-step programs."}, {"h": "Limitations and Diversity", "p": "The spiritual framework may not suit everyone, so secular alternatives like SMART Recovery are also used. There is growing recognition that there is no single path to recovery."}]'::jsonb, advanced_en='[{"h": "Spread and Influence", "p": "AA served as the model for numerous 12-step groups such as NA and GA, and has had a profound impact on addiction recovery culture overall. It popularized the paradigm of mutual aid and peer recovery."}, {"h": "Evidence of Effectiveness", "p": "Long criticized as anecdotal, recent controlled studies report that AA and 12-step facilitation therapy are effective in maintaining sobriety. Participation level and sense of belonging are key factors in effectiveness."}, {"h": "Intersection with Faith Communities", "p": "The spiritual dimension of AA naturally aligns with faith-based recovery communities. Elements such as admitting powerlessness and relying on a higher power resonate with religious recovery narratives."}]'::jsonb, updated_at=now() WHERE id='alcoholics-anonymous';
UPDATE encyclopedia_terms SET definition_en='A theory explaining that repeated use shifts the brain''s reward-stress balance point itself, making substances necessary to feel normal. It conceptualizes the ''dark side'' of later-stage addiction, where motivation shifts from pleasure seeking to avoidance of discomfort.', example_en='Example: Initially used to feel good, but later used just to restore a disrupted baseline to normal.', body_en='[{"h": "What is it", "p": "Allostasis is a theory explaining that repeated use shifts the brain''s reward-stress balance point itself, making substances necessary to feel normal."}, {"h": "How does it work", "p": "Initially used to feel good, but with repetition, the brain''s baseline lowers. Later, a change occurs where the substance is used just to restore the disrupted baseline to normal."}, {"h": "The ''dark side''", "p": "This theory conceptualizes the ''dark side'' of later-stage addiction, where motivation shifts from pleasure seeking to avoidance of discomfort. The purpose of use becomes not euphoria but avoidance of suffering."}, {"h": "What it suggests", "p": "Allostasis provides a framework for understanding chronic dysphoria and craving in later-stage addiction, as well as anhedonia in early recovery. It shows that recovery is a time-consuming process that includes restoration of the baseline."}]'::jsonb, advanced_en='[{"h": "Beyond homeostasis", "p": "Unlike homeostasis (return to a fixed set point), allostasis involves a shift in the set point itself, leading to a new ''pathological equilibrium.'' It is the result of cumulative repeated neuroadaptations."}, {"h": "Opponent process and stress systems", "p": "This theory emphasizes the opponent process (counter-response) to reward and activation of brain stress systems (e.g., CRF). These changes create the negative affect and craving of withdrawal."}, {"h": "Koob''s contribution", "p": "This perspective, established by George Koob and others, illuminates the negative reinforcement (avoidance of suffering) dimension of addiction, complementing reward-centered models. It is a key axis for understanding later-stage addiction."}]'::jsonb, updated_at=now() WHERE id='allostasis';
UPDATE encyclopedia_terms SET definition_en='A class of stimulants that increase alertness and concentration, some of which are prescribed for ADHD and narcolepsy. They are useful at therapeutic doses but can lead to dependence, insomnia, and cardiovascular risks when misused. Non-medical use for academic or performance enhancement is a concern.', example_en='Example: A person misuses prescribed stimulants to concentrate during exams, eventually developing dependence and insomnia.', body_en='[{"h": "What Is It", "p": "Amphetamines are a class of stimulants that increase alertness and concentration, some of which are prescribed for ADHD and narcolepsy. They are useful at therapeutic doses but risky when misused."}, {"h": "Therapeutic Agent and Target of Abuse", "p": "Properly prescribed amphetamines are effective for ADHD treatment, and treatment itself may lower the risk of addiction. However, non-medical misuse for academic or performance enhancement is problematic."}, {"h": "Risks", "p": "Misuse can lead to dependence, insomnia, cardiovascular risks, anxiety, and psychosis. The risk increases with high doses and parenteral use."}, {"h": "What to Consider", "p": "Amphetamines are a substance where ''treatment'' and ''abuse'' diverge. A balance between legitimate therapeutic use and prevention of misuse is needed."}]'::jsonb, advanced_en='[{"h": "Treatment Reduces Risk", "p": "Untreated ADHD actually increases the risk of substance use, and appropriate stimulant treatment lowers that risk. This shows that the simple equation ''treatment drug = addiction trigger'' is incorrect."}, {"h": "Cognitive Enhancement Debate", "p": "Use of stimulants for ''cognitive enhancement'' in healthy individuals is controversial in terms of efficacy, ethics, and safety. Evidence suggests limited actual enhancement, and concerns exist about misuse driven by competitive pressure."}, {"h": "Balancing Prescription Management", "p": "A key clinical and policy challenge is balancing the prevention of misuse and diversion of stimulant prescriptions with ensuring access for legitimate patients. Both over- and under-prescribing are problematic."}]'::jsonb, updated_at=now() WHERE id='amphetamines';
UPDATE encyclopedia_terms SET definition_en='A male hormone-like substance misused for muscle growth. Unlike other addictions, it is driven not by immediate intoxication but by body image and performance compulsions. Discontinuation can cause depression, aggression, and other withdrawal-like symptoms, while long-term use harms the cardiovascular and hormonal systems.', example_en='Example: A person who, driven by an obsession with an ideal body, continues using steroids despite knowing the side effects and cannot stop.', body_en='[{"h": "What is it", "p": "Anabolic steroids are male hormone-like substances misused for muscle growth. Unlike other addictions, they are used not for immediate intoxication but due to compulsions related to body image and performance."}, {"h": "How is it different", "p": "A key feature is that use is driven by an obsession with an ''ideal body'' rather than pleasure-seeking. This often co-occurs with exercise addiction, eating disorders, and body dysmorphia."}, {"h": "Risks", "p": "Long-term use causes cardiovascular disease, hormonal disturbances, liver damage, and mental changes (aggression, mood swings). Discontinuation can lead to withdrawal-like symptoms such as depression and lethargy."}, {"h": "What to look for", "p": "Anabolic steroid misuse is intertwined with social pressures regarding appearance and performance. Understanding that body image compulsions underlie the inability to stop despite known side effects is the starting point for intervention."}]'::jsonb, advanced_en='[{"h": "Reward and body image", "p": "Anabolic steroids do not produce typical intoxication, but the strong reward from improved body image reinforces use. The addiction is unique in that the object is not the substance''s effect but the bodily changes it brings."}, {"h": "Relationship with muscle dysmorphia", "p": "A distorted body image of ''not being big enough'' (muscle dysmorphia) is identified as a psychological background for steroid misuse. This is understood as a mechanism similar to the body image distortion in eating disorders."}, {"h": "The flip side of health discourse", "p": "Health and fitness discourse, along with body image culture on social media, may encourage steroid misuse. It is necessary to view this not merely as an individual problem but in the context of social pressures on the body."}]'::jsonb, updated_at=now() WHERE id='anabolic-steroids';
UPDATE encyclopedia_terms SET definition_en='A state in which one cannot feel interest or pleasure in activities that were previously enjoyable. It is a core symptom of depression and commonly appears during withdrawal and early recovery from addiction, serving as a background for seeking intense stimuli and relapse. It is related to temporary desensitization of the reward circuit, and in early recovery, it manifests as the experience that ''nothing is fun,'' making it important to endure this period.', example_en='Example: A person a few weeks into abstinence feels numb toward previously enjoyed hobbies and thinks, ''What''s the point of living like this?''—a critical moment in early recovery.', body_en='[{"h": "What is it?", "p": "Anhedonia is a state in which one no longer feels pleasure from things that previously brought joy. It is a core symptom of depression and a significant experience in addiction and recovery processes."}, {"h": "Relationship with addiction", "p": "Repeated substance use desensitizes the reward system, leading to anhedonia where natural rewards feel meaningless. The motivation to fill this void with substances sustains use."}, {"h": "Critical moment in recovery", "p": "Anhedonia can be prominent in early recovery. The experience of ''I quit but nothing is enjoyable'' becomes a dangerous trigger for relapse, so understanding and enduring this period is important."}, {"h": "What is helpful to know?", "p": "Anhedonia usually recovers over time. Gradually rebuilding experiences of natural rewards (relationships, activities, achievements) helps restore the reward system."}]'::jsonb, advanced_en='[{"h": "Blunting of reward processing", "p": "Anhedonia is explained by blunting in the processes of predicting, experiencing, and learning rewards. In addiction, adaptation to strong artificial rewards results in weakened responses to natural rewards."}, {"h": "Predictor of relapse", "p": "Anhedonia in early recovery is an important predictor of relapse. The absence of pleasure can lead to doubts like ''What am I enduring for?'' and may lead to relapse."}, {"h": "Overlap with depression", "p": "Anhedonia is particularly prominent when addiction and depression co-occur, highlighting the need for integrated treatment addressing both. Recovery from anhedonia can also be an indicator of sustained recovery."}]'::jsonb, updated_at=now() WHERE id='anhedonia';
UPDATE encyclopedia_terms SET definition_en='A group of disorders characterized by excessive and persistent anxiety or fear that impairs daily functioning. They very commonly co-occur with addiction, and self-medication with substances or behaviors to soothe anxiety can become a pathway to addiction. When the two problems are intertwined, an integrated approach is needed.', example_en='Example: A person with social anxiety uses alcohol to calm nerves before every gathering, gradually becoming unable to endure interpersonal situations without alcohol.', body_en='[{"h": "What is it", "p": "Anxiety disorders are a group of mental disorders characterized by excessive and persistent anxiety or fear, and they very commonly co-occur with addiction."}, {"h": "How is it linked to addiction", "p": "A common pathway is self-medication, where individuals become dependent on substances (e.g., alcohol, sedatives) that relieve anxiety. Use that begins to soothe anxiety can lead to dependence."}, {"h": "Vicious cycle", "p": "Substances reduce anxiety in the short term, but withdrawal and rebound effects increase anxiety again. This cycle is especially pronounced with sedatives and alcohol, making it difficult to quit as anxiety worsens."}, {"h": "Implications for treatment", "p": "Integrated treatment addressing both anxiety and addiction is necessary. Learning skills to manage anxiety without substances (e.g., cognitive-behavioral therapy, relaxation, mindfulness) becomes part of recovery."}]'::jsonb, advanced_en='[{"h": "Typical self-medication pathway", "p": "Anxiety disorders are among the co-occurring conditions where the self-medication hypothesis fits best. Attempts to relieve the distress of anxiety with substances entangle the two problems."}, {"h": "The trap of sedative dependence", "p": "There is a paradox where benzodiazepines used to treat anxiety can themselves lead to dependence. Rebound anxiety makes it hard to discontinue, so short-term use and alternative treatments are emphasized."}, {"h": "Evidence for integrated treatment", "p": "Treating anxiety and addiction sequentially increases the risk of relapse, so integrated treatment addressing both simultaneously is recommended. Acquiring anxiety management skills is a key pathway to reducing substance dependence."}]'::jsonb, updated_at=now() WHERE id='anxiety-disorders';
UPDATE encyclopedia_terms SET definition_en='An attachment theory perspective on addiction, which posits that attachment styles formed in early relationships with caregivers shape emotional regulation and interpersonal patterns, and that insecure attachment is linked to addiction vulnerability. When the ability to find comfort in stable relationships is lacking, individuals may seek predictable solace in substances or behaviors rather than in people. This view emphasizes the role of trustworthy relationships and community in recovery.', example_en='Example: A person who has always felt anxious about relying on close others may find stability in alcohol or gaming, which respond in the same way every time, instead of in people.', body_en='[{"h": "What It Is", "p": "Attachment theory and addiction is a perspective that early attachment experiences with caregivers influence later emotional regulation and relational abilities, and that insecure attachment is linked to addiction vulnerability."}, {"h": "How They Are Connected", "p": "When secure attachment is not formed, the ability to self-soothe emotionally is weakened, and substances or behaviors may fill that gap. This view sees addiction as a ''substitute for relationships.''"}, {"h": "What It Suggests", "p": "The perspective that addiction is related to a lack of stable human connection suggests that recovery must include the restoration of relationships and belonging. It aligns with the insight that ''the opposite of addiction is connection.''"}, {"h": "Implications for Treatment", "p": "The attachment perspective emphasizes that the therapeutic relationship itself can be a corrective experience. Relearning emotional regulation within a safe relationship becomes part of recovery."}]'::jsonb, advanced_en='[{"h": "Development of Emotional Regulation", "p": "Attachment theory emphasizes that emotional regulation abilities develop in early relationships. When self-soothing capacity is poorly formed due to insecure attachment, vulnerability to relying on external substances for emotional regulation emerges."}, {"h": "Recovery as Connection", "p": "From this perspective, recovery is a process of replacing the relationship with substances with stable relationships with people and community. It explains why a sense of belonging in recovery communities has therapeutic power."}, {"h": "Intersection with Trauma", "p": "Attachment damage is often intertwined with childhood trauma, so the attachment perspective meets trauma-informed approaches. It suggests integrated recovery that addresses relationships, emotions, and trauma together."}]'::jsonb, updated_at=now() WHERE id='attachment-addiction';
UPDATE encyclopedia_terms SET definition_en='A depressant historically widely used for sedation, sleep, and anticonvulsant purposes, with a narrow margin between safe and lethal doses, posing a high risk of overdose. Its use has significantly declined since the introduction of benzodiazepines, but it remains for some medical purposes. Characterized by strong physical dependence and dangerous withdrawal.', example_en='Example: A class with a narrow therapeutic range, where even a slightly higher dose can be dangerous, leading to its replacement in modern times.', body_en='[{"h": "What Is It", "p": "Barbiturates are depressants historically widely used for sedation, sleep, and anticonvulsant purposes, enhancing GABA activity. The margin between safe and lethal doses is narrow, posing a high risk of overdose."}, {"h": "Why Were They Replaced", "p": "The narrow therapeutic range means even a slightly higher dose can be dangerous, and they cause strong physical dependence and dangerous withdrawal. This led to a significant decline in use after the introduction of safer benzodiazepines."}, {"h": "Current Uses", "p": "Today, barbiturates remain only for limited medical purposes such as some anticonvulsant and anesthetic uses. Their significance as a substance of abuse has greatly diminished compared to the past."}, {"h": "What to Remember", "p": "Barbiturates are an example in psychopharmacology history of ''safer drugs replacing older ones.'' They also illustrate how a narrow safety margin can be lethal."}]'::jsonb, advanced_en='[{"h": "Narrow Therapeutic Index", "p": "Barbiturates have a close proximity between effective and lethal doses, making accidental or combined use easily lead to fatal overdose. This characteristic is a key reason for their replacement by benzodiazepines."}, {"h": "Risk of Withdrawal", "p": "As a depressant class, barbiturate withdrawal can be life-threatening, including seizures, necessitating medical management during discontinuation."}, {"h": "Historical Significance", "p": "The rise and fall of barbiturates illustrate the development of drug safety evaluation and regulation, emphasizing the importance of safety margins in subsequent psychopharmacology drug development."}]'::jsonb, updated_at=now() WHERE id='barbiturates';
UPDATE encyclopedia_terms SET definition_en='A behavioral addiction is compulsive, out-of-control engagement in a behavior—gambling, gaming, shopping, sex, internet use—despite mounting harm, with no substance involved. It can produce craving, tolerance, withdrawal-like distress and relapse much like substance addiction, and it engages the same brain reward circuitry. So far only gambling disorder and gaming disorder are formally recognized (ICD-11); the rest remain under study.', example_en='Someone who cannot stop gambling shows the same structure as a substance user: rising ''doses,'' failed attempts to quit, and distress when they stop.', body_en='[{"h": "What it is", "p": "Behavioral addiction refers to losing control over a specific behavior—gambling, gaming, shopping, sex, internet use—and repeating it compulsively without any substance involved. The core issue is not the type of behavior but the loss of control. Something once enjoyed crosses into addiction when a person feels anxious without it and cannot stop despite knowing it is harmful."}, {"h": "What it shares with substance addiction", "p": "Behavioral addiction closely resembles substance addiction. It shows the same need for ever-stronger stimulation (tolerance), restlessness when stopped (a withdrawal-like response), repeated relapse, and involvement of the brain''s reward circuitry. As these parallels accumulated, the concept of addiction expanded from substances to behaviors."}, {"h": "Where the line falls", "p": "Not all absorption is addiction. Being passionately engaged differs from losing control and watching life fall apart. The test is not how much time is spent but functional impairment—whether work, relationships, health, and finances actually collapse, and whether one can stop. Because of this, the same hours may be a hobby for one person and a disorder for another."}, {"h": "How to view it", "p": "Behavioral addiction cannot be reduced to a matter of willpower. Reward learning in the brain, failures of stress coping, and environments (apps and industries) engineered to induce the behavior all work together. Recovery therefore requires not just resolve but alternative coping, environmental adjustment, and supportive relationships."}]'::jsonb, advanced_en='[{"h": "Diagnostic status and boundaries", "p": "Currently only gambling disorder (DSM-5, ICD-11) and gaming disorder (ICD-11) are officially recognized behavioral addictions. Shopping, sex, and internet use are addressed clinically and in research but are not established as independent diagnoses. This reflects scholarly caution against the concept inflation implied by ''anything in excess is addiction.'' How far to extend the disease label remains actively debated."}, {"h": "Shared mechanisms and debate", "p": "Behavioral addiction is explained through reward prediction and incentive salience, a shift from impulsivity to compulsivity (dual-process), and negative reinforcement (escaping distress). Yet there is disagreement over whether it involves the same neural damage as substances or merely similar learning patterns. Critics warn that over-pathologizing risks turning normal passion into disease."}, {"h": "Lived-experience and social view", "p": "Many behavioral addictions progress ''in secret,'' leaving no physical trace and wearing socially accepted disguises (investment, diligence, hobby). This delays both the person''s own recognition and others'' awareness. At the same time, there is growing insistence that the responsibility of environments designed to keep people repeating—the attention economy, the gambling industry—should not be reduced to individual pathology."}]'::jsonb, updated_at=now() WHERE id='behavioral-addiction';
UPDATE encyclopedia_terms SET definition_en='A phenomenon in which repeated exposure to a specific stimulus amplifies the response, opposite to tolerance (which reduces response). It explains how the ''wanting'' system becomes sensitized, intensifying craving and leaving individuals vulnerable to cues even after prolonged abstinence. A core concept of the incentive salience theory.', example_en='Example: A person who has been abstinent for years experiences a sudden re-exposure and is overwhelmed by stronger craving than before, leading to rapid relapse.', body_en='[{"h": "What is it", "p": "Behavioral sensitization is a phenomenon where repeated exposure to a specific stimulus strengthens the response. Opposite to tolerance (reduced response), some responses amplify over time."}, {"h": "How does it appear in addiction", "p": "With repeated use of substances like stimulants, sensitization occurs in ''wanting'' for the substance and cues, as well as motor and emotional responses. This persists long-term, increasing relapse vulnerability."}, {"h": "Coexistence with tolerance", "p": "For the same substance, some responses become blunted (tolerance) while others strengthen (sensitization). Sensitization of ''wanting'' is understood to drive craving."}, {"h": "What does it imply", "p": "Sensitization explains why strong craving can resurface upon cue exposure even after long abstinence. It supports the idea that recovery is not a ''cure'' but requires ongoing management."}]'::jsonb, advanced_en='[{"h": "Incentive sensitization theory", "p": "Robinson and Berridge''s incentive sensitization theory posits that repeated use sensitizes the neural circuits responsible for ''wanting,'' creating intense craving independent of liking. It is a key theory explaining why addiction involves wanting without pleasure."}, {"h": "Persistence", "p": "Sensitization is long-lasting and can be reactivated by cues even after prolonged abstinence. This persistence is considered the neural basis of relapse vulnerability."}, {"h": "Individual differences", "p": "The degree of sensitization varies greatly among individuals depending on genetics, environment, and substance. This variation partly explains why some people are more prone to addiction and relapse."}]'::jsonb, updated_at=now() WHERE id='behavioral-sensitization';
UPDATE encyclopedia_terms SET definition_en='An 18th–19th century American physician who was an early figure to view chronic heavy drinking not as moral corruption but as a kind of disease. He is cited as a historical pioneer of the disease understanding of addiction.', example_en='Example: A very early historical root of the view that addiction is a disease.', body_en='[{"h": "Who He Was", "p": "Benjamin Rush was an 18th–19th century American physician who was an early figure to view chronic heavy drinking not as moral corruption but as a kind of disease."}, {"h": "What He Did", "p": "Against the dominant moral perspective of his time, he sought to understand habitual heavy drinking as a disease state difficult to control by willpower. He planted the very early seeds of the medical understanding of addiction."}, {"h": "Why He Matters", "p": "Rush is cited as a historical pioneer of the view that addiction is a disease. The shift from morality to medicine had already begun with him."}, {"h": "What He Left Behind", "p": "His insights became the starting point of a long trajectory leading to Jellinek and the modern disease model. He is a figure who shows the historical roots of understanding addiction."}]'::jsonb, advanced_en='[{"h": "Distant Origins of the Disease Model", "p": "Benjamin Rush is cited as a very early historical root of the disease model of addiction. His perspective was ahead of its time but was not widely accepted in his era."}, {"h": "Historical Context", "p": "Rush''s views emerged in the context of Enlightenment medicine. Some of his other medical views are outdated by today''s standards, but his insight into addiction was pioneering."}, {"h": "From Morality to Medicine", "p": "Rush''s significance lies in his shift in perspective, viewing addiction not as a moral failure but as a condition requiring treatment. This shift would develop over subsequent centuries."}]'::jsonb, updated_at=now() WHERE id='benjamin-rush';
UPDATE encyclopedia_terms SET definition_en='A class of sedatives used to treat anxiety, insomnia, and seizures, which enhance GABA activity to produce rapid calming effects. While useful in the short term, tolerance and dependence develop quickly, and withdrawal can be dangerous, so long-term and high-dose use requires caution. Concurrent use with opioids is a major factor in overdose deaths.', example_en='Example: A person prescribed benzodiazepines for anxiety relief finds that when trying to stop, rebound anxiety and insomnia worsen, leading to continued use.', body_en='[{"h": "What is it", "p": "Benzodiazepines are a class of sedatives used to treat anxiety, insomnia, and seizures. They enhance GABA activity to produce rapid calming effects. While useful in the short term, they carry a risk of dependence."}, {"h": "Why caution is needed", "p": "Tolerance and dependence develop relatively quickly, and after long-term or high-dose use, discontinuation can lead to rebound anxiety, insomnia, and dangerous withdrawal symptoms such as seizures. Therefore, short-term use at the lowest effective dose is recommended."}, {"h": "Risks of concurrent use", "p": "When used together with opioids or alcohol, respiratory depression is compounded, significantly increasing the risk of overdose death. Benzodiazepines are commonly involved in opioid overdose fatalities."}, {"h": "Safe use", "p": "Benzodiazepines should be used for short periods at the lowest effective dose, and discontinuation should be gradual under medical supervision. Long-term users should avoid abrupt cessation."}]'::jsonb, advanced_en='[{"h": "Mechanism and tolerance", "p": "Benzodiazepines enhance the action of GABA-A receptors, and repeated use leads to receptor adaptation, resulting in tolerance. This adaptation is the biological basis for rebound symptoms and withdrawal."}, {"h": "Problems with long-term prescribing", "p": "Long-term prescribing for anxiety and insomnia often leads to dependence, a clinical issue known as ''prescribed dependence.'' In older adults, risks of falls and cognitive impairment increase."}, {"h": "Deprescribing", "p": "Deprescribing—helping long-term users safely taper and discontinue benzodiazepines—has emerged as a clinical priority. Due to the risks of abrupt cessation, a systematic and gradual tapering strategy is emphasized."}]'::jsonb, updated_at=now() WHERE id='benzodiazepines';
UPDATE encyclopedia_terms SET definition_en='Co-founder of Alcoholics Anonymous (AA), who established the 12-step and mutual aid model based on his own recovery experience. He is a symbolic figure in the movement that regards lived experience as a core resource for recovery.', example_en='Example: A case of starting from one''s own recovery experience and laying the foundation for a global recovery movement.', body_en='[{"h": "Who He Is", "p": "Bill Wilson (Bill W.) is the co-founder of Alcoholics Anonymous (AA), who established the 12-step and mutual aid model based on his own recovery experience."}, {"h": "What He Did", "p": "After suffering from alcohol problems and experiencing recovery, he established the principle of mutual aid, where one alcoholic helps another. This principle became the foundation of AA and the 12 steps."}, {"h": "Why He Is Important", "p": "Bill W. is a symbol of the movement that regards the recovery experience of the person themselves as a core resource for recovery. He pioneered a model where a recovered person, not a professional, helps the next person."}, {"h": "What He Left Behind", "p": "The mutual aid model he established became the foundation of a global recovery movement and later expanded into numerous 12-step programs. It is a case where an individual''s recovery experience became a social movement."}]'::jsonb, advanced_en='[{"h": "Symbol of Experience-Based Recovery", "p": "Bill W. is a symbol of the paradigm that ''recovery experience,'' not ''expert knowledge,'' can aid recovery. This is the root of today''s peer support and recovery coaching."}, {"h": "Spiritual Awakening and Jung''s Influence", "p": "His recovery narrative centers on spiritual awakening, and Carl Jung''s views are known to have influenced him. This spiritual dimension shaped the character of AA."}, {"h": "Legacy and Limitations", "p": "Bill W.''s model had a tremendous impact, but it also left limitations in that the spiritual framework does not suit everyone. Discussions on the diversity of recovery pathways are also reflections on his legacy."}]'::jsonb, updated_at=now() WHERE id='bill-w';
UPDATE encyclopedia_terms SET definition_en='A phenomenon during drinking in which the person is conscious but no memory is formed for that period, caused by alcohol disrupting memory storage in the hippocampus. Failure to recall dangerous situations can lead to safety issues.', example_en='Example: A person who converses and moves around during a drinking session but the next day has no memory of that time.', body_en='[{"h": "What is it", "p": "Blackout (film break) is a phenomenon during drinking in which the person is conscious but no memory is formed for that period. It occurs because alcohol disrupts memory storage in the hippocampus."}, {"h": "How does it manifest", "p": "The person engages in actions such as conversation and movement, but the next day has no memory of that time. There are cases of partial memory fragmentation and complete memory loss."}, {"h": "Why is it dangerous", "p": "During a blackout, the person cannot remember dangerous situations, which can lead to safety issues. Actions taken while judgment and memory are impaired can result in accidents and harm."}, {"h": "What does it signify", "p": "A blackout is a sign that blood alcohol has risen rapidly, and repeated blackouts may indicate risky drinking patterns and alcohol-related problems."}]'::jsonb, advanced_en='[{"h": "Blocking of memory formation", "p": "Blackout occurs because alcohol disrupts the storage (consolidation) of long-term memory in the hippocampus. Consciousness and short-term memory are maintained, but new memories are not stored."}, {"h": "Rapid rise in blood alcohol concentration", "p": "Blackout is more likely when blood alcohol concentration rises rapidly. The risk increases when drinking quickly on an empty stomach or binge drinking."}, {"h": "Significance as a risk indicator", "p": "Frequent blackouts are associated with the risk of alcohol use disorder and are considered a warning sign, especially in binge drinking among young people. They are also directly linked to safety and legal issues."}]'::jsonb, updated_at=now() WHERE id='blackout';
UPDATE encyclopedia_terms SET definition_en='This field addresses how addiction alters the functions of multiple brain regions, including reward (nucleus accumbens), motivation, judgment/inhibition (prefrontal cortex), memory/habit (hippocampus/striatum), and emotion (amygdala). In particular, the weakening of inhibitory control in the prefrontal cortex, where the judgment to stop fails to overcome impulses, provides a neurological explanation for loss of control. The interplay of heightened reward, reduced inhibition, and increased stress response solidifies the addiction circuit.', example_en='Example: A situation where a person clearly knows the risk of relapse but cannot suppress impulses in the presence of cues is explained by reduced inhibitory function of the prefrontal cortex.', body_en='[{"h": "What is it", "p": "Addiction is a state in which the brain''s reward, motivation, control, and habit circuits are transformed by repeated use. It is understood not as a change in a single region but as alterations in the interactions of multiple circuits."}, {"h": "Which circuits change", "p": "The circuits involved in reward, stress/emotion, impulse inhibition (prefrontal cortex), and habit automation all change together. Reward becomes blunted, control weakens, and habits become stronger."}, {"h": "Why is control difficult", "p": "The function of the prefrontal cortex, which inhibits impulses, weakens, while responses to substances and cues become stronger. This imbalance creates a state where it is difficult to stop despite wanting to."}, {"h": "Recovery and the brain", "p": "Thanks to brain plasticity, when substance use stops and new experiences are accumulated, the brain gradually recovers. However, this takes time, and early recovery symptoms such as anhedonia and cognitive decline are part of this recovery process."}]'::jsonb, advanced_en='[{"h": "Three-stage circuit model", "p": "A widely used model explains addiction through three stages: binge/intoxication (reward), withdrawal/negative affect (stress), and preoccupation/anticipation (executive function). Each stage is associated with different brain regions and neurotransmitters."}, {"h": "Weakening of prefrontal control", "p": "Repeated use weakens the function of the prefrontal cortex, which is responsible for judgment and inhibition. This weakening is identified as a key mechanism underlying loss of control in the face of strong cravings."}, {"h": "Debate on the disease model", "p": "The view that addiction is a brain disease has reduced stigma and justified treatment, but it has also been criticized for underestimating personal agency, recovery potential, and social factors. An integrated perspective that combines brain changes with learning and context is needed."}]'::jsonb, updated_at=now() WHERE id='brain-addiction';
UPDATE encyclopedia_terms SET definition_en='A partial opioid agonist that controls craving and withdrawal with a relatively lower risk of overdose, widely used in the treatment of opioid use disorder. It can be prescribed in outpatient settings, offering high accessibility.', example_en='Example: Managing opioid dependence with buprenorphine prescribed in an outpatient clinic outside the hospital.', body_en='[{"h": "What Is It", "p": "Buprenorphine is a partial opioid agonist that controls craving and withdrawal with a relatively lower risk of overdose, widely used in the treatment of opioid use disorder. It can be prescribed in outpatient settings, offering high accessibility."}, {"h": "Why Is It Safer", "p": "Buprenorphine acts only partially on opioid receptors, producing a ceiling effect where effects do not increase beyond a certain dose. This results in a relatively lower risk of respiratory depression and overdose, allowing for prescription and management in outpatient settings outside the hospital."}, {"h": "What Are the Benefits", "p": "Unlike methadone, which requires daily clinic visits, buprenorphine can be prescribed for outpatient use, offering advantages in accessibility and maintaining daily routines. Formulations combined with naloxone are designed to deter misuse. This accessibility helps lower the threshold for treatment."}, {"h": "Significance", "p": "Buprenorphine has emerged as a key accessible treatment in the response to the opioid crisis. Policies such as easing prescribing restrictions and expanding telemedicine prescriptions are being pursued to broaden access to this medication."}]'::jsonb, advanced_en='[{"h": "Pharmacological Properties", "p": "Buprenorphine is a partial agonist at opioid receptors with strong binding affinity, which also blocks the effects of other opioids. Therefore, the timing of administration (starting after withdrawal has begun) is important; incorrect timing can precipitate acute withdrawal."}, {"h": "Accessibility Policies", "p": "The strength of buprenorphine lies in its outpatient accessibility. Many countries are easing prescribing requirements and allowing remote prescriptions to reduce treatment gaps. This is central to the strategy of ''bringing treatment closer to people'' in the overdose crisis response."}, {"h": "Debates Surrounding Maintenance Therapy", "p": "Similar to methadone, there are differing perspectives on whether buprenorphine maintenance therapy constitutes ''full recovery.'' The tension between the harm reduction perspective, which prioritizes preserving life and function, and the abstinence-oriented perspective is also evident here."}]'::jsonb, updated_at=now() WHERE id='buprenorphine';
UPDATE encyclopedia_terms SET definition_en='Caffeine is the most widely used psychoactive substance in the world, a mild stimulant that increases alertness. Generally safe, but dependence and tolerance can develop, and cessation may cause withdrawal symptoms such as headache and fatigue. The DSM recognizes caffeine intoxication and withdrawal, but ''caffeine use disorder'' is listed as a condition requiring further research.', example_en='Example: A person who regularly drinks several cups daily experiences severe headache and lethargy after skipping a day—caffeine withdrawal.', body_en='[{"h": "What Is It", "p": "Caffeine is the most widely used psychoactive substance in the world, a mild stimulant that increases alertness. It is found in coffee, tea, energy drinks, etc., and is consumed safely by most people."}, {"h": "Dependence and Withdrawal", "p": "Regular consumption leads to tolerance and dependence; abrupt cessation causes withdrawal symptoms such as headache, fatigue, irritability, and difficulty concentrating. This shows that caffeine, though mild, is a genuine psychoactive substance."}, {"h": "Diagnostic Status", "p": "The DSM recognizes caffeine intoxication (acute) and caffeine withdrawal, but ''caffeine use disorder'' is listed as a condition requiring further research. Most use is not problematic, but some individuals experience difficulty controlling intake."}, {"h": "What to Know", "p": "Excessive caffeine can cause anxiety, insomnia, and palpitations; high-dose consumption in energy drinks is a concern especially among adolescents. To ease withdrawal, gradual reduction is recommended."}]'::jsonb, advanced_en='[{"h": "Adenosine Blockade", "p": "Caffeine blocks adenosine receptors that promote sleepiness, thereby increasing alertness. Repeated consumption leads to receptor upregulation, an adaptation that underlies tolerance and withdrawal headache."}, {"h": "Touchstone for Addiction Models", "p": "Caffeine, being widely used with clear dependence and withdrawal, serves as a touchstone for debating ''what constitutes addiction.'' It illustrates that dependence does not necessarily mean disorder."}, {"h": "Public Health Concerns", "p": "The high caffeine and sugar content of energy drinks and their consumption by adolescents have emerged as public health concerns. The risk of mixing with alcohol is also noted."}]'::jsonb, updated_at=now() WHERE id='caffeine';
UPDATE encyclopedia_terms SET definition_en='Canada''s supervised consumption sites (SCS) are harm reduction facilities where individuals can use pre-obtained drugs under the supervision of trained professionals. The first North American site, Insite, opened in Vancouver in 2003, and the model expanded to several provinces, though recent moves to reduce or close sites in some provinces have sparked debate.', example_en='At Vancouver''s Insite, a person uses their own drugs in a hygienic environment, receives immediate emergency response in case of overdose, and is connected to treatment and housing services.', body_en='[{"h": "What is it?", "p": "Supervised consumption sites (SCS) are facilities where individuals can use pre-obtained drugs in a hygienic environment under the supervision of trained professionals. The sites do not provide drugs; they serve as a point of contact to reverse overdoses immediately, prevent infections, and connect people to treatment and social services."}, {"h": "How does it work?", "p": "In 2003, North America''s first SCS, Insite, opened in Vancouver''s Downtown Eastside. Under Canadian criminal law, an exemption from the Controlled Drugs and Substances Act applies within the facility, but possession outside remains illegal. Users consume safely inside, receive emergency care for overdoses, and can be linked to treatment, housing, and medical services if desired."}, {"h": "What effects has it had?", "p": "Studies report that Insite has reduced overdose deaths and HIV infections, decreased public drug use and discarded syringes, and generated significant healthcare cost savings. Its core value is serving as a low-stigma point of contact that connects vulnerable users to services."}, {"h": "Recent debates", "p": "Despite evidence of effectiveness, some provinces like Ontario have recently moved to reduce or close sites. Concerns about neighborhood disorder and safety, along with criticism that sites prioritize maintenance over recovery, have driven political reversals. The debate over balancing harm reduction and recovery-oriented approaches is particularly acute in Canada."}]'::jsonb, advanced_en='[{"h": "Evidence and cost-effectiveness", "p": "Research on Insite has shown reductions in nearby overdose deaths and large healthcare cost savings through HIV prevention. However, recent studies examining the relationship between safer supply, decriminalization policies, and overdose outcomes have yielded mixed results, leaving the interpretation of policy effects still contested."}, {"h": "Tension between harm reduction and recovery", "p": "At the heart of Canada''s debate is the observation that ''harm reduction specialists and recovery specialists come from different schools.'' The key issue is where to allocate resources—saving lives or guiding people toward recovery—and how to balance the two. Both sides agree that neither approach alone is sufficient."}, {"h": "Safer supply experiment", "p": "To prevent deaths from contaminated illegal drugs (e.g., fentanyl), Canada has also experimented with ''safer supply,'' providing regulated drugs by prescription. However, ongoing debates over its effectiveness and side effects (such as diversion) present a new challenge for harm reduction policy."}]'::jsonb, updated_at=now() WHERE id='canada-scs';
UPDATE encyclopedia_terms SET definition_en='A group of substances derived from the cannabis plant (e.g., THC, CBD) and related compounds that act on the brain''s endogenous cannabinoid receptors. THC produces intoxication and perceptual changes, while CBD has non-intoxicating effects. Synthetic cannabinoids pose additional risks due to their unpredictable and potent toxicity.', example_en='Example: Synthetic cannabinoids, which are much stronger and more dangerous than natural cannabis, can cause unexpected acute poisoning.', body_en='[{"h": "What Are They?", "p": "Cannabinoids are substances derived from the cannabis plant (e.g., THC, CBD) and related compounds that act on the brain''s endogenous cannabinoid receptors. THC produces intoxication, while CBD has non-intoxicating effects."}, {"h": "Natural vs. Synthetic", "p": "In addition to natural cannabinoids (cannabis components), there are synthetic cannabinoids created in laboratories. Synthetic products have unpredictable and potent effects, and can cause acute toxicity that is entirely different from natural cannabis."}, {"h": "Risks of Synthetic Cannabinoids", "p": "Synthetic cannabinoids, once marketed as ''legal cannabis,'' have frequently caused severe psychosis, seizures, and emergency situations. Their constantly changing chemical compositions make risk prediction and regulation difficult."}, {"h": "What to Consider", "p": "Cannabinoids span a wide spectrum from medical potential (e.g., CBD) to serious risks (e.g., synthetic products). It is important to distinguish between natural and synthetic forms, as risks vary greatly by component."}]'::jsonb, advanced_en='[{"h": "The Endocannabinoid System", "p": "The body has a regulatory system composed of naturally produced cannabinoids and their receptors (CB1 and CB2), which modulate appetite, pain, mood, and memory. External cannabinoids act on this system to produce various effects."}, {"h": "Regulatory Cat-and-Mouse Game with Synthetic Cannabinoids", "p": "Synthetic cannabinoids are a representative class of novel psychoactive substances that emerge with altered chemical structures to evade regulation. This ''cat-and-mouse'' dynamic, where regulation always lags behind, amplifies risks."}, {"h": "The Rise of CBD", "p": "The non-intoxicating component CBD has gained attention for its therapeutic use in certain conditions like epilepsy. However, the quality and content of CBD products on the market vary widely, highlighting a gap between evidence and marketing."}]'::jsonb, updated_at=now() WHERE id='cannabinoids';
UPDATE encyclopedia_terms SET definition_en='An entry on cannabis and its main components (THC, CBD), with medical and recreational legalization in many countries and regions forming a global trend. At the same time, advances in cultivation and extraction technology have significantly increased THC concentrations in products compared to the past, raising concerns about cannabis use disorder, effects on adolescent brain development, and risk of psychosis. Policy debates over the social and health effects of legalization are active.', example_en='Example: Cases of adolescents in legalized regions who are exposed early to high-potency products and experience difficulty in controlling their use.', body_en='[{"h": "What is it", "p": "Cannabis is a plant containing THC, CBD, and other compounds. THC produces intoxication and perceptual changes, while CBD has non-intoxicating effects. Many countries and regions are moving toward legalizing medical and recreational use, a global trend."}, {"h": "Legalization trends", "p": "Legalization, starting with medical use and expanding to recreational use, has progressed in North America and elsewhere. The goals include reducing the harms of criminal penalties and regulating and taxing the market, but the social and health effects are evaluated differently depending on the region and time period."}, {"h": "Increased THC potency", "p": "Advances in cultivation and extraction technology have significantly increased THC concentrations in products compared to the past. This raises concerns about cannabis use disorder, effects on adolescent brain development, and risk of psychosis, leading to the argument that ''today''s cannabis is different from before.''"}, {"h": "What to consider", "p": "There is a coexistence of the perception that cannabis is relatively low-risk and concerns about the dangers of high-potency and early use. A balanced perspective is needed, weighing the benefits of legalization (reduced criminal penalties, ability to regulate) against the risks (increased use, effects on adolescents)."}]'::jsonb, advanced_en='[{"h": "Cannabis use disorder", "p": "Cannabis can also cause use disorder, with risk particularly high in early, frequent, and high-potency use. Contrary to the common belief that it is ''not addictive,'' withdrawal and loss of control can occur, which is clinically emphasized."}, {"h": "Psychosis debate", "p": "Associations between early, frequent use of high-potency THC and risk of psychosis have been reported, but there is debate over whether this is causal or an expression of vulnerability. Interaction with genetic and environmental vulnerability is identified as a key variable."}, {"h": "Natural experiments of legalization", "p": "Legalization in various regions provides ''natural experiments'' to observe policy effects. Results vary across indicators such as adolescent use, accidents, tax revenue, and reduction of illegal markets, requiring multifaceted evaluation rather than simple success/failure narratives."}]'::jsonb, updated_at=now() WHERE id='cannabis';
UPDATE encyclopedia_terms SET definition_en='A depth psychologist whose view that spiritual conversion may be necessary for recovery from alcohol addiction is known to have influenced the formation of Alcoholics Anonymous (AA). He is cited as a figure who suggested the connection between addiction and spirituality/meaning.', example_en='Example: The intellectual background suggesting the importance of meaning and spiritual dimensions in addiction recovery.', body_en='[{"h": "Who is he?", "p": "Carl Jung was a depth psychologist whose view that spiritual conversion may be necessary for recovery from alcohol addiction is known to have influenced the formation of AA."}, {"h": "What did he do?", "p": "He is reported to have conveyed to a patient with alcohol addiction that spiritual awakening beyond medical treatment might be necessary for recovery. This idea influenced the early formation of AA."}, {"h": "Why is it important?", "p": "Jung''s view suggests the importance of meaning and spiritual dimensions in addiction recovery. It illuminates that recovery can be a life transformation, not merely symptom removal."}, {"h": "What did he leave behind?", "p": "Through Jung, the connection between addiction and spirituality/meaning entered the recovery discourse. This became the intellectual background for the spiritual dimension of the 12 steps and faith-based recovery."}]'::jsonb, advanced_en='[{"h": "Connection between spirituality and recovery", "p": "Jung''s view illuminates the role of spiritual and meaning dimensions in addiction recovery. It suggests aspects of recovery that are not reducible to a purely medical perspective."}, {"h": "Indirect influence on AA", "p": "Jung''s view is reported to have influenced the formation of AA''s spiritual framework through Bill W. This is an interesting point where depth psychology and the recovery movement meet."}, {"h": "Recovery of meaning", "p": "Jung''s perspective sees recovery as a restoration of meaning and wholeness beyond symptom removal. This resonates with modern views that understand recovery as rebuilding one''s life."}]'::jsonb, updated_at=now() WHERE id='carl-jung';
UPDATE encyclopedia_terms SET definition_en='A powerful stimulant extracted from coca leaves, producing a short, intense euphoria followed by a rapid crash that drives repeated use. The smoked form (crack) has a faster, stronger effect with higher dependence risk. There is a high risk of cardiovascular complications and acute psychosis.', example_en='Example: A pattern where intense euphoria ends quickly and is immediately followed by a crash, leading to repeated use to fill the gap.', body_en='[{"h": "What is it", "p": "Cocaine is a powerful stimulant extracted from coca leaves, producing a short, intense euphoria. The smoked form (crack) has a faster, stronger effect with higher dependence risk."}, {"h": "How it works", "p": "Cocaine provides a brief, intense euphoria followed by a rapid crash. This gap drives repeated use, and the short duration encourages frequent re-administration."}, {"h": "Risks", "p": "There is a high risk of cardiovascular complications (arrhythmia, cardiac arrest, stroke) and acute psychosis. Repeated use leads to psychological dependence and cognitive/psychiatric problems."}, {"h": "Treatment gap", "p": "For cocaine, a stimulant, there is no approved effective pharmacotherapy, so behavioral treatments like contingency management are considered the most evidence-based approach. Psychosocial support is central to recovery."}]'::jsonb, advanced_en='[{"h": "Dopamine reuptake blockade", "p": "Cocaine blocks dopamine reuptake, causing a surge in synaptic dopamine. This intense, brief dopamine spike is the neural basis for strong reward and frequent re-use."}, {"h": "Crack and social stigma", "p": "The crack epidemic of the 1980s generated intense social fear and punitive policies, criticized for resulting in racially and class-disparate criminal penalties. Cocaine is entangled in debates about equity in drug policy."}, {"h": "Polysubstance use risks", "p": "Using cocaine with opioids (speedball) is particularly dangerous due to opposing effects. Recently, combined use of stimulants and fentanyl has emerged as a new threat."}]'::jsonb, updated_at=now() WHERE id='cocaine';
UPDATE encyclopedia_terms SET definition_en='A relationship pattern in which a person closely connected to an individual with addiction becomes excessively entangled in that person''s problems, sacrificing their own needs and, as a result, inadvertently perpetuating the addictive behavior. It manifests as over-caregiving, taking on responsibilities, or covering up problems, which deprives the individual of the opportunity to face the consequences. This highlights the need for recovery that involves the entire family.', example_en='Example: A family member repeatedly pays off gambling debts, preventing the individual from facing the consequences and allowing the behavior to continue.', body_en='[{"h": "What is it", "p": "Codependency is a relationship pattern in which a person closely connected to an individual with addiction becomes excessively entangled in that person''s problems, sacrificing their own needs and unintentionally perpetuating the addiction."}, {"h": "How does it manifest", "p": "Typical behaviors include taking on responsibilities for the person with addiction, covering up problems, and repeatedly cleaning up after them. Helping in this way actually deprives the individual of the opportunity to face the consequences."}, {"h": "Why is it a problem", "p": "Codependency not only hinders the recovery of the person with addiction but also undermines the family member''s own life and health. Caregiving can deteriorate into self-exhaustion and control."}, {"h": "How is it addressed", "p": "Recovery involves setting healthy boundaries, taking care of oneself, and letting go of what cannot be controlled. Self-help groups like Al-Anon and family therapy can be helpful."}]'::jsonb, advanced_en='[{"h": "Usefulness and limitations of the concept", "p": "Codependency is a useful concept for highlighting the difficulties of family members, but it has been criticized for being applied too broadly, pathologizing normal caregiving. Careful use is required."}, {"h": "Enabling", "p": "Enabling, a core behavior of codependency, illustrates the paradox that well-intentioned help can perpetuate addiction. Changing the way help is provided is key to supporting recovery."}, {"h": "Family recovery and community", "p": "The concept of codependency emphasizes that families also need recovery. This leads to the need for family therapy, family self-help groups, and recovery communities that embrace families."}]'::jsonb, updated_at=now() WHERE id='codependency';
UPDATE encyclopedia_terms SET definition_en='The cognitive-behavioral model views addiction as maintained by distorted beliefs and learned behavioral patterns, with thoughts (cognition), emotions, and behaviors mutually influencing each other. It is the theoretical foundation of cognitive-behavioral therapy (CBT), which targets automatic thoughts and outcome expectancies that trigger craving, and trains skills to cope with high-risk situations. The focus is on breaking the chain of thoughts, situations, and behaviors that lead to relapse.', example_en='Example: Training to notice the link between the automatic thought ''Just this once is okay'' and subsequent relapse, and to challenge that thought.', body_en='[{"h": "What is it?", "p": "The cognitive-behavioral model holds that thoughts (cognition), emotions, and behaviors influence each other, and that distorted thoughts and learned behaviors maintain addiction. It is the foundation of cognitive-behavioral therapy (CBT)."}, {"h": "How does it explain addiction?", "p": "It posits that automatic thoughts and distortions, such as ''Alcohol is the answer to stress'' or ''Just this once is fine,'' justify substance use, and that conditioned cues and habits maintain the behavior."}, {"h": "How is it treated?", "p": "Treatment involves identifying, examining, and modifying distorted thoughts (cognitive restructuring), and training coping and refusal skills for high-risk situations. Both thoughts and behaviors are addressed together."}, {"h": "What are its implications?", "p": "The cognitive-behavioral model views addiction as learned and therefore re-learnable. It is a well-evidenced, practical approach that serves as the theoretical basis for relapse prevention."}]'::jsonb, advanced_en='[{"h": "Evidence-based core", "p": "CBT is one of the most evidence-based psychotherapies for various mental health issues, including addiction. Relapse prevention and coping skills training are its core components."}, {"h": "Third wave", "p": "The ''third wave'' of CBT, which integrates mindfulness and acceptance (e.g., mindfulness-based relapse prevention, acceptance and commitment therapy), has developed. It adds an approach of staying with craving rather than fighting it."}, {"h": "Diversity of cognitive distortions", "p": "Cognitive distortions that maintain addiction include permissive beliefs, illusion of control, and the abstinence violation effect. Identifying and addressing these is a specific task of CBT."}]'::jsonb, updated_at=now() WHERE id='cognitive-behavioral';
UPDATE encyclopedia_terms SET definition_en='An impulse is a spontaneous urge to pursue immediate pleasure, while a compulsion is a repetitive behavior aimed at reducing anxiety or discomfort. Addiction is explained by a dual-process model in which it shifts from early impulse-driven (pleasure-seeking) to later compulsion-driven (pain avoidance/habit) stages. This transition is supported by weakened control circuits and strengthened habit circuits in the brain.', example_en='Example: A game initially started for fun later turns into compulsive use, where one feels anxious and cannot help but play.', body_en='[{"h": "What are they?", "p": "An impulse is a spontaneous urge to pursue immediate pleasure, while a compulsion is a repetitive behavior aimed at reducing anxiety or discomfort. Addiction involves characteristics of both."}, {"h": "How does the transition occur?", "p": "Addiction shifts from early impulse-driven (pleasure-seeking) to later compulsion-driven (pain avoidance/habit) stages. What starts as fun later becomes a compulsion driven by anxiety if not performed."}, {"h": "What does this mean?", "p": "This transition shows that addiction is not merely pleasure-seeking. In later stages, substance use or behavior is aimed at avoiding discomfort or withdrawal rather than seeking pleasure."}, {"h": "How is it addressed?", "p": "In the impulse stage, coping with immediate rewards is needed; in the compulsion stage, approaches targeting anxiety and habits are required. Stage-matched interventions are effective."}]'::jsonb, advanced_en='[{"h": "Dual-process model", "p": "Addiction is explained by a dual-process model combining impulsivity (weakened top-down control) and compulsivity (strengthened habit circuits). This transition is supported by weakened control circuits and strengthened habit circuits in the brain."}, {"h": "From ventral to dorsal", "p": "Repeated use is associated with a shift in behavioral control from goal-directed (ventral striatum) to habitual/automatic (dorsal striatum). This shift is the neural basis of ''automated compulsion.''"}, {"h": "Distinction from OCD", "p": "Compulsions in addiction resemble those in obsessive-compulsive disorder (OCD) but differ. In addiction, repetition is rooted in reward and habit, whereas in OCD, compulsions primarily aim to reduce anxiety."}]'::jsonb, updated_at=now() WHERE id='compulsion-impulse';
UPDATE encyclopedia_terms SET definition_en='Compulsive computer or internet use is loss of control over online activity to the point of functional harm. The field has shifted from a single ''internet addiction'' label toward activity-specific disorders—gaming, social media, pornography, shopping—because it is usually what you do online, not the internet itself, that becomes the problem.', example_en='The issue is rarely ''too much internet'' but losing control over one specific activity such as gaming or social media.', body_en='[{"h": "What it is", "p": "Compulsive computer and internet use broadly refers to the inability to control online activity, causing impairment of daily functioning. Early discussions treated it as a single concept of ''internet addiction,'' but the now-dominant view is that the essence lies not in the internet itself but in what one does on it—gaming, social media, pornography, shopping."}, {"h": "Why the single concept faded", "p": "The internet is merely a tool; the object over which control is actually lost is a specific activity. The same hours online may be work for one person and compulsive gaming for another. Specifying which activity control is lost over is therefore more accurate—and more useful for treatment—than a lumped-together diagnosis of ''using the internet too much.''"}, {"h": "How it appears", "p": "Use far exceeds planned time, attempts to cut back repeatedly fail, leaving the internet brings restlessness, and sleep, study, work, and face-to-face relationships get pushed aside. Cravings for a specific activity (gaming, social media, etc.) are triggered throughout daily life."}, {"h": "Response", "p": "The key is to specify ''what'' control is lost over, then target that activity. Self-management of use time and situations, adjusting notifications and accessibility, providing alternatives for the emotional needs the activity substituted for, and managing co-occurring depression and anxiety all work together."}]'::jsonb, advanced_en='[{"h": "Conceptual history and classification", "p": "''Internet addiction'' was proposed in the 1990s but drew criticism for lumping heterogeneous activities together, shifting toward activity-specific differentiation. Currently the only official diagnosis is gaming disorder, while social media and pornography remain at the research stage. The core issue is whether to view the various internet-mediated problems as one disorder or as separate behavioral addictions."}, {"h": "Medium or object", "p": "The axis of debate is whether the internet is the ''object of addiction'' or a ''channel mediating access.'' From the latter view, the internet is a facilitator that has dramatically increased the accessibility and intensity of existing behavioral addictions—gambling, sex, shopping—and the real substance of the problem lies in the activities beneath it."}, {"h": "Measurement and over-diagnosis risk", "p": "Self-report scales are criticized for insufficiently distinguishing ''usage amount'' from ''disorder,'' which can inflate prevalence. In an era where digital use has become the default of daily life, strictly applying the criteria that separate normal use from pathology (functional impairment, loss of control) is key to preventing over-diagnosis."}]'::jsonb, updated_at=now() WHERE id='compulsive-computer-use';
UPDATE encyclopedia_terms SET definition_en='Compulsive buying is repeated, out-of-control purchasing beyond need that causes financial and emotional distress. Not an established diagnosis, it is discussed on the impulse-control and addiction spectrum, with tension before buying and relief or pleasure at the moment of purchase. Mobile and live commerce have sharply raised its accessibility and risk.', example_en='Impulsively buying things you don''t need whenever your mood dips, feeling briefly better, then facing regret and debt.', body_en='[{"h": "What it is", "p": "Compulsive shopping is a behavioral pattern of repeatedly consuming beyond need without controlling the buying impulse, resulting in financial and emotional distress. Though not established as an official diagnosis, it is discussed within the impulse-control and addiction spectrum."}, {"h": "How it appears", "p": "A cycle repeats: tension and craving heighten before buying, relief and pleasure arise at the moment of purchase, and regret and guilt soon follow. One buys to soothe emotions rather than out of need, and may not properly use or even hide the purchased items."}, {"h": "Why it is a problem", "p": "Impulsive consumption leads to debt and financial ruin, and the resulting shame and relationship conflict again prompt consumption, creating a vicious cycle. With the spread of mobile and live commerce, instant purchase is possible anytime, anywhere, greatly raising accessibility and risk."}, {"h": "Response", "p": "Becoming aware of what emotion (emptiness, anxiety, depression) the consumption tries to soothe is key. Restricting payment methods and shopping-app access, setting a waiting period before purchase, providing alternative emotional regulation, and managing co-occurring depression and anxiety all work together."}]'::jsonb, advanced_en='[{"h": "Diagnostic status", "p": "Compulsive buying is not an independent diagnosis in DSM or ICD. Views differ on where to place it—impulse-control disorder, behavioral addiction, or a secondary symptom of depression and anxiety. This ambiguity is a factor complicating clinical intervention and research."}, {"h": "The emotion-regulation hypothesis", "p": "Compulsive shopping is commonly understood as self-medicating behavior to relieve negative emotion. The pleasure of purchase temporarily lifts mood but soon reverses into guilt, and this emotional cycle reinforces repetition. Approaches addressing the underlying emotion rather than suppressing consumption are therefore emphasized."}, {"h": "The role of the consumption environment", "p": "Live and mobile commerce, hyper-personalized recommendations, one-click payment, and interest-free installments remove the friction between impulse and purchase. The role of an environment designed to maximize consumption—making compulsive shopping hard to see as a matter of individual disposition alone—is growing."}]'::jsonb, updated_at=now() WHERE id='compulsive-shopping';
UPDATE encyclopedia_terms SET definition_en='A learning process in which a previously neutral cue, through repeated pairing with an addictive substance or behavior, comes to elicit craving and physiological responses on its own. It applies Pavlovian conditioning principles to addiction, explaining why relapse is often triggered by specific places, people, or moods. Cue exposure therapy aims to weaken this association.', example_en='Example: A person who always drank at a bar in a particular alley may experience a racing heart and thoughts of alcohol just by walking through that alley.', body_en='[{"h": "What It Is", "p": "Classical conditioning is a form of learning in which a neutral stimulus, through repeated association with a reward, comes to elicit a response (such as craving) on its own. It originates from Pavlov''s experiments."}, {"h": "How It Works in Addiction", "p": "When specific places, people, tools, or times are repeatedly paired with substance use, encountering those cues alone can trigger craving. The context of use becomes a trigger for craving as a result of this learning."}, {"h": "Why It Matters", "p": "Conditioned cues persist for a long time, so even after cessation of use, exposure to cues can trigger craving and relapse. This explains why returning to familiar environments can be risky."}, {"h": "How It Is Addressed", "p": "Cue avoidance and extinction or reconditioning training—learning not to respond to cues—are used in relapse prevention. Changing one''s environment is also important in early recovery."}]'::jsonb, advanced_en='[{"h": "Cue Reactivity", "p": "Conditioning creates strong physiological and psychological responses to substance-related cues (cue reactivity). This reactivity is a powerful predictor of craving and relapse, making it a key target for relapse prevention."}, {"h": "Extinction and Spontaneous Recovery", "p": "Cue responses can be extinguished through repeated exposure without the substance, but they do not disappear completely; they can reappear over time or in different contexts, a phenomenon called spontaneous recovery. This explains why relapse remains possible even after long abstinence."}, {"h": "Integration with Reward Prediction", "p": "Classical conditioning integrates with dopamine-based reward prediction signals, forming a mechanism where cues predict reward and elicit ''wanting.'' Conditioning and incentive salience work together."}]'::jsonb, updated_at=now() WHERE id='conditioning';
UPDATE encyclopedia_terms SET definition_en='A repetitive pattern of norm-violating and aggressive behavior in childhood and adolescence, which is a risk factor for later substance use disorder and antisocial development. Early intervention is important for reducing the subsequent risk of addiction.', example_en='Example: A developmental pathway where early severe conduct problems lead to substance use in adolescence.', body_en='[{"h": "What is it", "p": "Conduct disorder is a repetitive pattern of norm-violating and aggressive behavior in childhood and adolescence, and is a risk factor for later substance use disorder and antisocial development."}, {"h": "How are they connected", "p": "A developmental pathway has been identified where early severe conduct problems lead to substance use in adolescence. Impulsivity and norm-violating tendencies increase the risk of substance use."}, {"h": "Why is it important", "p": "Conduct disorder can lead to later addiction and antisocial personality disorder, making it a notable early developmental signal. Early intervention can alter this trajectory."}, {"h": "What to look for", "p": "When conduct problems are viewed not merely as ''delinquency'' but as developmental signals requiring intervention, there is potential to prevent various issues including later addiction."}]'::jsonb, advanced_en='[{"h": "Developmental trajectory", "p": "The developmental pathway from conduct disorder to substance use to antisociality has been confirmed by longitudinal studies. Earlier onset tends to be associated with poorer prognosis, emphasizing the need for early intervention."}, {"h": "Shared vulnerability", "p": "Conduct disorder and addiction share common vulnerabilities such as impulsivity, emotional dysregulation, and adverse environments. This common basis explains their association."}, {"h": "Effectiveness of early intervention", "p": "Early interventions such as family intervention and social skills training can reduce the progression of conduct disorder and the subsequent risk of addiction. The value of childhood intervention from a preventive perspective is emphasized."}]'::jsonb, updated_at=now() WHERE id='conduct-disorder';
UPDATE encyclopedia_terms SET definition_en='Contingency management is an evidence-based treatment that reinforces recovery behaviors by providing immediate rewards for desirable actions, such as drug-negative test results. It is a representative application of operant conditioning principles in therapy, particularly effective for stimulant use disorders.', example_en='Example: A program designed to reinforce recovery behaviors by providing rewards when a person abstains from substance use for a specified period.', body_en='[{"h": "What is it?", "p": "Contingency management is an evidence-based treatment that reinforces recovery behaviors by providing immediate rewards for desirable actions, such as drug-negative test results. It is a representative application of operant conditioning principles in therapy, particularly effective for stimulant use disorders."}, {"h": "How does it work?", "p": "When a person is confirmed to have abstained from substance use for a specified period (e.g., negative urine test), they immediately receive a reward (e.g., vouchers, small incentives). The immediate and certain reward reinforces recovery behaviors. The idea is to counter the immediate rewards of substance use by attaching immediate rewards to recovery behaviors."}, {"h": "Why is it effective?", "p": "Addiction is a state that responds strongly to immediate rewards. Contingency management leverages this principle by using certain rewards in the present, rather than distant future benefits, to encourage recovery behaviors. It has strong evidence particularly for stimulant (cocaine, methamphetamine) use disorders, for which effective pharmacotherapy is lacking."}, {"h": "Limitations and misconceptions", "p": "Misconceptions include the idea of ''buying recovery with money,'' and concerns about sustainability once rewards are discontinued. However, it is powerful for establishing initial recovery behaviors, and its effects are reported to persist when combined with other treatments."}]'::jsonb, advanced_en='[{"h": "The paradox of evidence and underutilization", "p": "Contingency management is one of the most evidence-based behavioral treatments, yet it is underutilized in practice due to moral objections to providing rewards and financial/administrative burdens. It is a prime example of the gap between evidence and real-world application."}, {"h": "The treatment gap for stimulants", "p": "Unlike opioids and alcohol, there are no approved effective pharmacotherapies for stimulant use disorders. In this gap, contingency management stands out as the most evidence-based intervention, and its importance is being reexamined amid rising stimulant overdoses."}, {"h": "Ethics and design", "p": "The size and type of incentives (e.g., prize-based rewards) influence effectiveness and sustainability. Concerns that ''external rewards undermine intrinsic motivation'' are addressed by designing a transition from initial behavior formation to natural rewards (relationships, achievements)."}]'::jsonb, updated_at=now() WHERE id='contingency-management';
UPDATE encyclopedia_terms SET definition_en='A legal framework that classifies and regulates substances into schedules based on their abuse potential and medical utility, with the U.S. Controlled Substances Act (CSA) being a representative example. Scheduling affects research, prescription, and penalties, and has been criticized for discrepancies between scientific evidence and classification.', example_en='Example: A substance with potential medical use is placed in a restrictive schedule, limiting research—a point of ongoing debate.', body_en='[{"h": "What Is It", "p": "The Controlled Substances Act is a legal framework that classifies and regulates substances into schedules based on their abuse potential and medical utility. The U.S. CSA is a representative example."}, {"h": "How It Works", "p": "Each substance is assigned to a schedule, which determines rules for research, prescription, distribution, and penalties. Substances classified as having high abuse potential and no accepted medical use are subject to the strictest controls."}, {"h": "Why It Matters", "p": "Schedule classification determines which substances can be researched, prescribed, and what penalties apply for possession. Legal classification has broad implications for medicine, research, and criminal justice."}, {"h": "Controversy", "p": "Critics argue that scheduling sometimes conflicts with scientific evidence. A key issue is that substances with potential medical use (e.g., cannabis, some psychedelics) are placed in restrictive schedules, hindering research."}]'::jsonb, advanced_en='[{"h": "Discrepancy Between Classification and Science", "p": "There is ongoing criticism that the schedule classification of some substances lags behind current scientific evidence. Strict scheduling can create a ''regulatory paradox'' that blocks research into therapeutic potential."}, {"h": "Link to Criminal Penalties", "p": "Schedule classification directly determines the severity of criminal penalties, linking classification equity to disparities in criminal justice. Debates over differential penalties by substance and population are intertwined with this legal framework."}, {"h": "Politics of Rescheduling", "p": "Rescheduling a substance involves not only science but also politics, industry interests, and public opinion. As seen in cannabis rescheduling debates, changing a substance''s schedule can have wide-ranging social impacts."}]'::jsonb, updated_at=now() WHERE id='controlled-substances-act';
UPDATE encyclopedia_terms SET definition_en='Cognitive and behavioral efforts to respond to stress and negative situations, divided into problem-focused coping (addressing the problem itself) and emotion-focused coping (managing emotions). Addiction often manifests as avoidance- and emotion-focused coping that mobilizes substances or behaviors, and a lack of healthy coping repertoire increases vulnerability. Expanding alternative coping skills is key to relapse prevention.', example_en='Example: A person who, when conflict arises, turns to alcohol to forget rather than resolving it through conversation, gradually learns alternative coping strategies such as exercise, journaling, or counseling during recovery.', body_en='[{"h": "What is it", "p": "Coping refers to the ways individuals respond to stress and difficulties. The type and flexibility of coping strategies influence addiction vulnerability and recovery."}, {"h": "How is it linked to addiction", "p": "When substance use becomes the primary coping strategy for stress, other healthy coping mechanisms fail to develop. A narrow coping repertoire that turns to substances whenever difficulties arise perpetuates addiction."}, {"h": "Problem-focused and emotion-focused coping", "p": "Coping is divided into problem-focused coping, which aims to change the problem itself, and emotion-focused coping, which manages the emotions resulting from the problem. Flexible coping tailored to the situation characterizes healthy adaptation."}, {"h": "Implications for treatment", "p": "Recovery involves expanding healthy coping skills to replace substance use. Developing a concrete list of coping strategies for cravings, stress, and high-risk situations is central to relapse prevention."}]'::jsonb, advanced_en='[{"h": "The trap of avoidant coping", "p": "Substance use is a typical avoidant coping strategy that reduces discomfort in the short term but exacerbates problems in the long term. Shifting from avoidance to approach- and problem-focused coping is the direction of recovery."}, {"h": "Coping repertoire", "p": "Healthy adaptation involves the ability to flexibly use a variety of coping strategies according to the situation. Addiction can be seen as a state where this repertoire has narrowed to a single substance."}, {"h": "Connection to relapse prevention", "p": "Relapse prevention focuses on preparing coping plans in advance for each high-risk situation. Securing coping skills enhances self-efficacy and reduces relapse."}]'::jsonb, updated_at=now() WHERE id='coping';
UPDATE encyclopedia_terms SET definition_en='The total direct and indirect socioeconomic costs caused by addiction, including medical expenses, productivity loss, crime, welfare burden, and family breakdown. Countries estimate these costs to set policy priorities and justify prevention investments. It shows that addiction, often seen as a personal problem, is actually a public health issue borne by society as a whole.', example_en='Example: One person''s alcohol problem extends beyond their own treatment costs to impose costs on society through absenteeism, accidents, and family care burdens.', body_en='[{"h": "What It Is", "p": "The social costs of addiction refer to the economic and social burdens that addiction imposes on society beyond the individual. They include medical expenses, productivity loss, and criminal justice costs."}, {"h": "What Costs Are Involved", "p": "Costs include treatment and emergency medical expenses, reduced labor productivity, crime and criminal justice costs, family breakdown and child harm, and accidents. Both direct costs and less visible indirect costs are substantial."}, {"h": "What It Implies", "p": "The enormous cost of addiction suggests that investment in prevention and treatment is socially beneficial. It provides evidence for the argument that ''treatment is more cost-effective than punishment.''"}, {"h": "What to Consider", "p": "Calculating social costs helps set policy priorities. However, balance is needed to avoid viewing affected individuals solely as a ''burden'' when emphasizing costs."}]'::jsonb, advanced_en='[{"h": "Treatment as Investment", "p": "Multiple analyses show that investment in treatment and prevention reduces future medical, judicial, and productivity costs, making it cost-effective. This provides an economic rationale for a health-centered approach."}, {"h": "Distribution of Costs", "p": "The costs of addiction are unevenly distributed across individuals, families, communities, and nations. In particular, the invisible costs borne by children and families are often underestimated."}, {"h": "Perspective in Calculation", "p": "What counts as a cost depends on perspective, and cost discourse risks being misused to stigmatize affected individuals as a ''social burden.'' Balance with a humanistic perspective is required."}]'::jsonb, updated_at=now() WHERE id='costs-of-addiction';
UPDATE encyclopedia_terms SET definition_en='An intense subjective urge to use a substance or engage in a behavior, which is the most characteristic experience of addiction and a key predictor of relapse. Specific cues such as places, people, times, or emotions trigger craving through learned associations, closely linked to surges in dopamine signaling that predict reward. Craving tends to come in waves and subside over time, so coping skills to ride out these waves are an important part of recovery. Stress, negative emotions, and small re-exposures can all strongly induce craving.', example_en='Example: A person who has quit smoking experiences a strong urge to smoke when having coffee after a meal, triggered by the association with their previous smoking habit.', body_en='[{"h": "What is it", "p": "Craving is an intense subjective urge to use a substance or engage in a behavior, and is the most characteristic experience of addiction and a key predictor of relapse."}, {"h": "What triggers it", "p": "Specific cues such as places, people, times, or emotions trigger craving through learned associations. Stress, negative emotions, and small re-exposures can also induce strong craving."}, {"h": "It comes in waves", "p": "Craving tends to come in waves and subside over time. Coping skills to ''ride out'' these waves are an important part of recovery, and understanding that craving does not last forever is helpful."}, {"h": "How to manage it", "p": "Cue avoidance, attention diversion, mindful observation, and contacting supportive relationships are used to cope with craving. An approach of staying with the craving and letting it pass, rather than fighting it, is emphasized."}]'::jsonb, advanced_en='[{"h": "Reward prediction and dopamine", "p": "Craving is closely linked to surges in dopamine signaling that predict reward. When cues signal reward, the brain generates a strong ''wanting,'' which is the neural basis of craving."}, {"h": "Cue reactivity", "p": "Individuals with addiction show strong ''cue reactivity'' to substance-related cues. Extinguishing or reconditioning this response is a target for craving management and relapse prevention."}, {"h": "Separation of wanting and liking", "p": "Craving illustrates the paradox of addiction: wanting something intensely even when it is no longer pleasurable. The incentive salience theory explains this through the dissociation of ''wanting'' and ''liking.''"}]'::jsonb, updated_at=now() WHERE id='craving';
UPDATE encyclopedia_terms SET definition_en='A phenomenon in which tolerance developed to one substance extends to another pharmacologically similar substance. It is commonly observed among substances acting on the same receptors or neural pathways and influences substitution use or treatment medication selection. This principle is utilized in withdrawal management but is also important for understanding the risks of combining multiple depressants.', example_en='Example: A person who has developed tolerance to alcohol may show unexpectedly reduced sensitivity to sedatives of the same class.', body_en='[{"h": "What It Is", "p": "Cross-tolerance is a phenomenon in which tolerance to one substance also applies to other similarly acting substances. It commonly occurs among substances of the same class."}, {"h": "How It Manifests", "p": "For instance, a person with alcohol tolerance may also show some tolerance to other depressants (e.g., benzodiazepines) because they act on the same receptor systems."}, {"h": "Clinical Application", "p": "Cross-tolerance is both a risk and a tool. Managing withdrawal from one depressant with another (e.g., using benzodiazepines for alcohol withdrawal) is the principle of safe detoxification utilizing cross-tolerance."}, {"h": "What to Watch For", "p": "Due to cross-tolerance, switching to another substance may still require high doses, perpetuating risk. Switching within a class does not guarantee safety."}]'::jsonb, advanced_en='[{"h": "Shared Receptor Mechanisms", "p": "Cross-tolerance occurs when substances act on the same receptors or neural systems. This indicates that tolerance is an adaptation to a common mechanism rather than a specific substance."}, {"h": "Application in Detoxification", "p": "Cross-tolerance within the depressant class provides the basis for withdrawal management using substitute medications. This principle allows dangerous withdrawal to be safely managed with more controllable drugs."}, {"h": "Combined Use and Unpredictability", "p": "When cross-tolerance and interactions intertwine, predicting the effects and risks of combining multiple substances becomes difficult. This increases the danger of polysubstance use."}]'::jsonb, updated_at=now() WHERE id='cross-tolerance';
UPDATE encyclopedia_terms SET definition_en='Cryptocurrency and trading addiction is compulsive, gambling-like high-frequency trading of crypto, stocks or similar assets. Round-the-clock markets, extreme volatility, and apps that gamify trading heighten the risk, and it is often understood through the gambling-disorder frame. The socially sanctioned label of ''investing'' tends to delay recognition of the problem.', example_en='Watching price charts all night, impulsively buying and selling, and taking bigger risks to recover losses.', body_en='[{"h": "What it is", "p": "Cryptocurrency and investment addiction refers to a behavioral pattern of compulsively repeating high-frequency trading of crypto, stocks, and the like in a gambling-like manner. Wearing the legitimate guise of investment, it easily delays recognition of the problem."}, {"h": "How it progresses", "p": "A 24-hour open market and extreme volatility prompt constant checking and trading. Once the thrill of a big gain is imprinted, one gradually takes greater risks, and when losses occur, chasing trades to recover them take hold. One checks price screens all night, and daily life and sleep become governed by the trading rhythm."}, {"h": "Why it is close to gambling", "p": "Short-term high-frequency trading often relies on immediate excitement and luck rather than analysis, making it structurally close to gambling. App designs that gamify trading (easy one-tap trades, notifications, celebration effects) fuel impulse. It is commonly understood through the frame of gambling disorder."}, {"h": "Response", "p": "Distinguishing ''investment'' from ''compulsive trading'' is the first step. Setting limits on trade frequency and amount, restricting real-time alerts and app access, becoming aware of the loss-recovery psychology, and the recovery principles of gambling disorder (self-help groups, financial cleanup, supportive relationships) apply equally."}]'::jsonb, advanced_en='[{"h": "The boundary between investment and pathology", "p": "Not all active trading is addiction. The criteria separating planned investment from compulsive trading that collapses one''s life are, again, loss of control and functional impairment. The social legitimacy of ''investment'' delaying recognition of pathology is the particularity of this domain."}, {"h": "Structural facilitating factors", "p": "A 24-hour market, unlimited volatility, leverage, gamified trading interfaces, and social media''s ''to-the-moon'' narratives combine to fuel impulsive trading. This shows that not only individual disposition but market and platform structures amplify risk."}, {"h": "An early stage of research", "p": "Cryptocurrency and investment addiction is not an independent diagnosis and is studied at an early stage as a subtype or adjacent phenomenon of gambling disorder. With standard scales and prevalence data lacking, it is often approached by borrowing the framework of gambling disorder research."}]'::jsonb, updated_at=now() WHERE id='crypto-trading-addiction';
UPDATE encyclopedia_terms SET definition_en='Cybersex or pornography addiction is compulsive, out-of-control consumption of online sexual content or activity. Its defining features are unlimited, instant, anonymous access, with debate over how heavy use may shift expectations and response. Its diagnostic status sits within the compulsive sexual behavior framework and the evidence base is still developing.', example_en='Spending far more time on online sexual content than intended, unable to cut back, with daily life affected.', body_en='[{"h": "What it is", "p": "Cybersex and pornography addiction refers to compulsively consuming or engaging in online sexual content or activity to the point of losing control. Its core backdrop is the internet''s traits of unlimited, instant, anonymous access."}, {"h": "How it progresses", "p": "One spends far more time on sexual content than planned, attempts to cut back repeatedly fail, and one may come to seek ever-stronger stimulation. Daily life, sleep, and relationships are disrupted, and the resulting shame again prompts escapist use."}, {"h": "Why online is different", "p": "Unlike offline, being able to access unlimited content instantly and anonymously makes control difficult. Endless novelty sustains craving, and anonymity weakens the brakes. There is also discussion that frequent use may alter sexual expectations and responses."}, {"h": "Response", "p": "Access control (filters, device management), awareness of the emotional triggers prompting use, managing underlying loneliness, anxiety, and trauma, and recovering healthy intimacy all work together. An environment that lowers shame and enables asking for help is the premise of recovery."}]'::jsonb, advanced_en='[{"h": "Diagnostic status and evidence", "p": "Cybersex and pornography addiction is addressed within the frame of compulsive sexual behavior disorder and is not established as an independent diagnosis. The criteria separating ''problematic pornography use'' from pathological addiction, and the sufficiency of evidence, remain under discussion."}, {"h": "The trap of moral incongruence", "p": "Studies point out that ''moral incongruence'' about pornography use (a conflict between one''s values and behavior) can create distress and a ''sense of addiction'' independent of actual addiction. Distinguishing self-stigma from actual loss of control is therefore clinically important."}, {"h": "Neural and behavioral debate", "p": "Research on whether frequent pornography use alters reward responses and expectations exists, but results are mixed and causation is not established. Cautious interpretation is required regarding whether one can speak of the same neural damage as substance addiction."}]'::jsonb, updated_at=now() WHERE id='cybersex-addiction';
UPDATE encyclopedia_terms SET definition_en='A policy that excludes small-scale possession and use from criminal punishment, distinct from legalization, aiming to connect individuals to treatment and health services instead of punishment. Experiments in some regions have yielded both successes and controversies.', example_en='Example: A policy experiment that directs users to treatment and counseling rather than prison.', body_en='[{"h": "What It Is", "p": "Decriminalization is a policy that excludes personal use and small-scale possession of drugs from criminal punishment, but is distinct from legalization. Drugs remain illegal, but the focus is on connecting users to treatment and health services rather than prison. It does not eliminate punishment entirely but replaces criminal penalties with administrative or health-oriented responses."}, {"h": "How It Differs from Legalization", "p": "Often confused, decriminalization and legalization are different. Legalization permits a legal market for production and sale, while decriminalization maintains illegality but only eases criminal penalties for users. Missing this distinction leads to misinterpretation of the outcomes and limitations of various national cases."}, {"h": "Successes and Setbacks", "p": "Portugal is a prominent success story, having introduced decriminalization alongside treatment and reintegration infrastructure, reducing deaths, infections, and incarceration. In contrast, Oregon (USA) introduced decriminalization in 2020 but, amid infrastructure gaps and an overdose crisis, re-criminalized in 2024. The same policy yields different results depending on infrastructure and context."}, {"h": "The Key Is Infrastructure", "p": "The common lesson from both cases is that decriminalization is not a solution in itself; it works only when accompanied by treatment and social systems that replace punishment. What fills the void left by removing punishment determines the outcome, not the removal itself."}]'::jsonb, advanced_en='[{"h": "Contrast Between Portugal and Oregon", "p": "The contrast between these two cases is a key text in decriminalization research. Portugal combined long preparation, treatment infrastructure, and social reintegration support to establish the policy, while Oregon, with weak treatment linkages and amid a fentanyl crisis, retreated in a short time. This shows that policy success depends more on implementation conditions than on the policy itself."}, {"h": "Debates in Evidence Interpretation", "p": "The effects of decriminalization are methodologically controversial. It is difficult to separate whether observed improvements are due to decriminalization alone or to concurrent treatment expansion and social changes. Supporters and critics often draw opposing conclusions from the same data, requiring careful interpretation."}, {"h": "Relationship with International Norms", "p": "Decriminalization aligns with the public health and human rights-based approaches supported by UNODC, WHO, and human rights bodies, but also represents a point of value conflict with punishment-oriented countries. International tensions surrounding drug policy are concentrated in the decriminalization debate."}]'::jsonb, updated_at=now() WHERE id='decriminalization';
UPDATE encyclopedia_terms SET definition_en='Defense mechanisms are unconscious psychological strategies that protect the ego from anxiety or unbearable emotions. In addiction, prominent defenses include denial (no problem), rationalization (there was a reason), minimization (it''s not that bad), and projection (blaming others), which hinder problem recognition and treatment entry. The key to treatment is addressing the underlying pain rather than breaking down the defenses.', example_en='Example: Someone who drinks daily but believes ''I can quit anytime I want,'' minimizing the problem (denial and minimization).', body_en='[{"h": "What is it?", "p": "Defense mechanisms are unconscious psychological strategies that protect oneself from anxiety and painful emotions. The concept originates from psychoanalysis."}, {"h": "How does it appear in addiction?", "p": "Defenses such as denial (believing there is no problem), rationalization (making up plausible reasons), minimization (downplaying the issue), and projection (blaming others) prevent individuals from confronting their addiction problems."}, {"h": "Why is it important?", "p": "Defense mechanisms block individuals from acknowledging the problem and seeking help. Understanding these defenses is crucial for addressing resistance and facilitating change."}, {"h": "How is it addressed?", "p": "Rather than directly breaking down defenses, approaches that reduce threat and help individuals confront issues on their own (e.g., motivational interviewing) are effective. The starting point is understanding that defenses protect against pain."}]'::jsonb, advanced_en='[{"h": "Boundary between adaptation and pathology", "p": "Defense mechanisms originally serve an adaptive function, helping individuals endure pain. However, in addiction, these defenses become pathological by hindering problem confrontation and recovery."}, {"h": "Spectrum of maturity", "p": "Defenses range from immature ones like denial and projection to mature ones like sublimation and humor. The recovery process involves shifting from immature defenses to mature coping strategies."}, {"h": "Reinterpretation of resistance", "p": "A modern perspective reinterprets ''resistance'' not as the individual''s problem but as a natural response to threat and a signal in the therapeutic relationship. Addressing defenses with respect facilitates change."}]'::jsonb, updated_at=now() WHERE id='defense-mechanisms';
UPDATE encyclopedia_terms SET definition_en='A tendency to devalue future rewards more steeply as the delay increases, serving as a key indicator of impulsivity. Individuals with addiction often exhibit steeper delay discounting, strongly preferring smaller immediate rewards over larger delayed ones. This can be measured through decision-making experiments and may lessen during recovery.', example_en='Example: Repeatedly choosing a small immediate reward over a larger reward available after one month.', body_en='[{"h": "What is it?", "p": "Delay discounting is the tendency to value immediate rewards much more highly than future ones, failing to delay gratification and opting for smaller immediate rewards."}, {"h": "How is it linked to addiction?", "p": "Individuals with addiction often steeply discount the value of future rewards, choosing immediate substance rewards despite knowing long-term harms. A high delay discounting rate is a characteristic cognitive pattern in addiction."}, {"h": "What does it imply?", "p": "This concept reframes addiction not as a lack of willpower but as a distortion in how rewards are evaluated. The core issue is that the future is excessively devalued relative to the present."}, {"h": "Measurement and application", "p": "Delay discounting can be measured experimentally and is associated with addiction severity and relapse risk. Training the ability to delay gratification is one direction for intervention."}]'::jsonb, advanced_en='[{"h": "Indicator of impulsivity", "p": "A high delay discounting rate is a behavioral economic indicator of impulsivity observed across multiple addictions. This supports the role of impulsivity as a common vulnerability in addiction."}, {"h": "State and trait", "p": "Delay discounting has both a stable trait-like component and a state-dependent aspect that becomes steeper during craving or deprivation. This duality suggests opportunities for intervention."}, {"h": "Intervention potential", "p": "Some studies report that training involving concrete future thinking (episodic future thinking) can reduce delay discounting. The possibility of intervention through cognitive training is being explored."}]'::jsonb, updated_at=now() WHERE id='delay-discounting';
UPDATE encyclopedia_terms SET definition_en='A psychological defense mechanism in which one denies or minimizes the existence or severity of one''s addiction problem. It is one of the psychoanalytic defense mechanisms and is considered the most common and powerful barrier to seeking help and entering treatment for addiction. Rather than conscious lying, it is often an unconscious process to protect the ego from unbearable reality, so an approach that addresses the underlying fear rather than blame is effective.', example_en='Example: Despite obvious losses and relationship breakdowns, a person believes ''I don''t have a problem, I can quit anytime I want'' and refuses help.', body_en='[{"h": "What It Is", "p": "Denial is a psychological state in which one does not acknowledge the existence or severity of an addiction problem. It is considered a hallmark feature of addiction and the first barrier to recovery."}, {"h": "Why It Occurs", "p": "It is an unconscious defense to protect oneself from the shame, fear, and sense of loss that acknowledging the problem would bring. Additionally, addiction itself impairs judgment and self-awareness, reinforcing denial."}, {"h": "How It Manifests", "p": "It appears in forms such as ''I can quit anytime,'' ''I drink as much as others,'' or ''The problem is elsewhere.'' Even in the face of obvious harm, the person minimizes or denies the problem."}, {"h": "How to Address It", "p": "Blaming or forcefully trying to break denial only increases resistance. An approach that lowers threat and helps the person recognize contradictions on their own (e.g., motivational interviewing) is effective."}]'::jsonb, advanced_en='[{"h": "Defense and Symptom", "p": "Denial is both a psychological defense and a result of impaired self-awareness (lack of insight) caused by addiction. It is not purely ''lying'' but involves a genuine inability to perceive the problem."}, {"h": "The Confrontation Debate", "p": "Past strong confrontation methods aimed to break denial but were criticized for causing resistance and relationship damage. Modern approaches view empathic, non-confrontational methods as more effective."}, {"h": "Viewing as Ambivalence", "p": "Understanding denial not as a rigid wall but as ambivalence about change opens up opportunities to elicit motivation for change. This is a key insight of motivational interviewing."}]'::jsonb, updated_at=now() WHERE id='denial';
UPDATE encyclopedia_terms SET definition_en='Physical dependence (tolerance, withdrawal) is the body''s adaptation to a drug, while addiction is characterized by loss of control and compulsive use. The two overlap but are not identical; physical dependence from prescribed medication may occur without addiction, and vice versa. This distinction is important to prevent stigmatization of pain patients.', example_en='Example: Why it is inaccurate to immediately label a patient who has developed physical dependence on opioids for pain treatment as an ''addict''.', body_en='[{"h": "What is it", "p": "Physical dependence (tolerance, withdrawal) is the body''s adaptation to a drug, while addiction is characterized by loss of control and compulsive use. The two overlap but are not identical."}, {"h": "Why is the distinction important", "p": "Physical dependence from prescribed medication may occur without addiction, and vice versa. This distinction is important to avoid unfairly labeling pain patients as ''addicts''."}, {"h": "How are they different", "p": "Dependence is ''a state of bodily adaptation to a drug,'' while addiction is ''a state of losing control and compulsively using despite harm.'' Dependence can be a component of addiction but is not the whole."}, {"h": "What to look for", "p": "It is inaccurate to immediately view a patient who has developed physical dependence on opioids for pain treatment as an addict. The presence of loss of control and compulsive use is key to diagnosing addiction."}]'::jsonb, advanced_en='[{"h": "History of terminology confusion", "p": "Until DSM-IV, the term ''dependence'' was used to mean addiction, causing confusion with physical dependence. DSM-5 changed the term to ''substance use disorder'' in part to reduce this confusion."}, {"h": "Pain treatment and stigma", "p": "Confusion between dependence and addiction can stigmatize legitimate pain patients and hinder their access to treatment. This distinction is particularly important in the clinical and ethical aspects of opioid prescribing."}, {"h": "Connection to pseudoaddiction", "p": "Behaviors such as requesting more medication due to uncontrolled pain (pseudoaddiction) can resemble addiction. Distinguishing among dependence, addiction, and pseudoaddiction is crucial for accurate pain management."}]'::jsonb, updated_at=now() WHERE id='dependence-vs-addiction';
UPDATE encyclopedia_terms SET definition_en='A class of substances that slow central nervous system activity, inducing sedation, relaxation, and sleep, primarily by enhancing GABA neurotransmission. Includes alcohol, benzodiazepines, and barbiturates. Concurrent use with other depressants or opioids can be fatal due to respiratory depression. Withdrawal from this class can be a medical emergency.', example_en='Example: A person taking sedatives for insomnia together with alcohol, leading to risk of respiratory depression.', body_en='[{"h": "What Are Depressants?", "p": "Depressants (sedatives) are a class of substances that slow central nervous system activity, inducing sedation, relaxation, and sleep, primarily by enhancing GABA neurotransmission. They include alcohol, benzodiazepines, and barbiturates."}, {"h": "Why Are They Dangerous?", "p": "Using multiple depressants together or combining them with opioids can compound respiratory depression and be fatal. In particular, mixing alcohol with sedatives and opioids is a common cause of overdose death."}, {"h": "Dangerous Withdrawal", "p": "Depressants are a class where withdrawal can become a medical emergency. Withdrawal from alcohol or benzodiazepines can be life-threatening due to seizures and delirium, and must be managed under medical supervision."}, {"h": "What to Watch For", "p": "Depressants are useful for treating anxiety and insomnia, but they are prone to tolerance and dependence, and discontinuation can be risky. Understanding the dangers of combining them with other depressants or opioids is key to safety."}]'::jsonb, advanced_en='[{"h": "Mechanism of GABA Enhancement", "p": "Depressants enhance the action of the inhibitory neurotransmitter GABA, slowing neural activity. This common mechanism makes concurrent use of multiple depressants or with opioids synergistically dangerous."}, {"h": "Cross-Tolerance and Withdrawal Management", "p": "Cross-tolerance exists among depressants, so one depressant (e.g., benzodiazepines) can be used to manage withdrawal from another (e.g., alcohol). This principle underlies safe detoxification."}, {"h": "Clinical Implications of Combined Use", "p": "Combining depressants with opioids is a major pathway to overdose death. Avoiding concurrent use at the prescribing stage, and managing risks when unavoidable, is emphasized as a clinical challenge."}]'::jsonb, updated_at=now() WHERE id='depressants';
UPDATE encyclopedia_terms SET definition_en='Depression is a common comorbid condition that mutually exacerbates addiction, creating a vicious cycle where substance use to alleviate lethargy and anhedonia deepens depression. Treating only one condition increases relapse risk, necessitating an integrated approach.', example_en='Example: A cycle where emptiness from depression is filled with substances, which then worsen depression.', body_en='[{"h": "What is it", "p": "Depression is a mental disorder characterized by persistent depressed mood, anhedonia, and functional impairment. It is a common comorbid condition that mutually exacerbates addiction."}, {"h": "How are they connected", "p": "Substance use to alleviate the lethargy and emptiness of depression creates a vicious cycle that deepens depression. The shared experience of anhedonia intertwines the two."}, {"h": "Which comes first", "p": "Depression can lead to addiction, addiction can lead to depression, and shared vulnerabilities can cause both. Causality is not simple, requiring an integrated understanding."}, {"h": "Implications for treatment", "p": "Treating only one condition increases relapse risk, so an integrated approach addressing both depression and addiction is recommended. Managing anhedonia and depression in early recovery is crucial for relapse prevention."}]'::jsonb, advanced_en='[{"h": "The intersection of anhedonia", "p": "Depression and addiction meet at the common symptom of anhedonia. Blunting of the reward system is identified as a shared neural basis for both conditions."}, {"h": "Suicide risk", "p": "The comorbidity of depression and addiction significantly increases suicide risk. Therefore, safety assessment and crisis management are especially important in integrated treatment. (If you are struggling, you can seek help from professional organizations.)"}, {"h": "Evidence for integrated treatment", "p": "Treating depression and addiction sequentially increases relapse risk, so concurrent integrated treatment is recommended. Combining antidepressants, psychotherapy, and addiction treatment improves prognosis."}]'::jsonb, updated_at=now() WHERE id='depression-addiction';
UPDATE encyclopedia_terms SET definition_en='A group of novel substances (e.g., synthetic cathinones, synthetic cannabinoids) created by modifying the chemical structure of existing drugs to evade regulation. Their inconsistent composition and potency make risk prediction difficult, and acute poisoning cases occur while regulations lag behind.', example_en='Example: A novel substance marketed as ''legal'' causes an emergency due to unexpected toxicity.', body_en='[{"h": "What Are They?", "p": "Designer/synthetic drugs are a group of novel substances created by modifying the chemical structure of existing drugs to evade regulation. Representative examples include synthetic cathinones (''bath salts'') and synthetic cannabinoids."}, {"h": "Why Are They Dangerous?", "p": "Their composition and potency are inconsistent, making risk prediction difficult. Acute poisoning and deaths occur while regulations lag behind. They are sometimes marketed as ''legal,'' leading to a misconception that they are safe."}, {"h": "The Regulatory Cat-and-Mouse Game", "p": "When one substance is banned, a new one with a slightly altered chemical structure emerges, repeating a ''cat-and-mouse game.'' This makes it difficult to respond by banning individual substances alone."}, {"h": "What to Watch For", "p": "The danger of designer/synthetic drugs lies in the fact that their composition is unknown. Users often do not know what or how much they are using, making substance testing and rapid risk alerts important."}]'::jsonb, advanced_en='[{"h": "Evolution of Regulatory Design", "p": "Due to the limitations of banning individual substances, ''analogue regulations'' that cover structurally similar substances and rapid temporary bans have been introduced. However, these still cannot fully keep up with chemical creativity."}, {"h": "Early Warning Systems", "p": "International and national early warning systems that rapidly detect and alert about the emergence of novel substances have become important. Quickly informing users and healthcare providers of risks is key to reducing harm."}, {"h": "Risk of Composition Uncertainty", "p": "The greatest risk of designer/synthetic drugs is the uncertainty of their composition and dosage. Drug checking services are gaining attention as a harm reduction tool to mitigate this risk."}]'::jsonb, updated_at=now() WHERE id='designer-drugs';
UPDATE encyclopedia_terms SET definition_en='Detoxification is the initial stage of safely removing substances from the body and medically managing acute withdrawal. It is only the beginning of recovery, not treatment itself, and without subsequent ongoing rehabilitation and management, relapse is likely. Some withdrawals require medical supervision.', example_en='Example: A case where detoxification is completed but follow-up treatment is not continued, leading to early relapse—mistaking the start of treatment for its end.', body_en='[{"h": "What It Is", "p": "Detoxification (detox) is the initial stage of safely removing substances from the body and medically managing acute withdrawal. It is only the beginning of recovery, not treatment itself, and without subsequent ongoing rehabilitation and management, relapse is likely."}, {"h": "Why Medical Management Is Necessary", "p": "Withdrawal can be dangerous depending on the substance. In particular, alcohol and benzodiazepine withdrawal can be life-threatening due to seizures and delirium, requiring medical supervision. Detoxification is a process that safely navigates this risky period and provides a foundation for transitioning to further treatment."}, {"h": "Common Misconceptions", "p": "The misconception that ''completing detox means treatment is over'' is a common cause of relapse. Detoxification only removes substances from the body; psychological and social treatments addressing craving and relapse must follow for recovery to begin. The ''revolving door'' phenomenon, where detox is repeated without connection to follow-up care, is identified as a problem."}, {"h": "Connection to Next Steps", "p": "The success of detoxification depends on how well it connects to subsequent treatment. The period immediately after detox is the highest risk for relapse, so seamless continuity into ongoing care—such as psychotherapy, medication, self-help groups, and recovery housing—is essential."}]'::jsonb, advanced_en='[{"h": "Clinical Withdrawal Management", "p": "Detoxification is tailored to the withdrawal patterns of each substance. For alcohol withdrawal, benzodiazepine-based management (using the CIWA-Ar scale) is used; for opioid withdrawal, substitution therapy is employed. Safe detoxification is a prerequisite for subsequent treatment engagement, but by itself does not guarantee long-term outcomes."}, {"h": "The Paradox of Overdose Risk", "p": "After detoxification, tolerance decreases, and reusing the previous dose can lead to fatal overdose. This risk is particularly high with opioids, and relapse after detox dramatically increases the risk of overdose death. This paradox highlights the danger of conducting detoxification alone."}, {"h": "Client Perspective", "p": "Detoxification is a physically difficult period and a vulnerable time when motivation for recovery can waver. Without nonjudgmental support and a clear connection to the next step, clients are likely to drop out. It is important to view detox not as a ''rite of passage'' but as a gateway that requires support."}]'::jsonb, updated_at=now() WHERE id='detoxification';
UPDATE encyclopedia_terms SET definition_en='The disease model views addiction as a chronic, relapsing brain disease rather than a lack of willpower. It forms the basis for treatment and recovery approaches and helps reduce stigma, but it has also been criticized for underestimating personal responsibility and social/environmental factors, leading to ongoing academic debate. Compromise perspectives between the pure disease model and choice/learning models are widely accepted today.', example_en='Example: The explanation that ''addiction is a brain disease'' can reduce self-blame and lead to treatment, but it also raises concerns about removing personal responsibility, sparking debate.', body_en='[{"h": "What is it?", "p": "The disease model views addiction not as a moral failing or a matter of willpower, but as a chronic, relapsing brain-based disease. It is the mainstream framework for understanding addiction today."}, {"h": "What does it claim?", "p": "It claims that repeated substance use alters the brain''s reward and control circuits, impairing control. Thus, addiction is a disease requiring treatment, and relapse is understood as a characteristic of the disease."}, {"h": "What has it contributed?", "p": "The disease model shifted addiction from a moral issue to a medical one, reducing stigma and justifying treatment and insurance coverage. It provided a counterargument to the accusation of ''weak will.''"}, {"h": "There are also criticisms", "p": "On the other hand, critics argue that the disease model underestimates personal agency and the potential for recovery, and obscures social and environmental causes. Concerns have also been raised that it fixes addiction as a ''lifelong disease.''"}]'::jsonb, advanced_en='[{"h": "Historical shift", "p": "The disease model evolved through Benjamin Rush, Jellinek, and modern neuroscience (e.g., Volkow), shifting the understanding of addiction from morality to medicine. The disease concept in Alcoholics Anonymous also contributed to its popular spread."}, {"h": "Critical perspectives", "p": "Critics like Stanton Peele argue that the disease model overly biologizes addiction, obscuring the roles of learning, context, choice, and the possibility of natural recovery. The ''disease vs. learning'' debate continues."}, {"h": "Toward integration", "p": "Today, there is a call to move beyond the dichotomy of pure disease model vs. pure learning/choice model, toward a biopsychosocial perspective that considers brain changes, agency, and social environment together."}]'::jsonb, updated_at=now() WHERE id='disease-model';
UPDATE encyclopedia_terms SET definition_en='Co-founder of AA, who, together with Bill Wilson, put into practice the mutual aid principle of one alcoholic helping another.', example_en='Example: A figure who personally embodied the peer-to-peer recovery model from the early days.', body_en='[{"h": "Who He Is", "p": "Dr. Bob (Robert Smith) is the co-founder of AA, who, together with Bill Wilson, put into practice the mutual aid principle of one alcoholic helping another."}, {"h": "What He Did", "p": "A physician and himself a person with alcohol problems, he recovered through his meeting with Bill W., and together they laid the foundation of AA. He personally practiced peer-to-peer recovery."}, {"h": "Why He Matters", "p": "Dr. Bob is a figure who embodied mutual aid recovery in practice from the early days. He showed that recovery occurs not in theory but in actual helping relationships."}, {"h": "What He Left Behind", "p": "His collaboration with Bill W. became the starting point of AA. The meeting of these two men is symbolic as the seed of a worldwide recovery movement."}]'::jsonb, advanced_en='[{"h": "Recovery as Practice", "p": "Dr. Bob is remembered as a figure who implemented mutual aid in practice. His role demonstrates that recovery is not an abstract principle but a concrete helping relationship."}, {"h": "The Meeting of Medicine and Self-Help", "p": "His dual position as a physician and a person with lived experience symbolizes the intersection of professional medical care and peer self-help. This foreshadowed later developments such as the Minnesota Model."}, {"h": "A Symbol of Collaboration", "p": "The collaboration between Dr. Bob and Bill W. is a prototypical example showing that recovery occurs not alone but in relationship. The fundamental principles of AA emerged from this meeting."}]'::jsonb, updated_at=now() WHERE id='dr-bob';
UPDATE encyclopedia_terms SET definition_en='The route of administration (oral, inhalation, injection, mucosal, etc.) refers to how a substance enters the body. Even for the same substance, the speed, intensity, and risk of effects vary greatly depending on the route. Faster routes to the brain increase the risk of intoxication and dependence.', example_en='Example: For the same substance, faster routes like injection or inhalation carry a higher risk of dependence than oral administration.', body_en='[{"h": "What It Is", "p": "The route of administration is the way a substance enters the body (oral, inhalation, injection, mucosal, etc.). Even for the same substance, the speed, intensity, and risk of effects vary greatly depending on the route."}, {"h": "Speed Determines Risk", "p": "Faster routes to the brain carry a greater risk of intoxication and dependence. Injection and inhalation produce faster and stronger effects than oral administration, and thus pose a higher risk of dependence."}, {"h": "Route-Specific Risks", "p": "Injection adds risks of infection (HIV, hepatitis) and vascular damage; inhalation can cause lung damage; nasal insufflation can damage mucous membranes. Each route has its own additional risks."}, {"h": "Implications", "p": "For the same substance, ''how it is used'' determines the risk. This principle provides the basis for harm reduction, guiding safer methods of use."}]'::jsonb, advanced_en='[{"h": "Pharmacokinetics and Dependence", "p": "The route of administration determines the speed at which a substance reaches the brain (pharmacokinetics), and this speed directly affects the intensity of reward and the formation of dependence. Faster delivery produces stronger reinforcement."}, {"h": "Risk of Route Switching", "p": "As dependence progresses, there is a tendency to switch to faster and more intense routes (oral → inhalation → injection), which signifies increased risk. Route switching may be a signal of worsening addiction."}, {"h": "Harm Reduction and Routes", "p": "Needle exchange programs to reduce infection risk from injection, and provision of smoking tools, are harm reduction measures targeting route-specific risks. This approach addresses ''how'' as well as ''what'' is used."}]'::jsonb, updated_at=now() WHERE id='drug-administration';
UPDATE encyclopedia_terms SET definition_en='A phenomenon in which the effects or risks of two or more substances change when they are used together. Combining depressants with each other or with opioids is particularly dangerous as it increases respiratory depression, and unexpected interactions are a common cause of overdose.', example_en='Example: Using alcohol with sedatives or opioids results in much greater risk than using each alone.', body_en='[{"h": "What is it", "p": "Drug interaction is a phenomenon in which the effects or risks of two or more substances change when they are used together. Unexpected interactions are a common cause of overdose."}, {"h": "Why is it dangerous", "p": "Combining depressants with each other, or depressants with opioids, is particularly dangerous as it increases respiratory depression. Doses that are tolerable individually can be fatal when taken together."}, {"h": "What are common cases", "p": "Common examples of dangerous interactions include combining alcohol with sedatives or opioids, and stimulants with opioids (''speedball''). Interactions between prescription drugs and alcohol are also easily overlooked."}, {"h": "What to watch out for", "p": "When using multiple substances (including prescription drugs) together, the risk of interaction must always be considered. Unrecognized concurrent use is often a hidden cause of overdose."}]'::jsonb, advanced_en='[{"h": "Pharmacokinetic and pharmacodynamic interactions", "p": "Interactions are divided into pharmacokinetic types, where metabolism or excretion of substances changes, and pharmacodynamic types, where substances act together on the same target. The danger of combining depressants is a representative example of the latter."}, {"h": "Risk of synergistic effects", "p": "Combining depressants and opioids produces a synergistic risk that exceeds the sum of individual effects. Due to this nonlinearity, ''a little of each'' can be more lethal than expected."}, {"h": "The era of polypharmacy", "p": "With aging and increased polypharmacy, the risk of interactions grows. Checking for interactions at the prescribing stage and educating users are key to safety."}]'::jsonb, updated_at=now() WHERE id='drug-interactions';
UPDATE encyclopedia_terms SET definition_en='Drug policy encompasses the full range of societal responses to substance use, forming a spectrum from prohibition and punishment to health and harm reduction. It is a representative arena where evidence-based policy and political-moral values conflict.', example_en='Example: For the same problem, opposing policy directions—such as stricter punishment versus expanded treatment—compete.', body_en='[{"h": "What is it?", "p": "Drug policy encompasses the full range of societal responses to substance use, forming a spectrum from prohibition and punishment to health and harm reduction."}, {"h": "What is the spectrum?", "p": "At one end lies strict punishment and prohibition; at the other, harm reduction and recovery support. Most policies fall somewhere in between, shifting with the times and political climate."}, {"h": "What are the key issues?", "p": "For the same problem, opposing directions—such as stricter punishment versus expanded treatment—compete. It is a representative arena where evidence-based policy and moral-political values conflict."}, {"h": "What should we consider?", "p": "Drug policy reveals not only its effectiveness but also which values a society prioritizes. Beyond the name of the policy, we must examine the infrastructure supporting it and the actual outcomes."}]'::jsonb, advanced_en='[{"h": "Conflict between evidence and values", "p": "Drug policy is not determined by evidence alone. Moral values such as a ''drug-free society'' and pragmatic values like ''harm minimization'' conflict, leading to different interpretations of the same data."}, {"h": "Difficulty in policy transfer", "p": "A policy successful in one country may fail in another. Due to differences in infrastructure, culture, and substance environment, simple policy transfer is risky."}, {"h": "Extension to behavioral addictions", "p": "Traditional drug policy discussions have focused on substances, but extending them to behavioral addictions such as gambling and gaming remains a challenge. Regulation of the gambling industry and design of digital environments are emerging policy areas."}]'::jsonb, updated_at=now() WHERE id='drug-policy';
UPDATE encyclopedia_terms SET definition_en='A system that assigns legal schedules to substances based on their risk and medical value, establishing the framework for regulation, research, and medical access. Criteria vary by country, so the same substance may have different legal statuses.', example_en='Example: A substance strictly prohibited in one country may be permitted for medical use in another.', body_en='[{"h": "What It Is", "p": "Drug scheduling is a system that assigns legal schedules to substances based on their risk and medical value, establishing the framework for regulation, research, and medical access."}, {"h": "Variation by Country", "p": "The same substance may be classified differently across countries, so a substance strictly prohibited in one country may be permitted for medical use in another. This shows that scheduling is a policy choice rather than purely scientific."}, {"h": "What It Affects", "p": "Scheduling determines prescription availability, research permissions, and severity of penalties. Strict scheduling can deter misuse but may also limit legitimate medical and research access."}, {"h": "What to Consider", "p": "Drug scheduling involves a balance between risk control and access to medical care and research. It is important to examine whether scheduling is evidence-based and what its social consequences are."}]'::jsonb, advanced_en='[{"h": "International Treaties and Domestic Law", "p": "Drug scheduling is implemented by each country through domestic law within the framework of UN drug control treaties. Tensions and coordination between international norms and domestic policies arise around scheduling."}, {"h": "Challenge of New Psychoactive Substances", "p": "New synthetic drugs often emerge with modified chemical structures to circumvent existing schedules. This ''cat-and-mouse game'' reveals the limitations of individual substance scheduling and has prompted comprehensive regulatory approaches."}, {"h": "Impact of Rescheduling", "p": "Rescheduling a substance (e.g., allowing medical use) has significant ripple effects on research, industry, and criminal justice. Changing a schedule is not merely an administrative act but a matter of social consensus."}]'::jsonb, updated_at=now() WHERE id='drug-scheduling';
UPDATE encyclopedia_terms SET definition_en='A test that detects substance use in bodily fluids, used in workplace, judicial, and treatment settings. It has a deterrent effect but raises concerns about privacy, accuracy, stigma, and the possibility of false positives.', example_en='Example: Workplace drug testing deters use while sparking debates over privacy and fairness.', body_en='[{"h": "What is it", "p": "Drug testing is a test that detects substance use in bodily fluids, used in workplace, judicial, and treatment settings."}, {"h": "Where is it used", "p": "It is used to confirm use in employment, criminal justice (e.g., probation), and treatment programs (e.g., contingency management). It functions both as a deterrent and a therapeutic tool."}, {"h": "What are the controversies", "p": "Issues include privacy invasion, accuracy (possibility of false positives), and stigma. There is tension between the deterrent effect of testing and individual rights and fairness."}, {"h": "What should be considered", "p": "The justification of drug testing varies by purpose (safety, treatment, punishment). It is important to understand the limitations of test results (difficulty in knowing timing and amount of use) and the possibility of false positives."}]'::jsonb, advanced_en='[{"h": "Testing as a therapeutic tool", "p": "In contingency management, drug testing is used not as punishment but as a tool to reinforce recovery behaviors. A typical approach links negative results to rewards."}, {"h": "Accuracy and false results", "p": "Drug tests have the potential for false positives and false negatives, and detection windows vary by substance, requiring caution in interpretation. The risk of overemphasizing a single test result has been noted."}, {"h": "Tension between rights and surveillance", "p": "Especially in employment drug testing, issues of privacy and discrimination arise. Key points include distinguishing between safety-sensitive and non-sensitive jobs, and the proportionality of testing."}]'::jsonb, updated_at=now() WHERE id='drug-testing';
UPDATE encyclopedia_terms SET definition_en='Driving under the influence of substances, which, along with drunk driving, is a serious public safety issue. Detection and determination standards vary by substance, making enforcement and proof challenging.', example_en='Example: Driving under the influence of cannabis or prescription drugs, leading to impaired judgment and slowed reactions.', body_en='[{"h": "What is it", "p": "Drugged driving is driving under the influence of substances, and along with drunk driving, it is a serious public safety issue."}, {"h": "Why is it dangerous", "p": "Under the influence of cannabis, prescription drugs, or illegal substances, judgment, reaction time, and attention are impaired, increasing the risk of accidents. Concurrent use of multiple substances further elevates the risk."}, {"h": "Challenges in enforcement", "p": "Unlike alcohol, the threshold for impairment and detection methods vary by substance, making enforcement and proof difficult. There are also cases where residual presence in the body does not match actual impairment."}, {"h": "What to consider", "p": "Drugged driving has become a new policy challenge with cannabis legalization. Developing accurate impairment criteria and testing methods is key to public safety."}]'::jsonb, advanced_en='[{"h": "Scientific challenges in impairment assessment", "p": "Blood substance concentration often does not correlate with actual driving impairment, making it scientifically difficult to set legal thresholds for impairment. This is especially true for cannabis."}, {"h": "Legalization and new challenges", "p": "In regions where cannabis is legalized, managing drugged driving has emerged as a new policy challenge. The drunk driving model cannot be directly applied due to unique characteristics."}, {"h": "Limitations of testing technology", "p": "Rapid and accurate field testing technology for impairment is still lacking. This gap is a key factor hindering enforcement and prevention."}]'::jsonb, updated_at=now() WHERE id='drugged-driving';
UPDATE encyclopedia_terms SET definition_en='A diagnostic manual for mental disorders published by the American Psychiatric Association; the current edition is DSM-5-TR. Widely used in global research and clinical practice, it notably incorporated gambling disorder into the same category as substance addictions and merged the ''abuse/dependence'' distinction into ''substance use disorder''. The WHO''s ICD is used in parallel for international public health statistics, and the two systems show some differences.', example_en='Example: Gaming disorder is an official diagnosis in ICD-11 but is placed in the appendix of DSM-5-TR as requiring further study, illustrating a divergence between the two systems.', body_en='[{"h": "What is it?", "p": "The DSM (Diagnostic and Statistical Manual of Mental Disorders) is a diagnostic manual for mental disorders published by the American Psychiatric Association and is the standard reference for addiction diagnosis. The current edition is DSM-5-TR."}, {"h": "What changed?", "p": "Starting with DSM-5, the dichotomy of ''abuse/dependence'' was abandoned and merged into ''substance use disorder'', with severity (mild, moderate, severe) determined by the number of symptoms. The inclusion of gambling disorder in the addiction category was another significant change."}, {"h": "How is it diagnosed?", "p": "Diagnosis and severity are determined by the number of criteria met among 11 items, including impaired control, social impairment, risky use, and pharmacological indicators (tolerance, withdrawal). The focus is on functional impairment, not the amount of use."}, {"h": "What is useful to know?", "p": "The DSM provides a common diagnostic language that facilitates research, treatment, and communication. However, diagnostic criteria are a ''consensus'' that evolves with social and scientific changes, not fixed truths."}]'::jsonb, advanced_en='[{"h": "Relationship with ICD", "p": "Alongside the DSM, the WHO''s ICD is widely used internationally. The two systems generally converge but differ in details (e.g., the status of gaming disorder), and these differences can spark diagnostic and policy debates."}, {"h": "Social nature of diagnosis", "p": "DSM revisions are products not only of scientific evidence but also of social consensus and debate. Decisions about what to include or exclude as a disorder have major implications for clinical practice, research, insurance, and stigma, so each revision is accompanied by controversy."}, {"h": "Category vs. dimension debate", "p": "The DSM is fundamentally based on categorical diagnosis (present/absent), but the view of addiction as a continuum of severity (dimensional) is gaining strength. The introduction of severity levels reflects this trend."}]'::jsonb, updated_at=now() WHERE id='dsm';
UPDATE encyclopedia_terms SET definition_en='A condition in which addiction and another mental disorder (e.g., depression, anxiety, ADHD, PTSD) co-occur. The two problems exacerbate each other, complicating treatment, and treating only one increases the risk of relapse, so integrated treatment is recommended. Clinically, co-occurrence is the rule rather than the exception.', example_en='Example: A vicious cycle where alcohol use increases to soothe depression and anxiety, and alcohol use in turn worsens depression, with the two problems intertwined.', body_en='[{"h": "What is it", "p": "Dual diagnosis (co-occurring disorders) refers to the presence of both addiction and another mental disorder (e.g., depression, anxiety, PTSD, schizophrenia). It is very common among the addiction population."}, {"h": "Why is it common", "p": "Co-occurrence arises through multiple pathways: using substances to soothe the pain of mental illness (self-medication), substance use triggering or worsening mental problems, or shared vulnerabilities causing both conditions."}, {"h": "Why is it important", "p": "Treating only one condition creates a vicious cycle where the other triggers relapse. Addiction treatment without addressing depression, or depression treatment without addressing addiction, is unlikely to be sustained."}, {"h": "How is it treated", "p": "An integrated approach that addresses both conditions simultaneously is recommended. It is effective when addiction treatment and psychiatric treatment are not separated but delivered within a single team and plan."}]'::jsonb, advanced_en='[{"h": "Complexity of causality", "p": "In dual diagnosis, what is cause and what is effect is complex. Self-medication, substance-induced effects, and shared vulnerabilities are intertwined, making it difficult to reduce to a simple temporal sequence."}, {"h": "Fragmentation of treatment systems", "p": "When addiction services and mental health services are separated, patients with dual diagnosis are at risk of falling through the cracks. The need for integrated treatment systems is highlighted as a policy challenge."}, {"h": "Prognosis and integrated approach", "p": "Dual diagnosis has a worse prognosis and higher relapse risk than a single diagnosis. Therefore, an integrated, long-term approach and continuous care are especially important."}]'::jsonb, updated_at=now() WHERE id='dual-diagnosis';
UPDATE encyclopedia_terms SET definition_en='A group of mental disorders characterized by distorted cognitions about eating behavior, weight, and body shape, causing significant physical and psychological harm. It includes anorexia nervosa, bulimia nervosa, and binge-eating disorder. These disorders have high mortality rates, making professional treatment essential. Although they share reward and compulsion mechanisms with addiction, they are independent diagnoses.', example_en='Example: A state in which health is threatened due to severe restriction of food intake or repeated binge eating and compensatory behaviors driven by extreme fear of body shape (specific methods are not described as they may be harmful).', body_en='[{"h": "What is it", "p": "Eating disorders are serious psychological and behavioral problems related to food, weight, and body shape, including anorexia nervosa, bulimia nervosa, and binge-eating disorder. They are life-threatening mental illnesses."}, {"h": "Overlap with addiction", "p": "Some eating disorders, particularly binge eating, share mechanisms with addiction in terms of loss of control, compulsion, and emotional dysregulation. The concept of ''food addiction'' is also discussed at this intersection."}, {"h": "What is core", "p": "At the root of eating disorders are often low self-esteem, perfectionism, need for control, and emotional distress. Food and body shape are often the surface through which this distress manifests."}, {"h": "Getting help", "p": "Eating disorders are serious conditions requiring professional treatment. Rather than trying to manage alone, it is important to seek help from medical and psychological professionals. Non-judgmental support from those around you can greatly aid recovery."}]'::jsonb, advanced_en='[{"h": "High risk", "p": "Anorexia nervosa has one of the highest mortality rates among mental disorders. Due to the combined risks of physical complications and suicide, early professional intervention is especially important."}, {"h": "Debate on applying the addiction model", "p": "There is debate over whether binge eating should be viewed through an addiction framework or as a disorder specific to eating. While the addiction model can provide insights, it also risks oversimplifying the complexity of eating disorders."}, {"h": "Integrated understanding", "p": "Eating disorders are multifactorial conditions involving biological vulnerability, psychological factors, and sociocultural pressures (e.g., appearance norms). Recovery is sustained when not only food issues but also underlying emotions, relationships, and self-worth are addressed together."}]'::jsonb, updated_at=now() WHERE id='eating-disorders';
UPDATE encyclopedia_terms SET definition_en='The ability to regulate the intensity, duration, and expression of emotions, which is a core psychological function in the onset and maintenance of addiction. Individuals with difficulty in emotion regulation cannot tolerate negative emotions and seek immediate relief through substances or behaviors, serving as a psychological pathway for self-medication. Learning healthy regulation skills is a key goal in addiction treatment.', example_en='Example: When anger or loneliness arises, having no way to handle the emotion and immediately suppressing it with substances as a coping pattern.', body_en='[{"h": "What It Is", "p": "Emotion regulation is the ability to recognize and manage one''s emotions. Deficits in this ability play a key role in the onset and maintenance of addiction."}, {"h": "How It Connects to Addiction", "p": "When the ability to self-soothe strong negative emotions is lacking, individuals rely on substances or behaviors for regulation. Addiction functions as ''outsourced emotion regulation.''"}, {"h": "Vicious Cycle", "p": "Using substances to regulate emotions weakens self-regulation ability and increases dependence on substances. Moreover, substance use itself worsens emotional problems, creating a vicious cycle."}, {"h": "Implications for Treatment", "p": "Recovery involves (re)learning skills to handle emotions without substances. Training in skills such as mindfulness, distress tolerance, and emotion recognition becomes a core component of addiction treatment."}]'::jsonb, advanced_en='[{"h": "Deficit and Cause", "p": "Emotion dysregulation is both a cause and a consequence of addiction. It may precede as a vulnerability, and substance use further impairs regulation ability. This bidirectional relationship complicates treatment."}, {"h": "Dialectical Behavior Therapy", "p": "Dialectical behavior therapy (DBT), used for borderline personality disorder and addiction, focuses on distress tolerance and emotion regulation skills. It is a representative approach that explicitly targets emotion regulation."}, {"h": "Connection to Negative Reinforcement", "p": "The emotion regulation perspective links negative reinforcement (relief from discomfort) and the self-medication hypothesis. Substances temporarily soothe unregulated distress, reinforcing use."}]'::jsonb, updated_at=now() WHERE id='emotion-regulation';
UPDATE encyclopedia_terms SET definition_en='Exercise addiction is compulsive continuation of exercise despite injury, exhaustion or disruption to daily life, with withdrawal-like anxiety when stopping. A prime example of a health behavior turning pathological, it often co-occurs with eating disorders or body-image concerns. Control and functional impairment separate devoted exercise from compulsive exercise.', example_en='Told to rest for an injury, the person cannot stop exercising out of anxiety and worsens the injury.', body_en='[{"h": "What it is", "p": "Exercise addiction refers to compulsively continuing exercise despite injury, fatigue, and daily disruption, and experiencing withdrawal-like symptoms (anxiety, restlessness) when stopping. It is a leading case of a health behavior turning into pathology."}, {"h": "How it differs from dedication", "p": "Exercising hard differs from being addicted to exercise. Healthy exercise allows rest depending on circumstances, but exercise addiction cannot stop due to anxiety even when one should rest for injury. It becomes a problem when exercise is not for life, but life is reorganized around exercise and other areas are pushed aside."}, {"h": "What gets entangled", "p": "Exercise addiction commonly appears together with eating disorders and body-image (appearance, shape) problems. In this case exercise becomes a compulsive means of body control or anxiety relief rather than health. Over-exercising despite injury actually harms the body."}, {"h": "Response", "p": "The goal is to recover control and balance, not to eliminate exercise. Including rest in the plan, directly addressing the anxiety and body-image problems exercise had been managing, and jointly evaluating a suspected eating disorder. The key is preserving exercise''s positive functions while escaping compulsion."}]'::jsonb, advanced_en='[{"h": "Primary and secondary", "p": "Exercise addiction is sometimes distinguished into ''primary,'' where it is an end in itself, and ''secondary,'' where it accompanies an eating disorder as a means of weight and shape control. In the secondary case, recovery is difficult through exercise control alone without addressing the underlying eating disorder."}, {"h": "Diagnostic status", "p": "Exercise addiction is not an official diagnosis and is studied as a candidate behavioral addiction. Addiction criteria such as withdrawal-like symptoms, tolerance, and loss of control are applied to exercise, but setting the criteria that separate healthy high-intensity training from pathology is tricky."}, {"h": "Tension with health discourse", "p": "Because exercise is a socially encouraged health behavior, its pathological form is hard to recognize and easily praised. Given that social-media workout-verification culture may fuel over-exercising and body-image compulsion, the boundary between health discourse and pathology must be examined together."}]'::jsonb, updated_at=now() WHERE id='exercise-addiction';
UPDATE encyclopedia_terms SET definition_en='An individual''s belief about the specific outcomes that a particular substance or behavior will produce, which strongly influences use as much as actual pharmacological effects. Positive expectancies (e.g., ''Drinking relaxes me,'' ''Gaming relieves stress'') promote use, and these expectancies are formed through direct experience and social learning. Modifying expectancies is a key component of cognitive-behavioral therapy.', example_en='Example: Continuing to drink because of a firm belief that ''a drink helps me sleep,'' even though alcohol actually disrupts sleep.', body_en='[{"h": "What Are Outcome Expectancies?", "p": "Outcome expectancies are an individual''s beliefs about the specific outcomes that a particular substance or behavior will produce. Expectancies such as ''Drinking this will relax me'' drive behavior."}, {"h": "How Do They Work in Addiction?", "p": "Positive expectancies about a substance (relaxation, pleasure, confidence) increase motivation to use, and these expectancies can shape actual experience. The expectancy itself becomes part of the effect."}, {"h": "What Do They Imply?", "p": "Even with the same substance, experience and use patterns vary depending on what one expects. Distorted expectancies (e.g., ''Alcohol solves my problems'') sustain use."}, {"h": "Implications for Treatment", "p": "Examining and modifying unrealistic positive expectancies is a part of cognitive-behavioral therapy. Changing expectancies can lead to behavior change."}]'::jsonb, advanced_en='[{"h": "Expectancies Create Effects", "p": "Alcohol expectancy research shows that when people believe they have consumed alcohol (even if they have not), they behave in ways consistent with their expectancies. This demonstrates the powerful role of expectancies, akin to placebo effects."}, {"h": "Development of Expectancies", "p": "Substance expectancies are formed through social learning even before use begins. Expectancies formed in childhood influence later initiation and patterns of use, making them a target for prevention."}, {"h": "Ambivalent Expectancies", "p": "Users often hold both positive and negative expectancies simultaneously. Addressing this ambivalence is a key point for eliciting change in motivational interviewing and cognitive-behavioral therapy."}]'::jsonb, updated_at=now() WHERE id='expectancy';
UPDATE encyclopedia_terms SET definition_en='An approach that views addiction not as an individual problem but as an issue within the family system, addressing relationship patterns and communication to support recovery. It alleviates codependency and transforms the family from part of the problem into a resource for recovery.', example_en='Example: The entire family participates in counseling together to change the interactions that perpetuate the problem.', body_en='[{"h": "What It Is", "p": "Family therapy is an approach that views addiction not as an individual problem but as an issue within the family system, addressing relationship patterns and communication to support recovery. It alleviates codependency and transforms the family from part of the problem into a resource for recovery."}, {"h": "Why the Family", "p": "Addiction affects not just the individual but the entire family, and family interactions can perpetuate the problem. For example, taking over responsibilities or hiding the problem can deprive the individual of the opportunity to face consequences. Therefore, addressing the family system together is beneficial for recovery."}, {"h": "How It Is Done", "p": "The family participates in counseling together to recognize and change the interactions that sustain the problem. They learn to set healthy boundaries, communicate honestly, and each family member learns to take care of their own life. The focus shifts from trying to fix the individual to changing relationships."}, {"h": "Family Recovery", "p": "A key insight of family therapy is that the family itself needs recovery. When family members, exhausted from long-term care and conflict, learn to care for themselves and set healthy boundaries, they can better support the individual''s recovery. Recovery is a task for the whole family."}]'::jsonb, advanced_en='[{"h": "Systemic Perspective", "p": "Family therapy views addiction not as individual pathology but as a phenomenon maintained within the homeostasis of the family system. Because one person''s change disrupts the system''s balance, treating only the individual may cause the system to pull them back into their previous role. Therefore, it aims for change in the system itself."}, {"h": "Evidence-Based Family Interventions", "p": "For adolescent addiction, Multidimensional Family Therapy (MDFT) and Community Reinforcement and Family Training (CRAFT) are evidence-based approaches. They train families in relationship and communication skills to increase treatment entry and retention. Family interventions have been reported to show better outcomes than individual treatment alone."}, {"h": "Codependency and Community", "p": "Family therapy is connected to the concept of codependency and family self-help groups like Al-Anon. Furthermore, when recovery communities include families as partners in recovery, family therapy becomes part of community-based recovery beyond individual counseling. This aligns with the recovery village model that embraces families together."}]'::jsonb, updated_at=now() WHERE id='family-therapy';
UPDATE encyclopedia_terms SET definition_en='Fentanyl is a synthetic opioid dozens to hundreds of times more potent than morphine, and has become a leading cause of drug overdose deaths, particularly in North America. Even tiny amounts can be lethal, and it is often secretly mixed into other drugs, posing a high risk of unintentional exposure. Recently, mixtures with sedatives like xylazine (''tranq'') have emerged as a new threat, and its global spread is a key public health concern.', example_en='Example: A case where a person unknowingly takes a pill believed to be a stimulant but which contains fentanyl, leading to an unexpected overdose.', body_en='[{"h": "What is it?", "p": "Fentanyl is a synthetic opioid dozens to hundreds of times more potent than morphine, originally used for severe pain management. Even minuscule amounts can be fatal, and it has recently become a leading cause of drug overdose deaths, especially in North America."}, {"h": "Why is it dangerous?", "p": "Fentanyl is often secretly mixed into other drugs (heroin, counterfeit pills, etc.), exposing users to lethal doses without their knowledge. Because it does not mix uniformly, the lethal dose can vary greatly even within the same batch. This ''invisible risk'' has led to a surge in overdose deaths."}, {"h": "New threats", "p": "Recently, mixtures with the sedative xylazine (''tranq'') or other synthetic substances have increased, causing overdoses that are difficult to reverse with naloxone alone. The constantly evolving synthetic opioid market makes it challenging to respond effectively."}, {"h": "Response", "p": "Key responses include widespread distribution of naloxone to reverse overdoses, drug checking to identify substances, safe consumption facilities, and expansion of medication-assisted treatment. The global spread of fentanyl is a pressing public health concern."}]'::jsonb, advanced_en='[{"h": "The ''Fourth Wave'' of the overdose crisis", "p": "The North American opioid crisis is described in phases: prescription opioids → heroin → fentanyl → fentanyl mixed with stimulants/sedatives. Fentanyl has fundamentally changed the crisis in terms of lethality."}, {"h": "Limitations of naloxone", "p": "Due to fentanyl''s potency, multiple doses of naloxone may be needed, and when mixed with xylazine, the opioid antagonist is ineffective against some effects. This calls for high-dose formulations and new response strategies."}, {"h": "Dilemmas in supply-side responses", "p": "Synthetic opioids are potent in small amounts, making trafficking enforcement difficult, and precursor chemical regulations are circumvented by manufacturers altering chemical structures. Supply-side interventions alone have significant limitations, highlighting the need for health-centered approaches."}]'::jsonb, updated_at=now() WHERE id='fentanyl-synthetic-opioids';
UPDATE encyclopedia_terms SET definition_en='A phenomenon in which past perceptual experiences suddenly recur without substance use after hallucinogen consumption. If persistent and repeated, it can lead to hallucinogen persisting perception disorder (HPPD), and the term is also used to refer to intrusive re-experiencing of trauma.', example_en='Example: Long after a hallucinogen experience, visual afterimages or distortions suddenly appear.', body_en='[{"h": "What It Is", "p": "Flashbacks are a phenomenon in which past perceptual experiences suddenly recur without substance use after hallucinogen consumption. The term is also used to refer to intrusive re-experiencing of trauma."}, {"h": "How It Manifests", "p": "Long after a hallucinogen experience, perceptual abnormalities such as visual afterimages or distortions may suddenly appear. They are usually temporary but can cause anxiety if repeated."}, {"h": "If Persistent", "p": "If perceptual abnormalities persist and recur, they can lead to hallucinogen persisting perception disorder (HPPD). However, this is relatively rare, and most perceptual changes resolve over time."}, {"h": "Trauma Flashbacks", "p": "Flashbacks can also refer to vivid re-experiencing of traumatic memories in PTSD. In this case, it becomes a point where addiction and trauma intersect."}]'::jsonb, advanced_en='[{"h": "HPPD", "p": "Hallucinogen persisting perception disorder (HPPD) is a condition in which perceptual abnormalities persist long after hallucinogen use. Its frequency and mechanisms are not fully understood, but it causes significant distress in some individuals."}, {"h": "Two Meanings", "p": "''Flashback'' refers to two different phenomena: perceptual re-experiencing after hallucinogens and traumatic re-experiencing. The meaning differs by context, and trauma flashbacks are linked to self-medication motives in addiction."}, {"h": "Vicious Cycle with Anxiety", "p": "Anxiety about flashbacks can itself worsen the experience. Reassurance and anxiety management are key to coping."}]'::jsonb, updated_at=now() WHERE id='flashbacks';
UPDATE encyclopedia_terms SET definition_en='Food addiction is repeated craving and loss-of-control eating of specific foods, especially high-sugar or high-fat ones. Reward-circuit involvement similar to substance addiction is reported, but it is not an established standalone diagnosis and overlaps with eating disorders such as binge-eating disorder. The engineering of highly processed foods is argued to fuel it.', example_en='Compulsively eating a specific ultra-processed food even when not hungry, followed by guilt.', body_en='[{"h": "What it is", "p": "Food addiction refers to a state of recurrent craving for and loss of control over eating certain foods high in sugar and fat. Involvement of reward circuitry similar to substance addiction is reported, but it is not established as an independent diagnosis and overlaps conceptually with eating disorders such as binge-eating disorder."}, {"h": "How it appears", "p": "A cycle repeats: one cannot control eating a certain food (mainly ultra-processed) even without hunger and continues, then feels guilt. Attempts to cut back fail, and strong craving for a specific food is triggered by stress or emotion."}, {"h": "Is food designed?", "p": "There is a point that highly processed foods combine sugar, fat, salt, and texture to maximize the brain''s reward. Strong rewards rare in natural foods fuel repeated eating. This is the point that makes it hard to see as a matter of individual restraint alone."}, {"h": "Response", "p": "Identifying ''what the trigger is'' (a specific food, emotion, or situation) and addressing the link between that food and emotion is key. Extreme restriction can actually prompt binging and requires caution, and if an eating disorder is suspected, professional help is needed. Providing alternatives for emotional regulation is the fundamental response."}]'::jsonb, advanced_en='[{"h": "Concept and diagnostic debate", "p": "Debate continues over whether ''food addiction'' is a distinct entity, another expression of binge-eating disorder, or an addiction to a specific ingredient (sugar, etc.). Tools like the Yale Food Addiction Scale attempt measurement by applying substance-addiction criteria to food, but the very validity of the concept remains unresolved."}, {"h": "Ingredient or behavior", "p": "One core debate is whether the object of addiction is a ''specific ingredient like sugar'' or the ''act of eating.'' Animal studies sometimes show addiction-like patterns with intermittent sugar intake, but evidence for ingredient-specific addiction in humans is still contested."}, {"h": "Relationship with eating disorders", "p": "The food-addiction concept overlaps substantially with binge-eating disorder. Careful review is therefore required of whether treating it as a separate ''addiction'' is clinically useful or adds stigma. An approach that does not encourage extreme dietary restriction is especially important."}]'::jsonb, updated_at=now() WHERE id='food-addiction';
UPDATE encyclopedia_terms SET definition_en='A 12-step-based mutual aid group for recovery from gambling problems, addressing the financial and relational harms of gambling disorder.', example_en='Example: A peer support group where individuals recover together from lives devastated by gambling.', body_en='[{"h": "What Is It", "p": "Gamblers Anonymous (GA) is a 12-step-based mutual aid group for recovery from gambling problems, addressing the financial and relational harms of gambling disorder."}, {"h": "How It Works", "p": "GA applies the 12-step, sponsor, and meeting structure of AA and NA to gambling problems. Peer support for recovering together from lives devastated by gambling is central."}, {"h": "What Makes It Special", "p": "Although gambling disorder is a behavioral addiction rather than a substance addiction, GA supports recovery based on the shared experience of loss of control and compulsion. It also addresses gambling-specific issues such as resolving financial problems."}, {"h": "What to Consider", "p": "GA is an example of applying the 12-step recovery model to behavioral addiction. Since gambling causes significant financial, legal, and relational harm, combining self-help groups with practical problem-solving support can be effective."}]'::jsonb, advanced_en='[{"h": "Application to Behavioral Addiction", "p": "GA demonstrates that the 12-step model for substance addiction can be applied to behavioral addiction. This also serves as practical evidence for the common mechanisms underlying substance and behavioral addictions."}, {"h": "Gambling-Specific Challenges", "p": "Gambling disorder is marked by financial ruin, debt, and legal issues, so GA also addresses recovery from these practical harms. Relationship recovery (with family) is also an important component."}, {"h": "Evidence and Complementarity", "p": "The evidence for GA''s effectiveness is more limited than that for AA, and it is noted that combining GA with professional treatment such as cognitive-behavioral therapy may be more effective. Combining self-help and professional treatment is recommended."}]'::jsonb, updated_at=now() WHERE id='gamblers-anonymous';
UPDATE encyclopedia_terms SET definition_en='Gaming disorder is impaired control over gaming, prioritizing it over other activities, and continued or escalating play despite harm, typically for 12 months or more. It is formally recognized in ICD-11, while DSM-5-TR lists ''internet gaming disorder'' only as a condition for further study. The vast majority of players are not disordered—functional impairment is the key threshold.', example_en='Neglecting school, work, sleep and meals to keep playing, unable to cut back as relationships fall apart.', body_en='[{"h": "What it is", "p": "Gaming disorder is losing control over gaming, prioritizing it over other activities, and continuing or escalating despite negative consequences. Diagnosis is typically considered when it persists 12 months or more with clear impairment of daily functioning. Most gamers do not meet this threshold; the core issue is not ''playing a lot'' but loss of control and functional impairment."}, {"h": "How it progresses", "p": "Games densely provide clear goals, immediate rewards, achievement, and social connection. When gaming fills the competence and belonging hard to obtain in reality, absorption gradually tilts toward escape and compulsion. Sleep, meals, study, and work get postponed for gaming''s sake; cutting back brings anxiety and irritability; and relationship conflict and declining performance follow."}, {"h": "Why it is a problem", "p": "Games themselves are not bad—the problem arises when control is lost. Especially in growing adolescents, when sleep, study, and relationships collapse together, development can be affected. Risk grows when gambling-like elements such as loot boxes are combined. Conversely, healthy gaming also has the positive functions of stress relief and social connection, which must be considered together."}, {"h": "Response and recovery", "p": "Recovery focuses on regaining control rather than quitting gaming entirely. Important elements include skills to self-manage time and situations, recovering in reality the needs (competence, belonging) gaming had substituted for, and addressing co-occurring depression, anxiety, and ADHD. For adolescents, family understanding and alternative activities work better than punishment and blocking alone."}]'::jsonb, advanced_en='[{"h": "International differences over diagnosis", "p": "Gaming disorder is a formal diagnosis in ICD-11, but DSM-5-TR places ''internet gaming disorder'' in an appendix as requiring further study. This difference reflects the sufficiency of evidence, concerns about pathologizing normal leisure, and entangled cultural and industry interests. The sensitivity and specificity of diagnostic criteria and the variance in prevalence estimates remain under discussion."}, {"h": "Risk factors and comorbidity", "p": "Gaming disorder rarely comes alone; it commonly co-occurs with depression, anxiety, ADHD, and social anxiety. It is therefore clinically important to distinguish whether gaming is cause or consequence—whether it is self-medication soothing distress. Its combination with gambling-like revenue models such as loot boxes is flagged as a new risk blurring the boundary between gaming and gambling disorders."}, {"h": "Social and industry context", "p": "Games are precisely engineered at the design stage to maximize absorption (variable rewards, progression locks, social-pressure mechanisms). Approaches emphasizing only individual restraint therefore have limits, and the role of user-protection design and regulation is discussed alongside. In Korea, where the game industry and health policy are sharply intertwined, the social controversy over introducing a disease code is a particularly prominent case."}]'::jsonb, updated_at=now() WHERE id='gaming-disorder';
UPDATE encyclopedia_terms SET definition_en='A substance identified under the hypothesis that the use of relatively mild substances can lead to the use of stronger substances. There is active academic debate about whether this relationship is causal or whether common vulnerabilities and environments explain both uses. It is more accurate to understand it as a complex interaction of risk factors rather than a simple causal narrative.', example_en='Example: Early-age smoking or drinking is statistically associated with later use of other drugs, but whether it is a cause or due to common background factors is debatable.', body_en='[{"h": "What is it?", "p": "Gateway drugs are a concept related to the hypothesis that the use of certain substances (e.g., cannabis, nicotine, alcohol) serves as a ''gateway'' to the subsequent use of stronger substances."}, {"h": "What does it claim?", "p": "It claims that early use of relatively accessible substances lowers the threshold for later use of other substances. This idea frequently appears in discussions of adolescent prevention."}, {"h": "There is debate", "p": "The gateway hypothesis has been criticized for potentially mistaking correlation for causation. Early substance use and later use may both stem from common vulnerabilities (environment, temperament)."}, {"h": "What should be considered?", "p": "The gateway concept suggests the importance of preventing early use, but accepting it as a simple causal scheme can lead to misunderstandings. Caution is needed to distinguish between correlation, causation, and common factors."}]'::jsonb, advanced_en='[{"h": "The issue of correlation and causation", "p": "The core debate of the gateway hypothesis is whether correlation can be seen as causation. While early users are more likely to use other substances later, it is unclear whether this is ''due to the gateway substance.''"}, {"h": "Common vulnerability explanation", "p": "An alternative explanation is that early substance use and later use both arise from common vulnerabilities (impulsivity, adverse environment, peers). From this perspective, gateway substances are indicators, not causes."}, {"h": "Caution in policy implications", "p": "The gateway hypothesis is used as a rationale for regulating specific substances, but given the uncertainty of causation, caution is required in policy application. The importance of preventing early use is acknowledged separately."}]'::jsonb, updated_at=now() WHERE id='gateway-drugs';
UPDATE encyclopedia_terms SET definition_en='This research area examines the substantial contribution of genetic factors to addiction vulnerability. Twin, family, and adoption studies estimate heritability at approximately 40–60%, but genetics confer predisposition, not destiny, and expression depends on interaction with environment and experience. Addiction is polygenic, involving many genes with small effects, and gene-environment interactions determine actual onset.', example_en='Example: Individuals whose parents had alcohol use disorder may have higher vulnerability, but many live without problems in stable environments with adequate coping resources.', body_en='[{"h": "What It Is", "p": "Genetics of addiction refers to the significant contribution of genetic factors to addiction vulnerability. Twin and family studies suggest that about half of the risk for addiction is genetic."}, {"h": "Genetics Is Not Everything", "p": "Genetics means ''higher vulnerability,'' not ''determined to become addicted.'' Expression occurs through interaction with environment and experience; even with genetic risk, one may not develop addiction depending on environmental factors."}, {"h": "What Is Inherited", "p": "Differences in metabolism and response to specific substances, traits such as impulsivity and reward sensitivity, and vulnerability to mental disorders are genetically transmitted, contributing to addiction risk. It is not a single gene but the combined small effects of many genes."}, {"h": "Implications", "p": "Understanding genetics shows that addiction is not a matter of weak will, reducing stigma. It also provides a basis for preventive attention and early intervention in individuals with family history."}]'::jsonb, advanced_en='[{"h": "Polygenicity", "p": "Addiction is a polygenic trait resulting from the combined small effects of numerous genes, not a few strong genes. Therefore, there is no single ''addiction gene,'' and polygenic risk score research is ongoing."}, {"h": "Gene-Environment Interaction", "p": "Genetic vulnerability is expressed through interaction with environmental factors such as stress, trauma, and substance exposure. Epigenetics shows that environment regulates gene expression, influencing addiction vulnerability."}, {"h": "Substance Specificity and Commonality", "p": "Both substance-specific factors (e.g., alcohol metabolism genes) and factors common to multiple addictions (e.g., impulsivity, reward sensitivity) operate together. This suggests both shared and specific vulnerability pathways in addiction."}]'::jsonb, updated_at=now() WHERE id='genetics-addiction';
UPDATE encyclopedia_terms SET definition_en='A neuroscientist who emphasized the stress and negative reinforcement dimensions of addiction, explaining later-stage addiction through allostasis and the ''dark side of addiction'' concept. He illuminated the shift in addiction motivation beyond pleasure-seeking.', example_en='Example: Research establishing the understanding that motivation in later-stage addiction shifts from pleasure to pain avoidance.', body_en='[{"h": "Who is he?", "p": "George Koob is a neuroscientist who emphasized the stress and negative reinforcement dimensions of addiction, explaining later-stage addiction through allostasis and the ''dark side of addiction'' concept."}, {"h": "What did he do?", "p": "He explained the later stage of addiction, where the focus shifts from pleasure-seeking to pain avoidance, through changes in the brain''s stress systems and a shift in reward set point (allostasis)."}, {"h": "Why is it important?", "p": "Koob''s research moved beyond the view of addiction solely as pleasure-seeking, highlighting the chronic distress and negative reinforcement in later-stage addiction. It provided a framework for understanding the shift in addiction motivation."}, {"h": "What did he leave behind?", "p": "The concepts of allostasis and the ''dark side'' have become key frameworks for understanding anhedonia in later-stage addiction and early recovery. They complemented the reward-centered model with a stress dimension."}]'::jsonb, advanced_en='[{"h": "Illumination of negative reinforcement", "p": "Koob''s contribution lies in neuroscientifically establishing the negative reinforcement (pain avoidance) dimension of addiction. This fills the motivational gap in later-stage addiction that reward-centered explanations missed."}, {"h": "Allostasis theory", "p": "His concept of allostasis posits that repeated use shifts the brain''s set point itself, leading to chronic dysphoria. This theory explains the ''dark side'' of later-stage addiction."}, {"h": "Role of stress systems", "p": "Koob emphasized the role of brain stress systems (e.g., CRF) in withdrawal, craving, and relapse. This aligns with the clinical reality that stress is a powerful trigger for relapse."}]'::jsonb, updated_at=now() WHERE id='george-koob';
UPDATE encyclopedia_terms SET definition_en='A central nervous system depressant that produces intoxication and sedation, with a narrow margin between safe and dangerous doses, posing high risks of loss of consciousness and respiratory depression. Its colorless, odorless nature is also associated with drug-facilitated crimes.', example_en='Example: Even small dose differences can lead to danger, making recreational use particularly risky.', body_en='[{"h": "What is it", "p": "GHB is a central nervous system depressant that produces intoxication and sedation, with a narrow margin between safe and dangerous doses, posing high risks of loss of consciousness and respiratory depression."}, {"h": "Why is it dangerous", "p": "Even a slight increase in dose can cause loss of consciousness or respiratory depression, making recreational use especially risky. Combining it with other depressants like alcohol sharply increases the danger."}, {"h": "Association with drug-facilitated crimes", "p": "Due to its colorless, odorless nature, it is sometimes misused in drug-facilitated crimes by being secretly added to drinks to incapacitate victims."}, {"h": "What to watch out for", "p": "GHB carries the risks of a narrow safety margin and rapid loss of consciousness. Awareness of the dangers of combined use and the potential for drug-facilitated crimes is important."}]'::jsonb, advanced_en='[{"h": "Narrow safety margin", "p": "GHB has a close proximity between effective and dangerous doses, making precise dose control difficult and errors potentially fatal. This characteristic makes recreational use particularly hazardous."}, {"h": "Dependence and withdrawal", "p": "Repeated use can lead to dependence, and GHB withdrawal can be severe and dangerous, requiring medical management. It presents a dangerous withdrawal pattern typical of depressants."}, {"h": "Criminal misuse and response", "p": "The misuse of GHB in drug-facilitated crimes highlights the need for responses focusing on the perpetrator rather than victim-blaming, as well as awareness education."}]'::jsonb, updated_at=now() WHERE id='ghb';
UPDATE encyclopedia_terms SET definition_en='GLP-1 receptor agonists (e.g., semaglutide) used for obesity and diabetes have been observed to reduce cravings for alcohol, nicotine, and other substances, leading to active research into their potential as addiction treatments. The mechanism is thought to involve the brain''s reward circuitry, but this is not yet an established indication for addiction and remains under investigation. The intersection with food addiction is also of interest.', example_en='Example: Reports from individuals using GLP-1 drugs for weight loss who also experienced reduced cravings for alcohol or cigarettes have spurred research.', body_en='[{"h": "What is it", "p": "GLP-1 receptor agonists (e.g., semaglutide) used for obesity and diabetes have been observed to reduce cravings for alcohol, nicotine, and other substances, leading to active research into their potential as addiction treatments. This is not yet an established indication for addiction."}, {"h": "How did it gain attention", "p": "Research was triggered by reports from individuals using GLP-1 drugs for weight loss or diabetes who also experienced reduced cravings for alcohol or cigarettes. The hypothesis is that the effect of reducing food cravings may extend to cravings for other addictive substances."}, {"h": "Proposed mechanism", "p": "A leading hypothesis is that GLP-1 drugs act on the brain''s reward circuitry, reducing the rewarding effects of substances and food. If they reduce the response to rewards themselves, they may have potential applicability across multiple addictions, which is noteworthy."}, {"h": "Cautious optimism", "p": "While promising, this is still a research area. More clinical evidence is needed for GLP-1 drugs to become established addiction treatments. Their efficacy, safety, and appropriate populations are still being investigated. Exaggerated expectations should be avoided, and evidence accumulation should be monitored."}]'::jsonb, advanced_en='[{"h": "Early stage of research", "p": "Evidence for the addiction treatment effects of GLP-1 drugs is at an early stage, with signals from animal studies, observational studies, and small-scale trials. Results from large-scale randomized controlled trials are needed, and these drugs are not currently a standard treatment for addiction."}, {"h": "Implications of a common reward circuit mechanism", "p": "If GLP-1 drugs commonly reduce cravings for food, alcohol, nicotine, and other substances, this could support the shared reward mechanisms between food addiction and substance addiction. It suggests the possibility of a common therapeutic target across addictions."}, {"h": "Access and equity issues", "p": "GLP-1 drugs face issues of demand, cost, and supply. If their use expands to addiction treatment, access equity could become a concern. Even if new drugs become recovery tools, policy challenges regarding who can access them will arise."}]'::jsonb, updated_at=now() WHERE id='glp1-and-craving';
UPDATE encyclopedia_terms SET definition_en='A group of substances that significantly alter perception, thought, and emotion, causing hallucinations or altered consciousness. They are divided into classical hallucinogens (LSD, psilocybin, mescaline) that act on the serotonin system and dissociative hallucinogens (ketamine, PCP). Physical dependence is relatively low, but there are risks of psychological distress, ''bad trips,'' and persistent perceptual disorders.', example_en='Example: Even with the same substance, the experience can vary greatly depending on the psychological state and environment (set and setting).', body_en='[{"h": "What Are They", "p": "Hallucinogens are a group of substances that significantly alter perception, thought, and emotion, causing hallucinations or altered consciousness. They are divided into classical hallucinogens (LSD, psilocybin, mescaline) that act on the serotonin system and dissociative hallucinogens (ketamine, PCP)."}, {"h": "What Are the Risks", "p": "Physical dependence is relatively low, but there are risks of unpredictable psychological reactions (''bad trips''), rarely persistent perceptual disorder (HPPD), and accidents due to impaired judgment. Underlying mental health conditions increase the risk."}, {"h": "Set and Setting", "p": "The hallucinogen experience is heavily influenced by the individual''s psychological state (set) and environment (setting). The same substance and dose can produce entirely different experiences depending on context, and this principle is a key condition for therapeutic use."}, {"h": "Therapeutic Research", "p": "Some classical hallucinogens are being studied in controlled clinical settings for potential treatment of depression, PTSD, and addiction. However, this is distinct from recreational use and involves controlled settings with professional guidance."}]'::jsonb, advanced_en='[{"h": "Serotonergic Action", "p": "Classical hallucinogens primarily act on serotonin 5-HT2A receptors, altering perception and cognition. This action is proposed as the neural basis for temporary ego boundary dissolution and novel insight experiences."}, {"h": "HPPD and Persistent Effects", "p": "Some users report persistent perceptual abnormalities after use, known as HPPD, but its frequency and mechanism are not fully understood. Most perceptual changes are temporary, and this should be approached with caution."}, {"h": "Therapeutic Renaissance and Caution", "p": "Therapeutic research on hallucinogens has become active, often called the ''psychedelic renaissance,'' but evidence is still accumulating. It is important to guard against exaggerated expectations and risks of self-medication, distinguishing between controlled research contexts and recreational use."}]'::jsonb, updated_at=now() WHERE id='hallucinogens';
UPDATE encyclopedia_terms SET definition_en='A hangover is a collection of aftereffects such as headache, nausea, fatigue, and cognitive impairment following heavy drinking, resulting from a combination of dehydration, sleep disruption, and metabolic byproducts. It is understood as a mild withdrawal and toxic reaction.', example_en='Example: After heavy drinking the previous night, a person experiences headache and lethargy all day, with reduced functioning.', body_en='[{"h": "What is it?", "p": "A hangover is a collection of aftereffects such as headache, nausea, fatigue, and cognitive impairment following heavy drinking. It is understood as a mild withdrawal and toxic reaction."}, {"h": "What causes it?", "p": "Dehydration, sleep disruption, alcohol metabolites (e.g., acetaldehyde), and inflammatory responses all contribute. It is not a single cause but a combination of multiple mechanisms."}, {"h": "What does it mean?", "p": "A hangover is a signal of the burden alcohol has placed on the body. Repeated severe hangovers can serve as an opportunity to reflect on drinking patterns."}, {"h": "What is good to know?", "p": "There is no definitive cure; hydration and rest help. ''Hair of the dog'' only temporarily delays withdrawal and worsens the problem, and may be a sign of dependence."}]'::jsonb, advanced_en='[{"h": "Understanding as mild withdrawal", "p": "Some hangover symptoms can be seen as a mild rebound (withdrawal) as alcohol leaves the system. This shows that even though alcohol seems mild, it causes neuroadaptation."}, {"h": "Individual differences", "p": "The severity of hangovers varies greatly by genetics (related to alcohol metabolism), hydration, sleep, and concurrent substance use. Differences in metabolic enzymes affect hangover susceptibility."}, {"h": "Social and economic impact", "p": "Productivity loss and accidents due to hangovers incur significant social costs. Beyond individual discomfort, it is a public health concern."}]'::jsonb, updated_at=now() WHERE id='hangover';
UPDATE encyclopedia_terms SET definition_en='A public health approach that focuses on reducing the harms associated with addiction without requiring complete abstinence. It includes naloxone distribution, syringe exchange, safe consumption sites, and drug checking services. By not mandating abstinence, it increases accessibility. It is complementary to abstinence-oriented approaches but also maintains a philosophical tension with them.', example_en='Example: Providing naloxone and safety information to prevent fatal overdose for individuals who are unable to stop immediately, thereby saving lives.', body_en='[{"h": "What It Is", "p": "Harm reduction is a public health approach that focuses on reducing the harms associated with addiction without requiring complete abstinence. It includes naloxone distribution, syringe exchange, safe consumption sites, and drug checking services. By not mandating abstinence, it increases accessibility."}, {"h": "Core Idea", "p": "The core idea is to ensure that even those who cannot stop immediately do not die or become severely ill. Instead of making complete recovery the sole goal, it first reduces the harms that occur along the way, such as fatal overdose, infection, and crime. Preserving life is seen as a prerequisite for recovery."}, {"h": "What Methods Are Used", "p": "Representative methods include naloxone to reverse overdose, syringe exchange to prevent infection, supervised consumption sites to promote safer use, drug checking to filter out lethal substances, and opioid agonist therapy. These also serve as points of contact that connect users to health services rather than punishment."}, {"h": "Relationship with Abstinence-Oriented Approaches", "p": "Harm reduction and abstinence-oriented approaches can be understood as complementary rather than conflicting. Harm reduction serves as the first point of contact that saves lives and connects people to treatment, from which they can move toward recovery and abstinence. However, there is also a philosophical tension between the two approaches."}]'::jsonb, advanced_en='[{"h": "Evidence and International Status", "p": "Harm reduction has strong evidence in reducing HIV and hepatitis transmission and fatal overdoses, and is supported by international organizations such as UNAIDS and WHO. Recently, resolutions recognizing harm reduction have been adopted at the UN level, establishing it as an international norm."}, {"h": "Frontline of Value Conflicts", "p": "Harm reduction is the most contentious point of value conflict in recovery policy. It faces moral criticism that it tolerates or encourages drug use, while evidence-based advocates argue it is a pragmatic intervention that saves lives. The same data can be interpreted differently depending on the value framework."}, {"h": "Position within the Recovery Continuum", "p": "There is a growing perspective that views harm reduction not as the opposite of recovery but as a stage within the recovery continuum. Preserving life and maintaining relationships can serve as a foundation for later treatment and recovery. This view aligns with the Recovery-Oriented Systems of Care (ROSC) framework, which connects prevention through recovery as a continuum."}]'::jsonb, updated_at=now() WHERE id='harm-reduction';
UPDATE encyclopedia_terms SET definition_en='A potent semi-synthetic opioid derived from morphine, producing rapid and intense euphoria with high risks of dependence and overdose. Injection use increases infection risk, and recent adulteration with fentanyl has greatly elevated lethality.', example_en='Example: A trajectory where dependence on prescription opioids leads to switching to cheaper and stronger heroin.', body_en='[{"h": "What is it", "p": "Heroin is a potent semi-synthetic opioid derived from morphine, producing rapid and intense euphoria with high risks of dependence and overdose. It is a representative illegal opioid."}, {"h": "How is it dangerous", "p": "As strong as the euphoria is, the risk of overdose (respiratory depression) is high, and injection use adds risks of HIV, hepatitis, and other infections. Recently, adulteration with fentanyl has greatly increased lethality."}, {"h": "What pathways lead to it", "p": "A common pathway is developing dependence on prescription opioids and then switching to cheaper and stronger heroin. Stricter regulation of prescription drugs has paradoxically encouraged this shift."}, {"h": "Treatment", "p": "Heroin use disorder is effectively managed with medication-assisted treatment such as methadone and buprenorphine. Harm reduction measures like naloxone and safe consumption sites save lives. Some countries use heroin-assisted treatment (HAT) for chronic users."}]'::jsonb, advanced_en='[{"h": "Rapid delivery and dependence", "p": "Heroin reaches the brain quickly, producing strong reward, and this speed underlies its high dependence potential. The route of administration (injection, inhalation) affects risk."}, {"h": "Threat of fentanyl adulteration", "p": "With fentanyl mixed into illegal heroin, users are increasingly exposed to lethal doses without their knowledge. This has fundamentally changed the risk landscape of heroin use."}, {"h": "Harm reduction and HAT", "p": "In managing heroin use disorder, harm reduction (naloxone, syringe exchange, safe consumption sites) and heroin-assisted treatment (HAT) have accumulated evidence. HAT in countries like Switzerland has shown effectiveness for chronic, treatment-resistant users."}]'::jsonb, updated_at=now() WHERE id='heroin';
UPDATE encyclopedia_terms SET definition_en='Hypersexuality is an excessive heightening of sexual urges and activity that dominates daily life and relationships. It is the core feature of compulsive sexual behavior disorder and can also arise as a side effect of certain neurological conditions or medications, so identifying the cause matters.', example_en='Unexpected hypersexuality emerging as a side effect in someone taking dopamine-agonist medication for Parkinson''s disease.', body_en='[{"h": "What it is", "p": "Hypersexuality refers to a state in which sexual urges and activity are excessively heightened, dominating daily life and relationships. It is a core feature of compulsive sexual behavior disorder, but importantly, its causes are diverse."}, {"h": "The cause is not one thing", "p": "Hypersexuality may be part of compulsive sexual behavior disorder, but it can also appear from certain neurological conditions (brain injury, dementia, etc.) or as a side effect of specific drugs (e.g., dopamine agonists used to treat Parkinson''s disease). It may also appear as a symptom of a manic episode. Differentiating the cause is therefore the starting point of treatment."}, {"h": "Why differentiation matters", "p": "Because the response differs entirely by cause. If it is a drug side effect, medication adjustment; if mania, mood-disorder treatment; if compulsive sexual behavior, psychotherapy comes first. Treating it as a single problem by looking only at the surface symptom misses accurate help."}, {"h": "Response", "p": "First confirm the underlying cause through medical and psychiatric evaluation. If a neurological condition, drug, or mood disorder is the background, address that; if compulsive sexual behavior, combine psychotherapy with emotional and relational recovery. A non-stigmatizing approach to finding the cause is key."}]'::jsonb, advanced_en='[{"h": "Symptom or disorder", "p": "Hypersexuality is more accurately understood as a ''symptom'' appearing across various conditions than as an independent diagnosis in itself. The scope of differential diagnosis is broad—compulsive sexual behavior disorder, bipolar mania, neurocognitive disorder, iatrogenic (drug-induced), and more."}, {"h": "Iatrogenic hypersexuality", "p": "Impulse-control disorders (hypersexuality, pathological gambling, compulsive shopping, etc.) appearing during dopamine-agonist treatment in Parkinson''s disease and the like offer a clinical window into how the dopamine reward circuit is involved in addictive behavior. That it improves with drug adjustment underscores the importance of differentiating cause."}, {"h": "Caution in assessment", "p": "Because the ''normal'' range of sexual desire varies greatly by individual and culture, judging hypersexuality must be done carefully by synthesizing loss of control and functional impairment, and the presence of an underlying cause, rather than frequency itself."}]'::jsonb, updated_at=now() WHERE id='hypersexuality';
UPDATE encyclopedia_terms SET definition_en='A group of disorders characterized by the inability to resist impulses that are harmful to oneself or others. It includes pathological fire-setting (pyromania), pathological stealing (kleptomania), intermittent explosive disorder, and others, with considerable conceptual overlap with behavioral addictions. A common cycle is tension buildup before the impulsive act and relief or pleasure afterward.', example_en='Example: A person who repeatedly fails to suppress an impulse arising in specific situations, engages in harmful behavior, and then experiences a cycle of regret and relief.', body_en='[{"h": "What is it?", "p": "Impulse control disorders are a group of disorders in which individuals fail to resist impulses that are harmful to themselves or others. They include pathological stealing (kleptomania), fire-setting (pyromania), intermittent explosive disorder, and others."}, {"h": "Relationship with addiction", "p": "Impulse control disorders conceptually overlap with behavioral addictions. In fact, gambling disorder was previously classified under impulse control disorders before being moved to the addiction category. Both share a common feature of failure to inhibit impulses."}, {"h": "How does it manifest?", "p": "A common pattern is tension and impulse buildup before the act, followed by relief and pleasure during the act. This resembles the craving-use-relief cycle of addiction."}, {"h": "What should be considered?", "p": "The boundary between impulse control disorders and addiction is fluid, and classification continues to evolve. The key is understanding and addressing the repeated harmful behaviors resulting from failure to control impulses."}]'::jsonb, advanced_en='[{"h": "Reclassification with addiction", "p": "The move of gambling disorder from impulse control disorders to the addiction category illustrates the fluid boundary between the two categories. There is ongoing debate about which repetitive behaviors should be seen as impulse control problems and which as addictions."}, {"h": "Impulsivity and compulsivity", "p": "Impulse control disorders are understood on a spectrum of impulsivity (immediate action) and compulsivity (repetition). Like addiction, they may shift from initial impulse-driven to later compulsion-driven patterns."}, {"h": "Commonality in treatment", "p": "Impulse control disorders and addiction share similar treatment approaches, such as cognitive-behavioral therapy and impulse coping training. This commonality supports the close relationship between the two categories."}]'::jsonb, updated_at=now() WHERE id='impulse-control-disorder';
UPDATE encyclopedia_terms SET definition_en='Incentive salience is the motivational prominence that the brain assigns to reward-associated cues, causing them to elicit strong ''wanting.'' It can be dissociated from ''liking,'' explaining the paradox of addiction where one strongly wants something even when it is no longer pleasurable.', example_en='Example: The contradiction of reporting that use is no longer enjoyable yet experiencing intense craving in the presence of cues.', body_en='[{"h": "What is it", "p": "Incentive salience is the motivational prominence that the brain assigns to reward-associated cues, causing them to elicit strong ''wanting.''"}, {"h": "Wanting and liking", "p": "The core of this concept is the dissociation between ''wanting'' and ''liking.'' Even when one does not like or enjoy something, one can strongly want it—this is the operation of incentive salience."}, {"h": "How does it explain addiction", "p": "Repeated use assigns excessive salience to substances or cues, making them intensely ''wanted'' above all else. This explains the paradox of addiction: craving persists even when use is no longer pleasurable."}, {"h": "What does it imply", "p": "This perspective views addiction not as a pursuit of pleasure but as a problem of distorted motivation. Therefore, recovery involves not only restoring pleasure but also recalibrating motivation and salience."}]'::jsonb, advanced_en='[{"h": "Theoretical background", "p": "Incentive salience is a core concept of the incentive-sensitization theory by Robinson and Berridge. Repeated use sensitizes the ''wanting'' circuitry, creating intense craving independent of liking."}, {"h": "Role of dopamine", "p": "Dopamine is involved more in ''wanting'' and salience attribution than in pleasure (liking). This distinction corrects the common notion that dopamine equals pleasure and illuminates the motivational nature of addiction."}, {"h": "Cues and relapse", "p": "Salience-assigned cues persist for a long time, triggering strong craving and relapse even after abstinence. This persistence is one mechanism that makes addiction a chronic disease."}]'::jsonb, updated_at=now() WHERE id='incentive-salience';
UPDATE encyclopedia_terms SET definition_en='Inhalants are volatile substances such as glue, butane, aerosols, and solvents that are inhaled to achieve intoxication. They are cheap and easily accessible, making their abuse a particular problem among adolescents. Even a single use can cause acute cardiac arrest (''sudden sniffing death''), and repeated use leads to cumulative brain and nerve damage.', example_en='Example: Inhaling easily accessible household products can lead to fatal cardiac arrest even on first use.', body_en='[{"h": "What Are Inhalants?", "p": "Inhalants are volatile substances such as glue, butane, aerosols, and solvents that are inhaled to achieve intoxication. They are cheap and easily accessible, making their abuse a particular problem among adolescents."}, {"h": "Why Are They Fatal?", "p": "Even a single use of inhalants can cause acute cardiac arrest (''sudden sniffing death''). The fact that they can be unpredictably lethal distinguishes them from other substances."}, {"h": "Harm from Repeated Use", "p": "Repeated inhalation causes cumulative damage to the brain, nerves, liver, and kidneys. The impact on the developing adolescent brain is especially severe."}, {"h": "What Is the Problem?", "p": "Because inhalants are household products, restricting access is difficult, and they are often the first substance of abuse among younger age groups. Preventive education and early intervention are key responses."}]'::jsonb, advanced_en='[{"h": "Sudden Sniffing Death", "p": "Inhalants make the heart hypersensitive to adrenaline, so that stimuli such as surprise or exercise can trigger fatal arrhythmias. This mechanism explains why even a single use can be lethal."}, {"h": "Social Vulnerability", "p": "Inhalant abuse is closely linked to social vulnerabilities such as poverty and neglect. Due to their low cost and easy accessibility, they are particularly prominent among younger individuals in environments with limited access to other substances."}, {"h": "Prevention Dilemma", "p": "There is a dilemma that preventive education about the risks may inadvertently provide information, so careful message design is required for inhalant prevention. Access control and addressing vulnerabilities must go hand in hand."}]'::jsonb, updated_at=now() WHERE id='inhalants';
UPDATE encyclopedia_terms SET definition_en='The direction of international drug and addiction policy centered on UNODC (United Nations Office on Drugs and Crime) and WHO (World Health Organization), which addresses both supply and demand while aiming for a balanced approach based on public health and human rights. It defines addiction as a preventable and treatable multifactorial health disorder, and there is a growing emphasis on recovery management and social reintegration.', example_en='Activities where UNODC and WHO jointly evaluate the quality of treatment systems in each country through collaborative programs and recommend alternative measures that divert individuals from punishment to treatment.', body_en='[{"h": "What It Is", "p": "International drug policy is based on three international drug control conventions, with the purpose of ''the health and welfare of humankind,'' pursuing both supply suppression and demand reduction. UNODC and WHO define addiction not as a crime but as a preventable and treatable multifactorial health disorder, and recommend evidence-based and human rights-based approaches to each country."}, {"h": "Current Direction", "p": "In recent years, the international community has shifted its focus from punishment-oriented approaches to prevention, treatment, and recovery management. UNODC-WHO joint programs evaluate and improve the quality of treatment systems, promote alternative measures that link individuals to treatment instead of criminal punishment, and emphasize rehabilitation and recovery management. Resolutions recognizing harm reduction from a human rights and health perspective have also been adopted."}, {"h": "Emphasis on Reducing Stigma", "p": "International organizations identify stigma as a key barrier to recovery and emphasize a ''person-centered'' approach. Language and policies that view addiction as a treatable disease rather than a moral failing are recommended at the international normative level. This provides an international basis for each country''s stigma reduction policies and recovery-oriented reforms."}, {"h": "Implications", "p": "International norms provide a common framework for individual countries to reference when designing recovery policies. However, there is a significant gap between international recommendations and actual national policies, and how this framework is applied in domestic contexts is crucial. The policies of each country, including South Korea, can be understood in relation to this international trend."}]'::jsonb, advanced_en='[{"h": "Tension Between Human Rights and Control", "p": "Within international drug policy, there is a coexistence of a stream emphasizing ''public health and human rights'' and another emphasizing ''strict control and a drug-free society.'' Some countries justify punitive policies under the banner of ''a drug-free life for the community,'' while human rights organizations and civil society criticize this as stigmatizing and criminalizing users. This tension is also evident within documents of international organizations."}, {"h": "Debate on Compulsory Treatment", "p": "The international community acknowledges that ''compulsory treatment'' can violate human rights, yet it is still implemented in many countries. Evidence-based treatment based on voluntariness is recommended as a principle, but the boundary between criminal justice and treatment, and the justification of intervention without consent, remain ongoing points of debate."}, {"h": "Gap Between Norms and Reality", "p": "International recommendations aim for a public health and human rights-based approach, but actual national policies span a wide spectrum from punishment-centered to health-centered. Due to differences in resources, politics, and culture, international norms are not uniformly implemented in each country, and narrowing this gap remains a challenge for international cooperation."}]'::jsonb, updated_at=now() WHERE id='international-drug-policy';
UPDATE encyclopedia_terms SET definition_en='Intervention is a structured procedure in which family members and professionals help a resistant individual accept treatment. There are differing views on methods and effectiveness depending on the approach, with approaches emphasizing relationship and support over confrontation gaining evidence. The family''s own preparation and recovery must also be addressed.', example_en='Example: A family, with professional guidance, arranges a meeting to recommend treatment to the individual, expressing concern and concrete help rather than blame.', body_en='[{"h": "What It Is", "p": "Intervention is a structured procedure in which family members and professionals help a resistant individual accept treatment. There are differing views on methods and effectiveness depending on the approach, with approaches emphasizing relationship and support over confrontation gaining evidence."}, {"h": "Why It Is Needed", "p": "Due to denial, a hallmark of addiction, it often takes a long time for individuals to acknowledge their problem and seek help. During this time, harm increases, so intervention by the surrounding community in a structured way helps facilitate treatment entry. However, coercive intervention can damage relationships and backfire."}, {"h": "How It Is Done", "p": "It is effective to recommend treatment in a prepared manner, expressing concern and concrete help rather than blame or confrontation. It is important for the family to approach planfully with professional guidance rather than emotional outbursts, and to have a concrete pathway to treatment ready."}, {"h": "Family Preparation", "p": "Intervention is not just the individual''s issue but a task for the whole family. Without addressing the family''s own burnout and codependency, intervention is difficult to sustain. The family''s recovery and preparation often determine the success or failure of the intervention."}]'::jsonb, advanced_en='[{"h": "Limitations of Confrontational Intervention", "p": "In the past, confrontational interventions (e.g., surprise interventions) that pressured the individual were popular, but they have been criticized for damaging relationships and increasing resistance. Recently, approaches like CRAFT, which train family members in relational skills to non-confrontationally facilitate treatment entry, show better evidence."}, {"h": "Boundary Between Autonomy and Coercion", "p": "Intervention involves a tension between respecting the individual''s autonomy and the need for treatment. The boundary between support and coercion is ambiguous, and this connects to debates on the legitimacy of compulsory treatment. The key is a balance that promotes change without harming relationships."}, {"h": "Family Systems Perspective", "p": "Viewing intervention as a family system issue rather than an individual one suggests that changing family interaction patterns leads to lasting change, rather than trying to change one person. This perspective links intervention to family therapy and codependency recovery."}]'::jsonb, updated_at=now() WHERE id='intervention';
UPDATE encyclopedia_terms SET definition_en='A temporary state of mental, behavioral, and physical changes caused by a substance acting on the body. Depending on the substance and dose, it may manifest as euphoria, impaired judgment, ataxia, altered consciousness, and in severe cases, can be life-threatening. It is distinct from long-term addiction.', example_en='Example: An acute state of impaired judgment and balance from a single episode of heavy drinking is different from long-term addiction formed through repeated use.', body_en='[{"h": "What is it", "p": "Intoxication is a temporary state of mental, behavioral, and physical changes caused by a substance acting on the body. It may manifest as euphoria, impaired judgment, ataxia, or altered consciousness."}, {"h": "Different from addiction", "p": "Intoxication is a temporary state resulting from a single use, whereas addiction is a chronic disease formed through repeated use. The two are distinct concepts."}, {"h": "Why is it dangerous", "p": "Severe intoxication can lead to accidents, loss of judgment, loss of consciousness, and even life-threatening overdose. The nature of the risk varies by substance and dose."}, {"h": "What is helpful to know", "p": "The risks of intoxication differ by substance, and combining multiple substances can lead to unpredictable and increased danger. Distinguishing between intoxication and addiction is fundamental to understanding these concepts."}]'::jsonb, advanced_en='[{"h": "Terminological confusion", "p": "The English terms ''intoxication'' and ''addiction'' are both translated as ''중독'' in Korean, causing confusion. The former is an acute state, the latter a chronic disease; this distinction is the starting point for understanding addiction."}, {"h": "Intoxication as an emergency", "p": "Severe intoxication can become an emergency requiring airway management and respiratory support. The risk increases sharply with polysubstance use or overdose."}, {"h": "Connection to law and safety", "p": "Driving or engaging in activities while intoxicated poses safety and legal issues. Regulations on drug-impaired driving and drunk driving target this state."}]'::jsonb, updated_at=now() WHERE id='intoxication';
UPDATE encyclopedia_terms SET definition_en='An early researcher who systematized alcoholism as a progressive disease, laying the academic foundation for the disease model. His ''Jellinek curve'' describes the stages of addiction progression and recovery.', example_en='Example: A turning point in the academic shift that led to viewing addiction not as a moral issue but as a progressive disease.', body_en='[{"h": "Who He Was", "p": "E. M. Jellinek was an early researcher who systematized alcoholism as a progressive disease, laying the academic foundation for the disease model."}, {"h": "What He Did", "p": "He proposed the ''Jellinek curve,'' which describes the progression of alcoholism in stages, and conducted research conceptualizing alcoholism as a disease. He elevated addiction research into the realm of academic study."}, {"h": "Why He Matters", "p": "His research marked a turning point in the academic shift that led to viewing addiction not as a moral issue but as a progressive disease. He contributed to the popularization and institutionalization of the disease model."}, {"h": "His Legacy", "p": "The Jellinek curve provided a framework for understanding the progression and recovery of addiction in stages. However, his typology has since been criticized for oversimplification and overgeneralization."}]'::jsonb, advanced_en='[{"h": "Academic Foundation of the Disease Model", "p": "Jellinek gave academic structure to the concept of addiction as a disease. His work can be seen as a bridge between Benjamin Rush''s early insights and modern neuroscience."}, {"h": "Typology and Its Limitations", "p": "His classification of alcoholism into types and stages was highly influential, but later criticized for overgeneralization and limited evidence. Not all cases follow a single progression path."}, {"h": "Historical Constraints of Research Methods", "p": "Jellinek''s early research faced limitations in sample size and methodology due to the era. Nonetheless, his historical significance in establishing addiction as a systematic research subject is substantial."}]'::jsonb, updated_at=now() WHERE id='jellinek';
UPDATE encyclopedia_terms SET definition_en='A dissociative anesthetic with a dual nature: it is both a recreational drug of abuse and an approved treatment for treatment-resistant depression (e.g., esketamine nasal spray). At low doses, it produces dissociative and hallucinogenic effects; repeated use can cause physical harm such as bladder damage and psychological dependence. Balancing therapeutic potential and abuse risk is a key current debate.', example_en='Example: A patient receives medically supervised ketamine treatment for depression in a clinic, while another person uses it recreationally at clubs and suffers bladder damage.', body_en='[{"h": "What is it", "p": "Ketamine is a dissociative anesthetic that produces dissociative and hallucinogenic effects at low doses. It has a dual nature: it is both a recreational drug of abuse and an approved treatment for treatment-resistant depression (e.g., esketamine nasal spray)."}, {"h": "As a therapeutic agent", "p": "It shows rapid effects in depression that does not respond to conventional antidepressants, and is used in controlled medical settings. It is noted for providing rapid improvement in depression with high suicide risk."}, {"h": "Risks of abuse", "p": "Repeated recreational use can lead to bladder damage (ketamine bladder), cognitive problems, and psychological dependence. The dissociative state impairs risk perception, increasing accident risk."}, {"h": "Balance", "p": "Ketamine has two faces—''controlled treatment'' and ''recreational abuse''—so the key is balancing therapeutic potential with managing abuse risk. Expanding treatment access and preventing abuse must be considered together."}]'::jsonb, advanced_en='[{"h": "Mechanism of action", "p": "Ketamine acts through NMDA receptor antagonism and other pathways distinct from conventional antidepressants; promotion of neuroplasticity is proposed as the mechanism for its rapid antidepressant effects. This unique mechanism explains its value in treatment-resistant depression."}, {"h": "Boundary between treatment and abuse", "p": "Medical esketamine is administered under supervision in controlled settings, whereas recreational or non-medical use carries entirely different risks. It is noted that public interest in treatment may blur this boundary and encourage self-use."}, {"h": "Relationship with psychedelic therapy", "p": "Ketamine is broadly discussed as part of a trend using consciousness-altering substances in therapy, sharing concerns with psychedelic-assisted therapy research. However, its pharmacological and regulatory status differs, so it is treated separately."}]'::jsonb, updated_at=now() WHERE id='ketamine';
UPDATE encyclopedia_terms SET definition_en='Kleptomania is an impulse control disorder characterized by the recurrent inability to resist the urge to steal items that are not needed or of significant monetary value. The cycle of tension before the theft and relief or pleasure during and immediately after the act is distinctive, distinguishing it from ordinary theft for gain. Diagnosis is often delayed due to shame.', example_en='Example: A person who cannot resist the urge to steal a trivial item despite having enough money to pay for it, and subsequently experiences deep guilt.', body_en='[{"h": "What is it?", "p": "Kleptomania is an impulse control disorder in which a person fails to resist the urge to steal items that are not needed or of significant monetary value."}, {"h": "How does it manifest?", "p": "A cycle occurs: tension builds before the theft, relief or pleasure is felt during and immediately after the act, followed by guilt. This resembles the craving-action-relief pattern of addiction."}, {"h": "Difference from ordinary theft", "p": "Kleptomania differs from planned theft for gain. Stolen items may be unneeded or discarded, and the core feature is the impulsive act itself."}, {"h": "What to consider", "p": "Kleptomania is a rare but real disorder, often hidden due to shame. It should be understood as an impulse control problem rather than a moral failing, and professional help is needed."}]'::jsonb, advanced_en='[{"h": "Similarity to behavioral addictions", "p": "The tension-action-relief cycle in kleptomania shares mechanisms with behavioral addictions and impulse control disorders, leading to approaches that frame it within addiction models for understanding and treatment."}, {"h": "Comorbid conditions", "p": "Kleptomania frequently co-occurs with depression, anxiety, and other impulse control problems. It often presents alongside other mental health issues rather than in isolation."}, {"h": "Treatment", "p": "Cognitive behavioral therapy and some medications are used, addressing impulse coping and underlying emotional issues. Reducing shame and enabling help-seeking are prerequisites for treatment."}]'::jsonb, updated_at=now() WHERE id='kleptomania';
UPDATE encyclopedia_terms SET definition_en='A plant native to Southeast Asia that produces stimulant effects at low doses and opioid-like effects at high doses. It is sometimes used for pain relief or as a self-treatment for opioid withdrawal, but its dependence potential and safety are controversial. With regulatory gaps, its legal status varies widely by country. The difficulty in standardizing its components makes risk assessment challenging.', example_en='Example: A person who uses kratom to self-treat opioid withdrawal may end up developing dependence on kratom itself.', body_en='[{"h": "What is it", "p": "Kratom is a plant native to Southeast Asia that produces stimulant effects at low doses and opioid-like effects at high doses. It is sometimes used for pain relief or as a self-treatment for opioid withdrawal."}, {"h": "Why is it controversial", "p": "Despite being perceived as a ''natural substance,'' its dependence potential and safety are controversial. Its composition and potency vary across products, making risk prediction difficult. With regulatory gaps, its legal status varies widely by country and region."}, {"h": "The dilemma of self-treatment", "p": "There are cases where people use kratom to stop opioids but end up becoming dependent on kratom itself. It represents both an accessible alternative and an unverified risk."}, {"h": "What to consider", "p": "Kratom is a substance with uncertain potential benefits and risks. With a lack of standardization, quality control, and research, a balanced approach between excessive expectations and indiscriminate regulation is needed."}]'::jsonb, advanced_en='[{"h": "Pharmacological duality", "p": "Kratom''s main alkaloids (e.g., mitragynine) produce stimulant and sedative effects depending on dose and also act on opioid receptors. This complex pharmacology makes it difficult to classify simply as an ''opioid or not.''"}, {"h": "Regulatory dilemma", "p": "Strict prohibition may remove a self-treatment option and drive it into illegal markets, while neglect leaves quality and safety unmanaged. The difficulty in standardizing components makes regulatory design challenging."}, {"h": "Lack of evidence", "p": "Controlled studies on kratom''s efficacy and risks are scarce, leading to reliance on individual case reports. This evidence gap fuels both exaggerated expectations and exaggerated risks."}]'::jsonb, updated_at=now() WHERE id='kratom';
UPDATE encyclopedia_terms SET definition_en='Learned helplessness is a phenomenon in which repeated exposure to uncontrollable negative experiences leads to learning that ''nothing I do matters,'' resulting in a failure to attempt escape even when it becomes possible. Proposed by Seligman, this concept explains how repeated relapses and failures in addiction can lead to giving up on recovery attempts altogether. Experiences that restore a sense of control become turning points in recovery.', example_en='Example: A person who has tried to quit multiple times but failed may stop seeking help, thinking ''I can''t do it anyway.''', body_en='[{"h": "What is it?", "p": "Learned helplessness is a state in which repeated experience of uncontrollable situations leads to the belief that ''nothing I do matters,'' resulting in giving up even trying. It originates from Seligman''s experiments."}, {"h": "How is it linked to addiction?", "p": "Repeated recovery failures or experiences of loss of control can lead to learning helplessness, such as ''I cannot recover.'' This helplessness can cause individuals to stop attempting recovery altogether."}, {"h": "Relationship with relapse", "p": "After a relapse, learned helplessness—''It didn''t work after all''—can lead to giving up on recovery. Stigmatizing relapse as a failure reinforces this helplessness."}, {"h": "How to address it?", "p": "Building small experiences of control and success to restore the belief that ''I can change'' (self-efficacy) is key to overcoming helplessness. Non-judgmental support facilitates this process."}]'::jsonb, advanced_en='[{"h": "Attributional style", "p": "Learned helplessness is linked to a pessimistic attributional style that attributes failure to internal, stable, and global causes. Changing this attributional style is a cognitive target for addressing helplessness and depression."}, {"h": "Relationship with depression", "p": "Learned helplessness theory has been extended to understanding depression and provides a framework for explaining the comorbidity of addiction and depression. Helplessness and anhedonia overlap, making recovery difficult."}, {"h": "Relearning hope", "p": "Just as helplessness is learned, a sense of control and hope can also be relearned. The presence of ''those who have recovered first'' in recovery communities serves as vicarious experience that counters helplessness."}]'::jsonb, updated_at=now() WHERE id='learned-helplessness';
UPDATE encyclopedia_terms SET definition_en='Loot boxes are randomized in-game purchases whose uncertainty and reward structure closely resemble gambling. By blurring the line between gaming and gambling they raise particular concern about youth exposure, and some countries regulate or classify them as gambling. They embody the variable-ratio reinforcement at the heart of gambling.', example_en='A teen repeatedly buying randomized items to get a wanted character and spending far more than intended.', body_en='[{"h": "What it is", "p": "Loot boxes are products purchased within games to obtain random rewards. In that one pays money without knowing what will come out, the uncertainty of outcome and the reward structure closely resemble gambling."}, {"h": "Why it resembles gambling", "p": "Loot boxes carry the very ''variable reward'' structure of ''not knowing when the desired item will appear.'' This is the same principle that makes gambling addictive. One repeatedly pays until the desired item appears, and the psychology of ''just a little more'' inflates spending. It is the point where the boundary between gaming and gambling blurs."}, {"h": "Why it is a problem", "p": "That adolescents can easily access them is a major concern. Without recognizing it as gambling, they may learn gambling-like behavior through in-game purchases, and cases of spending larger amounts than expected occur. Packaged as a fun element, it is hard to recognize as a problem."}, {"h": "Response and regulation", "p": "Some countries have regulated loot boxes or effectively classified them as gambling. User-protection measures such as odds-disclosure obligations, age restrictions, and spending limits are discussed. For guardians, restricting payments and helping children understand the gambling-like nature of loot boxes is necessary."}]'::jsonb, advanced_en='[{"h": "The frontier of gaming-gambling convergence", "p": "Loot boxes are the leading case blurring the boundary between gaming and gambling disorders. Studies report a correlation between loot-box spending and problem gambling, and the issue is whether they serve as a ''gateway'' that teaches gambling-like cognition and behavior to adolescents early."}, {"h": "The regulatory dilemma", "p": "Whether to define loot boxes as gambling differs by country. Judgment shifts depending on how the legal definition of gambling—''can it be exchanged for real currency,'' ''is the outcome purely chance''—is applied. That it is a core revenue model of the industry complicates regulation."}, {"h": "Design ethics", "p": "Loot boxes mobilize psychological devices such as engineered near-misses, dazzling acquisition effects, and limited-time sales. Given that such design targets especially the impulses of immature users, it is treated as a matter of design ethics and user protection beyond individual responsibility."}]'::jsonb, updated_at=now() WHERE id='loot-boxes';
UPDATE encyclopedia_terms SET definition_en='A classical hallucinogen that produces strong perceptual and consciousness alterations in very small doses. Physical dependence is low, but there is a risk of unpredictable psychological reactions (''bad trips'') and, rarely, persistent perceptual disorder (HPPD). The experience is highly influenced by the user''s mental state and environment.', example_en='For example, even at the same dose, taking it while anxious can lead to a frightening experience.', body_en='[{"h": "What is it", "p": "LSD is a classical hallucinogen that produces strong perceptual and consciousness alterations in very small doses. Physical dependence is relatively low."}, {"h": "What are the risks", "p": "Risks include unpredictable psychological reactions (''bad trips''), rarely persistent perceptual disorder (HPPD), and accidents due to impaired judgment. Underlying mental illness increases the risk."}, {"h": "Set and setting", "p": "Even at the same dose, the experience varies greatly depending on the user''s mental state and environment. Use in an anxious state or environment can lead to a frightening experience."}, {"h": "Therapeutic research", "p": "Classical hallucinogens including LSD are being studied in controlled clinical settings for potential treatment of depression, anxiety, and addiction. However, this involves use in a controlled setting with professional guidance."}]'::jsonb, advanced_en='[{"h": "Microgram activity and serotonin", "p": "LSD acts on serotonin receptors at microgram doses to produce strong effects. This high potency underlies the unpredictable psychological reactions."}, {"h": "HPPD", "p": "Some users report persistent perceptual abnormalities (HPPD), but the frequency and mechanism are uncertain. This is discussed cautiously alongside the fact that most perceptual changes are temporary."}, {"h": "Therapeutic history and re-evaluation", "p": "LSD was used in psychiatric research in the mid-20th century, then halted due to regulation, and is now being re-evaluated amid the recent renaissance in psychedelic research. Its regulatory status and evidence base continue to evolve."}]'::jsonb, updated_at=now() WHERE id='lsd';
UPDATE encyclopedia_terms SET definition_en='A substance with both stimulant and hallucinogenic properties, inducing feelings of intimacy, energy, and sensory enhancement, commonly misused in club settings. Risks include hyperthermia, dehydration, and serotonin-related issues, with purity uncertainty amplifying danger. It is also being studied in controlled clinical trials as a treatment for PTSD.', example_en='Example: The risks when used recreationally at parties are entirely different from the context of being studied as a therapeutic aid in clinical trials.', body_en='[{"h": "What is it", "p": "MDMA (Ecstasy) is a substance with both stimulant and hallucinogenic properties, inducing feelings of intimacy, energy, and sensory enhancement, commonly misused in club settings."}, {"h": "What are the risks", "p": "Risks include hyperthermia, dehydration, hyponatremia, and serotonin-related issues, with purity uncertainty in the illegal market amplifying danger. Low mood for several days after use is common."}, {"h": "Therapeutic research", "p": "MDMA is also being studied in controlled clinical trials as an adjunctive treatment for PTSD. This involves a controlled setting with a therapist, distinct from recreational use."}, {"h": "What to distinguish", "p": "Recreational use at parties and therapeutic aid in clinical trials differ entirely in context, dosage, and environment. Blurring this distinction can lead to underestimating the risks of self-use."}]'::jsonb, advanced_en='[{"h": "Serotonergic action", "p": "MDMA causes a massive release of serotonin, leading to feelings of intimacy and euphoria, with subsequent serotonin depletion contributing to low mood after use. The neural impact of repeated use is debated."}, {"h": "Ups and downs of therapeutic research", "p": "MDMA-assisted PTSD therapy has shown promising results, but has faced methodological and safety concerns during regulatory approval, with ongoing evolution in evidence quality and approval decisions."}, {"h": "Purity and harm reduction", "p": "Illegal MDMA is often adulterated with other substances, making drug checking a harm reduction tool. Purity uncertainty is a major risk of recreational use."}]'::jsonb, updated_at=now() WHERE id='mdma-ecstasy';
UPDATE encyclopedia_terms SET definition_en='Medication-Assisted Treatment (MAT) is an evidence-based approach that combines medication with psychosocial support to manage addiction. Particularly for opioid use disorder, medications such as methadone, buprenorphine, and naltrexone have proven effective in reducing craving and the risk of overdose. Misconceptions and stigma, such as the idea of ''replacing one drug with another,'' often hinder access.', example_en='Example: An individual with opioid dependence stabilizes craving and withdrawal using buprenorphine, allowing them to focus on daily recovery.', body_en='[{"h": "What Is It", "p": "Medication-Assisted Treatment (MAT) is an evidence-based approach that combines medication with psychosocial support to manage addiction. Particularly for opioid use disorder, medications such as methadone, buprenorphine, and naltrexone have proven effective in reducing craving and the risk of overdose."}, {"h": "How It Works", "p": "When medication stabilizes craving and withdrawal, individuals can focus on daily recovery—relationships, work, and psychotherapy—instead of being preoccupied with survival and controlling use. Medication does not replace recovery; it creates a stable foundation that makes recovery possible."}, {"h": "Stigma as a Barrier", "p": "Misconceptions and stigma, such as the idea of ''replacing one drug with another,'' are major barriers to accessing MAT. However, evidence shows that MAT is one of the most effective approaches for reducing mortality, relapse, and infection in opioid use disorder. Reducing this stigma is a key challenge for improving treatment access."}, {"h": "Integration Is Key", "p": "As the ''A'' (assisted) in MAT emphasizes, medication is most effective when combined with psychosocial support. While medication alone can reduce overdose, recovery of life quality requires counseling, peer support, and social support."}]'::jsonb, advanced_en='[{"h": "Evidence and Evolution of Terminology", "p": "MAT is among the most powerful evidence-based interventions for opioid use disorder, proven to significantly reduce mortality. Recently, the term ''assisted'' has been criticized for implying medication is secondary, leading to a preference for the term MOUD (Medications for Opioid Use Disorder)."}, {"h": "Access and Policy", "p": "Despite proven effectiveness, access to MAT remains limited due to regulations, stigma, and infrastructure gaps. Policies such as relaxing prescribing restrictions, providing MAT in correctional facilities, and expanding telehealth are discussed to improve access. From a harm reduction perspective, expanding MAT is a key pillar of responding to the overdose crisis."}, {"h": "Tension with Abstinence Orientation", "p": "MAT sometimes creates tension with traditional views that define success only as abstinence. The perspective that maintenance therapy is ''not real recovery'' conflicts with the harm reduction view that saving lives and restoring function are priorities. This tension is part of a larger debate over the definition of recovery."}]'::jsonb, updated_at=now() WHERE id='medication-assisted-treatment';
UPDATE encyclopedia_terms SET definition_en='A general term for conditions characterized by clinically significant disturbances in thinking, emotion, or behavior that cause functional impairment or distress. DSM-5-TR (American Psychiatric Association) and ICD-11 (WHO) are the international standard classification systems, and addiction is positioned as a category within these systems. Reducing stigma toward mental disorders is closely linked to reducing stigma toward addiction.', example_en='Example: Different disorders such as depression, anxiety disorders, and schizophrenia are classified and described within a single standard diagnostic system.', body_en='[{"h": "What It Is", "p": "Mental disorders are clinically significant disturbances in thinking, emotion, or behavior, and are closely intertwined with addiction. Addiction itself is classified as a mental disorder."}, {"h": "Relationship with Addiction", "p": "Different disorders such as depression, anxiety, and schizophrenia are classified alongside addiction within a single standard diagnostic system, and they co-occur and influence each other. Addiction and mental disorders often appear together."}, {"h": "Common Stigma", "p": "Both addiction and other mental disorders are prone to stigma. They share common difficulties, such as being misunderstood as a matter of willpower and facing barriers to seeking help."}, {"h": "What to Consider", "p": "Understanding addiction as a mental disorder helps reduce stigma and justifies treatment. At the same time, an integrated approach considering co-occurring mental disorders is necessary."}]'::jsonb, advanced_en='[{"h": "Addiction within Classification Systems", "p": "Standard diagnostic systems such as DSM and ICD classify addiction alongside other mental disorders. This provides a basis for defining addiction as a disease requiring treatment rather than a moral issue."}, {"h": "Shared Vulnerability", "p": "Addiction and various mental disorders share substantial genetic, neurological, and environmental vulnerabilities. This common foundation, along with high comorbidity rates, supports the need for an integrated understanding."}, {"h": "Implications and Limitations of the Disease Model", "p": "Viewing addiction as a mental disorder contributes to stigma reduction and treatment access, but it also risks underestimating social factors and recovery agency. A balance between medical and social perspectives is required."}]'::jsonb, updated_at=now() WHERE id='mental-disorders';
UPDATE encyclopedia_terms SET definition_en='The mesolimbic dopamine pathway is a core reward circuit in the brain, extending from the ventral tegmental area (VTA) to the nucleus accumbens. It is involved in motivation, salience, and reinforcement learning rather than pleasure. Almost all addictive substances and compulsive behaviors directly or indirectly amplify dopamine signals in this pathway, leading to strong ''wanting'' learning for related cues. This pathway is the scientific basis of the popular term ''reward circuit,'' and the key to understanding addiction lies in the separation of liking and wanting.', example_en='Example: In gambling, dopamine responds more strongly during the uncertain anticipation of ''maybe winning'' than when actually winning money, leading to repeated betting.', body_en='[{"h": "What is it", "p": "The mesolimbic dopamine pathway is a core reward circuit in the brain, extending from the ventral tegmental area (VTA) to the nucleus accumbens. It is involved in motivation, salience, and reinforcement learning rather than pleasure."}, {"h": "Why is it central to addiction", "p": "Almost all addictive substances and compulsive behaviors directly or indirectly amplify dopamine signals in this pathway. Signals much stronger than natural rewards ''hijack'' this circuit, reinforcing addictive behaviors."}, {"h": "What does it teach", "p": "This pathway assigns ''wanting'' to cues associated with rewards, teaching those cues to elicit strong motivation. This is the basis of cue-induced craving and relapse."}, {"h": "Motivation, not pleasure", "p": "Contrary to common misconception, dopamine is not ''pleasure itself'' but a motivational signal that makes one ''want and pursue'' something. This distinction explains why addiction involves ''wanting without liking.''"}]'::jsonb, advanced_en='[{"h": "Reward prediction error", "p": "Dopamine neurons signal a ''reward prediction error'' by responding to better-than-expected rewards. Addictive substances artificially amplify this signal, distorting learning."}, {"h": "Salience attribution", "p": "This pathway attributes ''salience'' to stimuli. In addiction, excessive salience is attributed to substances and cues, making other natural rewards relatively meaningless."}, {"h": "Circuit expansion", "p": "Addiction involves not only this reward circuit but also expansion to the prefrontal cortex (control), amygdala (emotion), and habit circuits. The dopamine pathway is the starting point and central node."}]'::jsonb, updated_at=now() WHERE id='mesolimbic-dopamine';
UPDATE encyclopedia_terms SET definition_en='A long-acting opioid used for decades as replacement therapy to stabilize withdrawal and craving in the treatment of opioid use disorder. It is provided in controlled programs and has the effect of reducing overdose and crime.', example_en='Example: A heroin-dependent individual restores daily functioning through a managed methadone program.', body_en='[{"h": "What is it", "p": "Methadone is a long-acting opioid that has long been used as replacement therapy to stabilize withdrawal and craving in the treatment of opioid use disorder. It is provided in controlled programs and has the effect of reducing overdose and crime."}, {"h": "How does it work", "p": "Methadone acts on opioid receptors to suppress withdrawal and craving, but because it works slowly and lasts long, it provides stability without a ''high'' effect. This reduces the behavior of seeking illegal opioids such as heroin and the associated risks (overdose, infection, crime), allowing the person to restore daily functioning."}, {"h": "How is it provided", "p": "Due to the risk of misuse, methadone is typically administered and managed in certified programs. The structure of daily visits for dosing can be a barrier to access, but it also provides an opportunity for regular management and connection."}, {"h": "Significance", "p": "Methadone maintenance therapy has been a cornerstone of opioid use disorder management for decades. Its public health benefits in reducing overdose deaths and HIV transmission have been proven, and it has become a representative tool of the harm reduction approach."}]'::jsonb, advanced_en='[{"h": "History and evidence", "p": "Methadone maintenance therapy has been used for opioid dependence management since the 1960s, making it the longest-validated pharmacotherapy. There is strong evidence for reductions in mortality, crime, and infection, but program accessibility and the burden of daily visits are noted as limitations."}, {"h": "Stigma and regulation", "p": "Methadone has long been tied to the stigma of ''replacing one addiction with another'' and strict regulation. This regulation has a dual nature: it ensures safety but also makes access difficult. Balancing regulatory relaxation and safety is a policy issue."}, {"h": "Comparison with buprenorphine", "p": "Methadone is potent but carries risks of overdose and interactions, requiring a controlled environment. Buprenorphine, a partial agonist, is relatively safer and can be prescribed in outpatient settings. The two drugs are not substitutes but complementary options chosen based on the patient''s situation."}]'::jsonb, updated_at=now() WHERE id='methadone-med';
UPDATE encyclopedia_terms SET definition_en='A long-acting, potent synthetic stimulant that produces strong arousal and euphoria along with significant neurotoxicity. Repeated use leads to psychosis, cognitive impairment, and severe physical deterioration, and dependence is extremely difficult to overcome.', example_en='Example: Because the stimulant effect lasts so long, individuals may go days without sleep in a binge pattern, eventually developing psychosis.', body_en='[{"h": "What is it", "p": "Methamphetamine is a long-acting, potent synthetic stimulant that produces strong arousal and euphoria along with significant neurotoxicity. It is considered one of the most difficult substances to quit."}, {"h": "How does it progress", "p": "Because the effects last so long, a ''run'' pattern of use may occur, where individuals continue using for days without sleep. Repeated use leads to psychosis, such as paranoia and hallucinations, and severe physical deterioration."}, {"h": "Risks", "p": "Risks include cardiovascular problems, acute and chronic psychosis, cognitive impairment, and widespread physical damage to teeth and skin. Some neurotoxic damage is long-lasting."}, {"h": "Treatment", "p": "There are no approved medications for methamphetamine use disorder, so behavioral treatments such as contingency management and cognitive-behavioral therapy are central. Management of psychosis and cognitive issues, along with long-term support, is also needed."}]'::jsonb, advanced_en='[{"h": "Strong dopamine release", "p": "Methamphetamine causes massive dopamine release and blocks reuptake, producing longer and stronger effects than cocaine. This powerful action underlies its neurotoxicity and strong addictive potential."}, {"h": "Resurgence of the stimulant crisis", "p": "Overshadowed by the opioid crisis, methamphetamine-related overdose and psychosis are increasing, and combined use with opioids is also rising. The lack of effective medications makes response difficult."}, {"h": "Psychosis and recovery", "p": "Methamphetamine-induced psychosis may persist or recur after cessation. Managing cognitive and psychiatric symptoms during recovery is important, and anhedonia and depression make early recovery particularly challenging."}]'::jsonb, updated_at=now() WHERE id='methamphetamine';
UPDATE encyclopedia_terms SET definition_en='A treatment model for addiction that combines 12-step philosophy with professional clinical care, characterized by a multidisciplinary team, peer support, and an abstinence-oriented approach. It has become a standard in modern rehabilitation treatment.', example_en='Example: The framework of a rehabilitation program that provides both professional treatment and a 12-step approach.', body_en='[{"h": "What Is It", "p": "The Minnesota Model is a treatment model for addiction that combines 12-step philosophy with professional clinical care, characterized by a multidisciplinary team, peer support, and an abstinence-oriented approach. It was developed in the mid-20th century in the United States and has become a standard in modern rehabilitation treatment."}, {"h": "How Is It Structured", "p": "A multidisciplinary team of doctors, counselors, social workers, etc., collaborates; recovered individuals participate as counseling staff; and 12-step principles are integrated into the treatment program. During the intensive rehabilitation period, education, group counseling, individual counseling, and self-help meetings are combined to build a foundation for recovery."}, {"h": "Why Was It Influential", "p": "The key was combining two previously separate streams: professional clinical care and peer support. Based on the view of addiction as a disease, it provided a framework linking professional treatment and the 12-step community, becoming a prototype for many rehabilitation programs."}, {"h": "Limitations and Evolution", "p": "As an intensive, abstinence-oriented rehabilitation model, it sometimes creates tension with harm reduction approaches and diverse recovery pathways. Recently, perspectives from continuing care and recovery-oriented systems of care (ROSC) have been added, expanding beyond short-term intensive treatment toward long-term recovery support."}]'::jsonb, advanced_en='[{"h": "Integration of Clinical Care and Self-Help", "p": "The historical contribution of the Minnesota Model lies in its institutional integration of professional clinical care and 12-step self-help. This integration established a dual perspective in treatment settings that defines addiction as a disease while viewing recovery as a communal process."}, {"h": "Evidence and Criticism", "p": "Although the Minnesota Model has been widely disseminated, it has faced criticism regarding the cost-effectiveness of intensive inpatient rehabilitation, its exclusive focus on abstinence, and the failure of standardized programs to adequately reflect individual differences. Evolution is needed toward evidence-based individualization and enhanced continuing care."}, {"h": "Lineage with Recovery Communities", "p": "The Minnesota Model, along with therapeutic communities and recovery housing, forms a lineage of ''recovery within community.'' It highlights the importance of communal support in maintaining recovery after professional treatment, sharing concerns with expanded models such as faith-based and ecologically based recovery villages."}]'::jsonb, updated_at=now() WHERE id='minnesota-model';
UPDATE encyclopedia_terms SET definition_en='A representative natural opioid extracted from opium, essential in medicine due to its potent analgesic effects. It is useful for pain management but carries risks of tolerance, dependence, and respiratory depression.', example_en='Example: A drug essential for terminal pain management while simultaneously requiring dependence management—a dual nature.', body_en='[{"h": "What Is It", "p": "Morphine is a representative natural opioid extracted from opium, essential in medicine due to its potent analgesic effects."}, {"h": "Medical Necessity", "p": "Morphine is essential for managing severe pain, such as terminal pain and postoperative pain. It is a basic analgesic listed on the WHO Model List of Essential Medicines."}, {"h": "Risks", "p": "Along with its analgesic effects, it carries risks of tolerance, dependence, and respiratory depression. Balancing the benefits of pain treatment with the risk of dependence is a clinical challenge."}, {"h": "What to Consider", "p": "Morphine represents the dual nature of opioids as both an essential therapeutic agent and a substance with dependence risk. Both access to pain management and prevention of misuse must be considered."}]'::jsonb, advanced_en='[{"h": "Prototype of Opioids", "p": "Morphine is the prototype substance for later opioids such as heroin and semi-synthetic opioids. The common characteristics of opioids—analgesia, euphoria, and respiratory depression—are typically observed in morphine."}, {"h": "Disparities in Access to Pain Treatment", "p": "Globally, many regions lack access to opioid analgesics like morphine, leaving patients in need of palliative care to suffer from untreated pain. Balancing concerns about misuse with access to pain treatment is an international health challenge."}, {"h": "Tension Between Regulation and Medical Use", "p": "Reactions to the opioid crisis may lead to the restriction of legitimate pain treatment. Morphine is at the center of this tension between regulation and medical use."}]'::jsonb, updated_at=now() WHERE id='morphine';
UPDATE encyclopedia_terms SET definition_en='Motivational interviewing is a collaborative counseling approach that respects ambivalence about change and helps individuals find their own motivation to change. Instead of persuasion or lecturing, it uses empathetic listening and open-ended questions to reduce resistance and elicit change talk. It is particularly effective for people in the precontemplation and contemplation stages of the transtheoretical model.', example_en='Example: Instead of pressuring someone by asking ''Why don''t you quit?'', the counselor helps the person articulate what is at stake in their life, thereby drawing out their own motivation to change.', body_en='[{"h": "What is it", "p": "Motivational interviewing is a collaborative counseling approach that respects ambivalence about change and helps individuals find their own motivation to change. Instead of persuasion or lecturing, it uses empathetic listening and open-ended questions to reduce resistance and elicit change talk."}, {"h": "Why not persuasion", "p": "Pressure to ''quit'' often increases resistance. People change when they find their own reasons, not because someone tells them to. Based on this principle, motivational interviewing helps the person articulate what is at stake in their own life, drawing out internal motivation for change."}, {"h": "How it is done", "p": "Core techniques include empathetic listening, open-ended questions, affirmations, reflections, and summarizing, as well as recognizing and reinforcing the client''s ''change talk.'' The counselor is not an expert who provides answers but a companion who helps the client find their own answers."}, {"h": "Where it is used", "p": "It is especially effective in the early stages when the person does not yet acknowledge the problem or is hesitant to change. Combined with the transtheoretical model, it tailors interventions to each stage and is widely used not only for addiction but also for various health behavior changes."}]'::jsonb, advanced_en='[{"h": "Theoretical background", "p": "Motivational interviewing was developed by Miller and Rollnick, rooted in person-centered counseling and self-determination theory. It is based on the premise that motivation for change is sustained when it comes from personal values and autonomy rather than external pressure. A key shift is reinterpreting ''resistance'' not as a client problem but as a signal in the counseling relationship."}, {"h": "Integration with stages of change", "p": "Motivational interviewing is often combined with the transtheoretical model. In precontemplation and contemplation stages, it addresses ambivalence; in preparation and action stages, it supports planning. The insight that premature demands for action, ignoring the stage, can backfire is foundational."}, {"h": "Evidence and limitations", "p": "Motivational interviewing has proven effective in many areas, but it is not a panacea. Its role is often emphasized as a facilitator to increase entry and engagement in other treatments rather than ensuring long-term change alone. Significant variability in effectiveness depending on counselor skill has also been noted."}]'::jsonb, updated_at=now() WHERE id='motivational-interviewing';
UPDATE encyclopedia_terms SET definition_en='An emergency antidote that rapidly reverses respiratory depression caused by opioid overdose, serving as a key tool in life-saving harm reduction. Nasal sprays that can be used by non-professionals are increasingly being distributed.', example_en='Example: An emergency situation where it is administered immediately to a person whose breathing has stopped due to an overdose, saving their life.', body_en='[{"h": "What is it", "p": "Naloxone is an emergency antidote that rapidly reverses respiratory depression caused by opioid overdose, serving as a key tool in life-saving harm reduction. Nasal sprays that can be used by non-professionals are increasingly being distributed."}, {"h": "How does it work", "p": "Naloxone strongly but briefly blocks opioid receptors, restoring breathing that has stopped due to overdose. When administered immediately to a person who has lost consciousness and respiration from an overdose, it takes effect within minutes, saving lives before arrival at the emergency room."}, {"h": "Why is it important", "p": "Overdose deaths mostly result from respiratory depression, which can be reversed by naloxone. With the spread of potent synthetic opioids like fentanyl, enabling users, families, and bystanders to use naloxone immediately has become the most direct way to prevent overdose deaths."}, {"h": "How is it distributed", "p": "It is widely distributed to pharmacies, communities, and emergency responders, accompanied by training on its use. Because its effect is short-lived and danger may return once it wears off, emergency medical care must follow administration."}]'::jsonb, advanced_en='[{"h": "Expansion as a public health tool", "p": "Naloxone distribution is a representative success story of harm reduction, with many countries making it available without a prescription and expanding community distribution. It embodies the principle of ''even if it doesn''t stop use, it prevents death.''"}, {"h": "Challenges in the fentanyl era", "p": "Overdoses involving ultra-potent opioids like fentanyl may require multiple doses of naloxone, and cases where a single dose is insufficient are increasing. This has raised the need for higher-dose formulations and rapid re-administration, with distribution scale and accessibility continuing to expand."}, {"h": "Stigma debate", "p": "Some critics argue that naloxone distribution encourages risky use, but evidence does not support this. The harm reduction principle that saving lives is a prerequisite for recovery is presented as the answer to moral concerns."}]'::jsonb, updated_at=now() WHERE id='naloxone';
UPDATE encyclopedia_terms SET definition_en='A medication that blocks the rewarding effects of opioids and alcohol, making it difficult to feel intoxicated and thereby reducing relapse. Long-acting injectable formulations improve adherence.', example_en='Example: Helps reduce the motivation to drink by eliminating the pleasure previously associated with alcohol consumption.', body_en='[{"h": "What is it?", "p": "Naltrexone is a medication that blocks the rewarding effects of opioids and alcohol, making it difficult to feel intoxicated and thereby reducing relapse. Long-acting injectable formulations improve adherence."}, {"h": "How does it work?", "p": "Naltrexone blocks opioid receptors, preventing the effects of opioids. For alcohol, it reduces the rewarding sensation of drinking, helping to weaken the motivation to drink by eliminating the pleasure previously associated with alcohol. This approach blocks the reward that fuels craving."}, {"h": "What are the benefits?", "p": "Unlike methadone or buprenorphine, naltrexone itself has no dependence potential. A once-monthly long-acting injection reduces the burden of daily dosing and improves adherence. It is a suitable option for individuals aiming for abstinence."}, {"h": "Precautions", "p": "As an opioid blocker, naltrexone should be started only after opioids have been fully cleared from the body to avoid acute withdrawal. Additionally, there is a risk that individuals may attempt to overcome the blockade by using large amounts of opioids, leading to overdose; therefore, patient education is essential."}]'::jsonb, advanced_en='[{"h": "Differences in mechanism of action", "p": "Unlike agonists (methadone) or partial agonists (buprenorphine), naltrexone is a pure antagonist that ''blocks'' rather than ''replaces'' the reward. This difference aligns with a treatment philosophy distinct from maintenance therapy—abstinence-oriented—and patient selection and motivation significantly influence outcomes."}, {"h": "Evidence in alcohol use disorder", "p": "Naltrexone is one of the few medications with evidence for reducing drinking and relapse in alcohol use disorder. Some approaches (e.g., the Sinclair Method) involve taking it before drinking to induce reward extinction. However, adherence and individual differences determine effectiveness."}, {"h": "Adherence and long-acting formulations", "p": "Oral naltrexone has low adherence due to easy discontinuation. Once-monthly long-acting injections mitigate this issue but have cost and accessibility limitations. As much as the medication''s efficacy, ''how to sustain treatment'' determines real-world outcomes."}]'::jsonb, updated_at=now() WHERE id='naltrexone';
UPDATE encyclopedia_terms SET definition_en='A mutual aid group that applies the 12-step model to recovery from all types of drug addiction, extending the AA model to substances in general. It emphasizes peer support and identity recovery.', example_en='Example: A meeting where people with various drug problems come together to support each other''s recovery.', body_en='[{"h": "What is it", "p": "Narcotics Anonymous (NA) is a mutual aid group that applies the 12-step model to recovery from all types of drug addiction, extending the AA model to substances in general."}, {"h": "How does it work", "p": "Like AA, it supports recovery through regular meetings, sponsors, and the 12 steps. A key feature is that members gather around the common experience of ''addiction'' rather than a specific substance."}, {"h": "What does it emphasize", "p": "It emphasizes peer support and identity recovery, based on the view that the essence of addiction is the same regardless of the drug. The structure involves recovered members helping the next person."}, {"h": "What should be considered", "p": "NA is a highly accessible self-help resource for recovery from substance use disorders. It is understood within the diversity of recovery pathways, alongside alternatives for those who do not fit the 12-step model."}]'::jsonb, advanced_en='[{"h": "Extension of the AA model", "p": "NA extends AA''s 12 steps to substances in general, becoming a representative self-help group for recovery from substance use disorders. It is characterized by an ''addiction'' identity that does not distinguish between substances."}, {"h": "Tension with medication-assisted treatment", "p": "Some 12-step traditions emphasize abstinence, which has created tension with individuals receiving medication-assisted treatment (MAT). In recent years, there has been a movement to embrace those in recovery using MAT."}, {"h": "Value of accessibility", "p": "NA is free and widely available, providing accessible recovery support even in areas with limited treatment resources. This accessibility is a core strength of self-help groups."}]'::jsonb, updated_at=now() WHERE id='narcotics-anonymous';
UPDATE encyclopedia_terms SET definition_en='Neuroadaptation is the process by which the brain alters its structure and function to maintain homeostasis in response to repeated stimulation. It includes adjustments in receptor number and sensitivity, reorganization of neural circuit connections, and forms the biological basis of tolerance and withdrawal. Because these changes persist to a significant degree, vulnerability to cues remains even after prolonged abstinence, providing the rationale for understanding addiction as a chronic disease.', example_en='Example: The brain of a long-term stimulant user becomes desensitized to dopamine signals, making it difficult to feel pleasure from ordinary activities for some time after cessation.', body_en='[{"h": "What is it?", "p": "Neuroadaptation is the process by which the brain adjusts its structure and function in response to repeated substance exposure. It is a core mechanism underlying tolerance, withdrawal, and craving."}, {"h": "How does it work?", "p": "The brain attempts to maintain balance by adjusting receptor numbers or signal strength in response to repeated substance stimulation. This adaptation leads to a need for larger amounts to achieve the same effect (tolerance) and disruption of balance when the substance is absent (withdrawal)."}, {"h": "Why is it important?", "p": "Neuroadaptation demonstrates that addiction is not a ''choice'' but a ''brain change.'' Understanding that difficulty in stopping stems from an altered brain reduces stigma."}, {"h": "Relationship with recovery", "p": "Neuroadaptation is partially reversible. When substance use stops, the brain gradually recovers, but this takes time, and the recovery period is also a time of vulnerability to relapse."}]'::jsonb, advanced_en='[{"h": "Homeostasis and allostasis", "p": "Neuroadaptation is an adjustment to maintain homeostasis, but with repetition, it can develop into allostasis, where the baseline itself shifts. This shift explains the chronic dysphoria and craving in later stages of addiction."}, {"h": "Reversibility and time", "p": "Some neuroadaptations reverse after cessation, but the speed and extent vary by substance, duration, and individual. Early recovery anhedonia and cognitive deficits may be part of this recovery process."}, {"h": "The dual nature of plasticity", "p": "Neuroadaptation is both the brain change that creates addiction and the flip side of plasticity that enables recovery. The same flexibility can guide recovery through new learning, providing a basis for hope."}]'::jsonb, updated_at=now() WHERE id='neuroadaptation';
UPDATE encyclopedia_terms SET definition_en='The property of the brain to change its connections and function in response to experience and learning. Addiction is a result of this plasticity being reorganized around substances or behaviors, and at the same time, recovery is possible through new plastic changes, providing a basis for hope.', example_en='Example: Just as addiction changes the brain, new learning during recovery can reshape the brain again.', body_en='[{"h": "What is it?", "p": "Neuroplasticity is the property of the brain to change its connections and function in response to experience and learning. It is the principle that the brain is not fixed but continuously changes."}, {"h": "Relationship with addiction", "p": "Addiction is a result of this plasticity being reorganized around substances or behaviors. Repeated use strengthens related neural connections, making the behavior increasingly automatic and compulsive."}, {"h": "Basis for recovery", "p": "The same plasticity also enables recovery. When substance use stops and new experiences, relationships, and skills are built, the brain changes again. This is the neuroscientific basis for hope that recovery is possible."}, {"h": "What does it imply?", "p": "Just as addiction changes the brain, new learning during recovery can reshape the brain again. However, change requires time and repeated experience."}]'::jsonb, advanced_en='[{"h": "Addiction as learning", "p": "From the plasticity perspective, addiction is viewed as ''pathological learning.'' Reward learning becomes excessively reinforced and solidified, bridging the pure disease model and the learning model."}, {"h": "Relearning in recovery", "p": "Recovery is understood as a relearning process that weakens existing pathological connections and strengthens new adaptive connections. New habits, relationships, and meanings serve as the material for this relearning."}, {"h": "Critical periods and vulnerability", "p": "Adolescence is a period of high plasticity, making learning rapid but also increasing vulnerability to addiction. This explains why substance exposure during this period is particularly risky and why prevention is crucial."}]'::jsonb, updated_at=now() WHERE id='neuroplasticity';
UPDATE encyclopedia_terms SET definition_en='Nicotine, the primary addictive component of tobacco, is a stimulant that creates strong dependence, and smoking is a leading cause of preventable death. Dependence develops rapidly, and withdrawal (irritability, craving, difficulty concentrating) triggers relapse. Delivery forms such as e-cigarettes and pouches are diversifying.', example_en='Example: A person who, despite knowing the health risks, repeatedly fails to quit smoking due to withdrawal and craving.', body_en='[{"h": "What Is It", "p": "Nicotine, the primary addictive component of tobacco, is a stimulant that creates strong dependence, and smoking is a leading cause of preventable death. Dependence develops rapidly, and withdrawal triggers relapse."}, {"h": "Why Is It Hard to Quit", "p": "Nicotine dependence is very strong, and withdrawal (irritability, craving, difficulty concentrating, anxiety) is pronounced. Smoking is tightly linked to daily habits and situations, so people often fail multiple attempts to quit despite knowing the health risks."}, {"h": "Changing Delivery Forms", "p": "Nicotine delivery forms such as e-cigarettes and nicotine pouches are diversifying. This creates both aspects of smoking cessation aids and nicotine introduction among adolescents."}, {"h": "Treatment", "p": "Nicotine replacement therapy (patches, gum, etc.), medications (varenicline, bupropion), and counseling increase quit rates. Multiple attempts are common, so it is important not to stigmatize failure."}]'::jsonb, advanced_en='[{"h": "Speed of Dependence Formation", "p": "Nicotine reaches the brain within seconds of inhalation, producing powerful reinforcement, and this rapid delivery underlies strong dependence. Adolescent exposure particularly affects the developing brain."}, {"h": "Successes and Challenges of Tobacco Regulation", "p": "Tobacco regulation—such as pricing, advertising restrictions, smoke-free zones, and warning labels—is a landmark public health success. However, the emergence of novel nicotine products creates new challenges that continue to expand the scope of regulation."}, {"h": "Harm Reduction Debate", "p": "The debate over whether nicotine harm reduction through e-cigarettes and similar products helps smoking cessation or creates new dependence is at the forefront of tobacco policy. The key point is that effects may differ between adult smokers and adolescent non-smokers."}]'::jsonb, updated_at=now() WHERE id='nicotine-tobacco';
UPDATE encyclopedia_terms SET definition_en='A leading researcher in the neuroscience of addiction, who has pioneered studies identifying addiction as a brain disease through dopamine, reward circuitry, and prefrontal cortex dysregulation. She has popularized the modern neuroscientific basis of the disease model.', example_en='Example: Using brain imaging research to scientifically support the understanding that ''addiction is a brain disease.''', body_en='[{"h": "Who is she?", "p": "Nora Volkow is a leading researcher in the neuroscience of addiction, who has pioneered studies identifying addiction as a brain disease through dopamine, reward circuitry, and prefrontal cortex dysregulation."}, {"h": "What did she do?", "p": "Through brain imaging research, she revealed how addiction alters the brain''s reward, motivation, and control circuits. She provided and popularized the modern neuroscientific basis of the disease model."}, {"h": "Why is it important?", "p": "Volkow''s research scientifically supports the understanding that ''addiction is a brain disease,'' contributing to reducing stigma and justifying treatment."}, {"h": "What should we consider?", "p": "While Volkow''s brain disease perspective has had a major impact, complementary discussions emphasize the need to also consider social and environmental factors and recovery agency. Her research is one pillar of an integrated understanding."}]'::jsonb, advanced_en='[{"h": "Advocate of the brain disease model", "p": "Volkow is a representative figure who scientifically established and popularized the modern brain disease model. Her brain imaging studies provided the core evidence for this model."}, {"h": "Contribution to stigma reduction", "p": "The message that ''addiction is a brain disease, not a moral failure'' has helped reduce stigma and expand access to treatment. This has important public health implications."}, {"h": "Criticism and balance", "p": "However, some critics argue that the brain disease model underestimates social determinants, recovery potential, and agency. Volkow herself has recently broadened the discussion to emphasize the integration of social and environmental factors."}]'::jsonb, updated_at=now() WHERE id='nora-volkow';
UPDATE encyclopedia_terms SET definition_en='A psychoanalytic perspective that views early relational experiences as internalized to form images of self and others, and sees deficits in this structure as linked to addiction vulnerability. In particular, Kohut''s self psychology explains that deficits in a healthy sense of self and self-soothing capacity are compensated for by substances or behaviors. It understands addiction as a problem of relational and self-structure, using the therapeutic relationship itself as a tool for recovery.', example_en='Example: A person with weak internal resources for self-soothing and self-support tries to fill that void with the temporary sense of fullness provided by a substance.', body_en='[{"h": "What is it", "p": "Object relations and self psychology are psychoanalytic schools that view early relational experiences as internalized to form self-structure and relational patterns. They understand addiction as a problem of this relational and self-structure."}, {"h": "How does it view addiction", "p": "When the ability to soothe and integrate the self is weakly formed due to unstable early relationships, substances are seen as filling that deficit. The substance functions as a substitute for a ''comforting object.''"}, {"h": "What does it suggest", "p": "This perspective suggests that the roots of addiction lie in vulnerabilities in relational and self-structure. It offers the insight that recovery is difficult without addressing the emptiness and self-deficits underlying substance use."}, {"h": "Implications for treatment", "p": "The therapeutic relationship itself can serve as a corrective experience to restore damaged self-structure. Rebuilding the capacity to soothe and integrate the self within a stable relationship is part of recovery."}]'::jsonb, advanced_en='[{"h": "Self psychology perspective", "p": "Kohut''s self psychology views addiction as an attempt to replace deficient selfobject functions (functions that support and soothe the self) with substances. The substance substitutes for what relationships should provide."}, {"h": "Connection to emotion regulation", "p": "The object relations perspective intersects with attachment theory and emotion regulation discussions. Deficits in self-soothing capacity, not formed in early relationships, are identified as a common root of addiction vulnerability."}, {"h": "Recovery as relationship", "p": "From this perspective, recovery is a process of replacing the relationship with substances with stable relationships with people and community, and restoring the damaged self within relationships. This provides a theoretical basis for the therapeutic power of recovery communities."}]'::jsonb, updated_at=now() WHERE id='object-relations';
UPDATE encyclopedia_terms SET definition_en='A disorder in which unwanted repetitive thoughts (obsessions) and repetitive behaviors (compulsions) aimed at alleviating the anxiety caused by those thoughts impair daily functioning. It superficially resembles the compulsive aspect of addiction, but the motivation differs—addiction typically originates from seeking pleasure or reward, whereas OCD focuses on eliminating anxiety. This distinction guides treatment direction.', example_en='Example: A cycle of OCD in which obsessive thoughts about contamination lead to washing hands dozens of times to temporarily relieve anxiety.', body_en='[{"h": "What Is It", "p": "Obsessive-compulsive disorder (OCD) is an anxiety-related disorder characterized by unwanted repetitive thoughts (obsessions) and repetitive behaviors (compulsions) aimed at reducing the anxiety caused by those thoughts."}, {"h": "How Is It Different from Addiction", "p": "Both addiction and OCD involve repetitive behaviors, but the motivation differs. Compulsions in OCD are primarily aimed at reducing anxiety, whereas repetition in addiction is rooted in reward, pleasure, and habit."}, {"h": "Why Are They Discussed Together", "p": "They are discussed together because both involve repetition that the person cannot stop despite wanting to, and because of the common element of compulsivity. The later compulsive use in addiction superficially resembles compulsions in OCD."}, {"h": "What to Look For", "p": "The distinction between OCD and addiction lies in ''what the repetition is for.'' This distinction determines accurate diagnosis and treatment direction."}]'::jsonb, advanced_en='[{"h": "Compulsivity Spectrum", "p": "Some scholars view OCD and addiction together on a ''compulsivity spectrum.'' However, due to differences in neural circuits and motivational structures, they cannot be fully equated."}, {"h": "Difference in Ego-Dystonicity", "p": "Compulsions in OCD are usually unwanted (ego-dystonic), whereas early substance use in addiction is desired (ego-syntonic). This difference is key to distinguishing the two disorders."}, {"h": "Co-occurrence and Treatment", "p": "OCD and addiction can co-occur, requiring an integrated approach. Both disorders utilize elements of exposure and response prevention and cognitive-behavioral therapy, but specific strategies differ."}]'::jsonb, updated_at=now() WHERE id='obsessive-compulsive';
UPDATE encyclopedia_terms SET definition_en='Online and mobile gambling is betting via the internet and apps, marked by 24/7 access, live in-play betting, and the explosive growth of sports betting. With physical barriers gone and instant repeat betting in hand, the slide into problem gambling can be fast, and losses shown only as on-screen numbers dull the sense of loss. Regulators are tightening advertising and access.', example_en='Placing live bets on a match through an app and losing control far faster than at a physical venue.', body_en='[{"h": "What it is", "p": "Online and mobile gambling is gambling via the internet and apps, characterized by 24-hour accessibility, real-time in-play betting, and the rapid growth of sports betting. Being able to bet instantly and repeatedly in one''s hand without going to a physical venue is a decisive difference from traditional gambling."}, {"h": "What makes it more dangerous", "p": "As access barriers vanish, the gap between impulse and action disappears. One can repeat anytime, any amount, 24 hours a day, and because losses appear only as numbers on a screen rather than actual cash, the sense of losing dulls. Real-time betting induces repeated wagering throughout a match. These elements make the shift to risky gambling far faster."}, {"h": "How it progresses", "p": "Even starting as light fun, the instant, repeatable structure rapidly erodes control. Chasing losses occurs more easily than offline, and problems surface late because losses are easy to hide. Possible anytime, anywhere with just a smartphone, it seeps into all of daily life."}, {"h": "Response", "p": "Blocking access (self-exclusion programs, payment and app restrictions) is even more important than offline. The recovery principles of gambling disorder in general—cognitive-behavioral therapy, self-help groups, financial cleanup, supportive relationships—apply equally, and devices that physically cut off 24-hour access are especially effective."}]'::jsonb, advanced_en='[{"h": "Structural risk factors", "p": "The risk of online gambling stems not only from individual disposition but from the medium''s structure. Unlimited accessibility, rapid betting cycles, in-play and micro-betting, and the abstraction of loss (digital balance) combine to accelerate loss of control. This shows that ''which medium one uses'' influences the degree of risk."}, {"h": "Regulation and advertising", "p": "Countries increasingly strengthen online gambling advertising, access hours, betting limits, and self-exclusion systems. The surge in sports-betting advertising and youth exposure is a particular policy issue. The boundary between legal and illegal markets and cross-border services make regulation difficult."}, {"h": "Digital traces and intervention potential", "p": "Paradoxically, online gambling leaves betting data, creating great potential to detect risky patterns early and intervene. ''Responsible gambling'' designs that impose risk-signal monitoring and intervention duties on operators are discussed, but conflicts of interest with revenue structures are noted as limits."}]'::jsonb, updated_at=now() WHERE id='online-gambling';
UPDATE encyclopedia_terms SET definition_en='A learning principle by Skinner stating that the consequences of a behavior (reward or punishment) increase or decrease the likelihood of that behavior being repeated. In addiction, substances or behaviors provide immediate rewards such as pleasure or relief from discomfort, reinforcing the behavior. Particularly, ''variable ratio reinforcement,'' where rewards are given unpredictably, creates a pattern that is most resistant to extinction, explaining why gambling is so difficult to quit.', example_en='Example: A slot machine provides intermittent rewards unpredictably, so even when losing, the person keeps pulling the lever thinking ''next time.''', body_en='[{"h": "What is it", "p": "Operant conditioning is a learning principle where the consequences of a behavior (reward or punishment) increase or decrease the likelihood of that behavior being repeated. It originates from Skinner''s experiments."}, {"h": "How does it work in addiction", "p": "When a substance or behavior provides immediate pleasure or relief from discomfort, that behavior is reinforced. This repeated reinforcement forms the learning basis of addictive behavior."}, {"h": "Immediacy is key", "p": "In operant conditioning, the more immediate and certain the reward, the stronger the behavior is reinforced. This is why the fast and reliable reward of addictive substances produces strong learning."}, {"h": "Application to treatment", "p": "Using this principle in reverse, contingency management treatment has been developed that provides immediate rewards for recovery behaviors. It is known that reinforcing desirable behaviors is more effective than punishment."}]'::jsonb, advanced_en='[{"h": "Reinforcement schedules", "p": "The way rewards are given (schedule) determines the strength and persistence of behavior. Particularly, variable ratio reinforcement, where the timing is unknown, creates the most persistent behavior and is a core principle of gambling addiction."}, {"h": "Positive and negative reinforcement", "p": "Behavior is reinforced not only by obtaining rewards (positive reinforcement) but also by removing discomfort (negative reinforcement). Withdrawal avoidance in later-stage addiction is a typical example of negative reinforcement."}, {"h": "Foundation of behavioral therapy", "p": "Operant conditioning is the theoretical foundation of evidence-based behavioral therapies such as contingency management and relapse prevention. It is central to the view of addiction as learned behavior."}]'::jsonb, updated_at=now() WHERE id='operant-conditioning';
UPDATE encyclopedia_terms SET definition_en='A group of analgesic and sedative substances derived from the opium poppy or synthesized to mimic its effects, acting on opioid receptors in the brain to reduce pain and produce intense euphoria. They carry high risks of dependence and fatal overdose due to respiratory depression, placing them at the center of the global drug crisis. They are classified as natural (morphine), semi-synthetic (heroin, oxycodone), and synthetic (fentanyl, methadone).', example_en='Example: A person prescribed opioid painkillers after surgery develops tolerance and dependence, leading them to seek stronger opioids.', body_en='[{"h": "What Are Opioids?", "p": "Opioids are a group of analgesic and sedative substances derived from the opium poppy or synthesized to mimic its effects, acting on opioid receptors in the brain to reduce pain and produce intense euphoria. They are classified as natural (morphine), semi-synthetic (heroin, oxycodone), and synthetic (fentanyl, methadone)."}, {"h": "Why Are They Dangerous?", "p": "They are highly addictive, and overdose can suppress respiration, leading to death. Tolerance develops rapidly, increasing dosage, and withdrawal avoidance motivates continued use. This combination makes opioids one of the most lethal substance groups."}, {"h": "Between Medicine and Crisis", "p": "Opioids are essential for pain treatment while simultaneously being at the center of the global drug crisis. The balance between the need for pain management and the risks of dependence and overdose is the key tension surrounding opioids."}, {"h": "Treatment", "p": "Opioid use disorder is effectively managed with medication-assisted treatment such as methadone and buprenorphine, while overdose response (naloxone) and harm reduction save lives. Opioids are among the substance groups with the best-established evidence-based treatments."}]'::jsonb, advanced_en='[{"h": "Endogenous Opioid System", "p": "Opioids act on the body''s endogenous opioid system, including endorphins produced naturally. Because this system is involved in pain, reward, and emotional regulation, exogenous opioids produce both powerful analgesia and euphoria simultaneously."}, {"h": "Structure of the Opioid Crisis", "p": "The crisis, starting from overprescription of prescription opioids and progressing to heroin and fentanyl, is a structural problem involving healthcare, industry, regulation, and illicit markets. It is understood as an interaction of multiple factors rather than a single cause."}, {"h": "Tension with Pain Treatment", "p": "In reaction to the opioid crisis, prescribing has become more restrictive, leading to undertreatment of legitimate pain patients. Balancing under- and overprescribing remains an ongoing clinical and policy challenge."}]'::jsonb, updated_at=now() WHERE id='opioids';
UPDATE encyclopedia_terms SET definition_en='A substance obtained from the opium poppy, the source of opiates such as morphine and codeine, and a historical drug used by humans since ancient times for pain relief and intoxication. Modern opium trade and regulation form the roots of today''s drug policies.', example_en='Example: The starting point of the opiate lineage from opium to morphine and heroin.', body_en='[{"h": "What Is It", "p": "Opium is a substance obtained from the opium poppy, the source of opiates such as morphine and codeine. It is a historical drug used by humans since ancient times for pain relief and intoxication."}, {"h": "Historical Weight", "p": "Opium is a substance that has greatly influenced world history, including the modern opium trade and the Opium Wars. The historical roots of today''s drug regulation and control systems lie in international responses to opium."}, {"h": "Starting Point of Opiates", "p": "Opium is the beginning of the lineage where morphine is derived from opium, and heroin is derived from morphine. This substance is the distant origin of today''s opiate crisis."}, {"h": "What to Remember", "p": "Opium shows the intertwined history of substances, society, and politics. It reminds us that drug problems are not merely individual issues but social phenomena entangled with trade, power, and regulation."}]'::jsonb, advanced_en='[{"h": "Origins of International Drug Control", "p": "International conventions surrounding opium in the early 20th century laid the foundation for today''s drug control systems. The history of opium regulation has shaped the structure of modern drug policy."}, {"h": "Production and Geopolitics", "p": "Opium (poppy) production is intertwined with the economy and conflict of specific regions, so supply-side responses go beyond simple enforcement to connect with geopolitical and development issues. This is the background for discussions on alternative crop development."}, {"h": "Historical Lessons", "p": "The Opium Wars are examples where interests surrounding a substance escalated into international conflict. They show the need to view drug problems not merely morally but in the context of history and political economy."}]'::jsonb, updated_at=now() WHERE id='opium';
UPDATE encyclopedia_terms SET definition_en='A case in which the U.S. state of Oregon decriminalized possession of small amounts of drugs through a 2020 ballot measure (Measure 110), then reversed course and recriminalized it in 2024. Often cited as a representative failure or retreat of the first U.S. attempt to adopt a Portugal-style approach that did not achieve expected outcomes.', example_en='After reducing possession of small amounts of drugs to a fine-level offense, it was reclassified as a misdemeanor four years later amid controversy over increased public drug use and overdose.', body_en='[{"h": "What it is", "p": "In 2020, Oregon decriminalized possession of small amounts of drugs such as heroin and cocaine via a ballot measure, and decided to allocate marijuana tax revenue to treatment. It was the first attempt by a U.S. state to shift from a punitive drug policy to a health-centered approach. However, in 2024, the state legislature reversed this, passing a recriminalization law that reclassified small-amount possession as a misdemeanor, which took effect that year."}, {"h": "Why the retreat", "p": "After decriminalization, public drug use and overdose problems became prominent, weakening support for the policy. A key issue identified was that ''while punishment was removed, the infrastructure to connect people to treatment did not function in time.'' Many assessments indicate that decriminalization moved ahead without a health and social system ready to replace punishment."}, {"h": "How it differed from Portugal", "p": "Both places decriminalized small-amount possession, but outcomes diverged. Portugal simultaneously built treatment and reintegration infrastructure and established it over a long period, whereas Oregon had weak linkages and faced a different context of an overdose crisis (fentanyl). This shows that the same policy can yield entirely different results depending on infrastructure and context."}, {"h": "What it left behind", "p": "The Oregon case has added caution to the decriminalization debate. It teaches that ''removing punishment'' and ''connecting to treatment'' are separate, and without the latter, the former alone can fail. Even after recriminalization, the law allows localities to run programs that divert people to treatment instead of criminal penalties, suggesting it is not a complete return to punishment."}]'::jsonb, advanced_en='[{"h": "Failure or incompletion", "p": "Interpretations differ on whether the Oregon experiment should be seen as a ''failure of decriminalization'' or a ''failure of hasty implementation without infrastructure.'' Critics argue that decriminalization itself led to disorder, while advocates point to delays in treatment funding allocation and the disruptive factor of the fentanyl crisis. This interpretive divide has become central to subsequent U.S. policy debates."}, {"h": "The variable of the fentanyl environment", "p": "Oregon''s experiment coincided with a surge in synthetic opioid (fentanyl) overdoses. Even the same policy can amplify risks in an environment where a lethal substance dominates the market. This case illustrates that recovery policies cannot be evaluated separately from changes in the substance environment."}, {"h": "The politics of policy reversal", "p": "The process by which a once-adopted reform policy is quickly overturned due to short-term lack of results and worsening public opinion reveals that perceived disorder and political pressure can shape policy more than evidence. A political environment that cannot wait for long-term effects is identified as a structural factor hindering the sustainability of recovery-oriented reforms."}]'::jsonb, updated_at=now() WHERE id='oregon-measure110';
UPDATE encyclopedia_terms SET definition_en='An acute, life-threatening condition caused by using a substance beyond the body''s capacity to handle it. Respiratory depression from opioid overdose is a prime example. Risks increase with reduced tolerance after abstinence, polysubstance use, and uncertain purity. Emergency interventions like naloxone can save lives.', example_en='Example: A person who has been abstinent for a while, with reduced tolerance, uses the previous dose and experiences an overdose.', body_en='[{"h": "What is it?", "p": "An overdose is an acute, life-threatening condition caused by using a substance beyond the body''s capacity to handle it. Respiratory depression from opioid overdose is a prime example."}, {"h": "What increases the risk?", "p": "Reuse after reduced tolerance, mixing multiple substances, and uncertainty about purity or composition (especially fentanyl adulteration) significantly increase overdose risk. Unexpectedly high potency can be fatal."}, {"h": "How to respond?", "p": "Opioid overdose can be reversed with naloxone; prompt administration and emergency medical connection save lives. Overdose is an immediate emergency."}, {"h": "What is good to know?", "p": "Overdose is not just the user''s problem; rapid response by bystanders can determine life or death. Naloxone distribution and training in its use are key to reducing overdose deaths."}]'::jsonb, advanced_en='[{"h": "Mechanism of respiratory depression", "p": "Most opioid overdose deaths result from suppression of the brain''s respiratory center. Concurrent use of depressants and opioids compounds this suppression, multiplying the risk."}, {"h": "The trap of reduced tolerance", "p": "After a period of abstinence (e.g., detoxification, incarceration), tolerance decreases. Reusing the previous dose can easily lead to a fatal overdose. This period carries the highest overdose risk."}, {"h": "Harm reduction target", "p": "Overdose prevention is a key target of harm reduction. Naloxone distribution, safe consumption facilities, drug checking, and education on ''not using alone'' are evidence-based means to reduce overdose deaths."}]'::jsonb, updated_at=now() WHERE id='overdose';
UPDATE encyclopedia_terms SET definition_en='A potent semi-synthetic opioid analgesic that has been at the center of prescription misuse and the opioid crisis. Effective for pain treatment but carries high risks of misuse and dependence for euphoric purposes.', example_en='Example: A typical trajectory where a prescription for pain treatment leads to misuse and dependence.', body_en='[{"h": "What is it", "p": "Oxycodone is a potent semi-synthetic opioid analgesic that has been at the center of prescription misuse and the opioid crisis. Effective for pain treatment but carries high risks of misuse and dependence."}, {"h": "Symbol of the crisis", "p": "Oxycodone extended-release tablets, amid aggressive marketing and overprescribing, were widely misused and became a symbol of the early stages of the North American opioid crisis."}, {"h": "How does it lead to addiction", "p": "A typical trajectory involves a prescription for pain treatment leading to misuse and dependence, and after regulatory tightening, some users transition to heroin or fentanyl."}, {"h": "What to consider", "p": "Oxycodone has two faces: a legitimate analgesic and a trigger for crisis. One must consider the need for pain treatment, the risk of misuse, and the responsibility of pharmaceutical marketing."}]'::jsonb, advanced_en='[{"h": "Pharmaceutical marketing and responsibility", "p": "The aggressive marketing of oxycodone and downplaying of dependence risks fueled the crisis, raising issues of industrial and regulatory responsibility beyond individual pathology."}, {"h": "Misuse of extended-release formulations", "p": "The problem involved crushing extended-release tablets designed for slow release to absorb the entire dose at once. This led to the development of abuse-deterrent formulations."}, {"h": "Balloon effect", "p": "Strengthened prescription regulations reduced prescription opioid misuse but pushed some users toward more dangerous illegal opioids, a ''balloon effect'' showing the limits of supply-side responses."}]'::jsonb, updated_at=now() WHERE id='oxycodone';
UPDATE encyclopedia_terms SET definition_en='Gambling disorder is persistent, recurrent gambling that seriously impairs personal, family and work life. It was the first non-substance addiction to be formally recognized—moved into the addictive-disorders category in DSM-5 and classified as a disorder due to addictive behavior in ICD-11. Hallmarks include chasing losses, escalating stakes (tolerance), restlessness when stopping (withdrawal), and lies to conceal the behavior.', example_en='Chasing losses with ever-larger bets, piling up debt, and lying to hide it until family and job are gone.', body_en='[{"h": "What it is", "p": "Gambling disorder is the inability to stop gambling despite clearly harmful consequences. The problem is not losing large sums of money but losing control over gambling while other areas of life—work, relationships, health, finances—collapse and one continues anyway. What separates recreational gambling from the disorder is not ''how much was wagered'' but ''whether one can stop.''"}, {"h": "How it progresses", "p": "It often begins as fun or stress relief. An early big win becomes strongly imprinted, and stakes gradually rise to recapture the same excitement (tolerance). When losses start, ''just one more and I can win it back'' leads to chasing losses, which snowballs the damage. Trying to cut back brings restlessness and anxiety, and as lies and debt pile up to raise funds and hide the problem, relationships and trust collapse."}, {"h": "Why it is hard to quit", "p": "Gambling''s reward comes ''when you least expect it.'' This irregular reward structure trains the brain''s reward circuitry most powerfully, so even while losing, the expectation that ''next time might win'' sustains the behavior. Notably, the dopamine response is greater in the uncertain moment of ''might win'' than in actually winning. Online and mobile gambling, available 24 hours with instant repetition and losses shown only as numbers on a screen, accelerates this dramatically."}, {"h": "Is recovery possible", "p": "Yes. Gambling disorder is understood as a chronic, relapsing condition, and relapse is treated not as failure but as part of the recovery process. Cognitive-behavioral therapy, motivational interviewing, self-help communities such as GA, sorting out financial and legal problems, and family recovery work powerfully together. Admitting the problem—moving past denial—is the first gateway, and recovery lasts when it happens within supportive relationships rather than alone."}]'::jsonb, advanced_en='[{"h": "A historic shift in classification", "p": "Until DSM-IV, pathological gambling belonged to impulse-control disorders. In DSM-5 (2013) it moved into the ''substance-related and addictive disorders'' category, becoming the first officially recognized non-substance addiction. This followed accumulated evidence that the behavior shows reward-circuit mechanisms, course, and treatment response similar to substances. ICD-11 likewise classifies it under ''disorders due to addictive behaviors'' alongside gaming disorder. This shift opened the door to later discussions of gaming, internet, and other behavioral addictions."}, {"h": "Theoretical perspectives and debate", "p": "Gambling disorder is explained by a dual-process model shifting from impulsivity-driven (early) to compulsivity-driven (late), by reward prediction error and incentive salience, and cognitively by distorted beliefs such as the illusion of control and the gambler''s fallacy as maintaining factors. Meanwhile, perspectives differ on whether to view it as a ''disease'' or as learned, contextual behavior, and there is a critical view that the gambling industry''s design (variable rewards, engineered near-misses) is an environmental cause as significant as individual pathology."}, {"h": "Lived-experience and recovery view", "p": "From the recovery field''s perspective, the core suffering of gambling disorder lies less in monetary loss than in the collapse of self-control and trust. Chasing losses often operates through a psychology of ''trying to restore a shattered self-image'' rather than the loss itself, so financial cleanup alone does not complete recovery—rebuilding relationships, meaning, and self-efficacy is also needed. The thickness of recovery capital—supportive community, stable routine, trusting relationships—greatly determines whether relapse occurs."}]'::jsonb, updated_at=now() WHERE id='pathological-gambling';
UPDATE encyclopedia_terms SET definition_en='A potent dissociative substance that can cause perceptual distortion along with unpredictable agitation, aggression, and dissociation. At high doses, it can induce severe psychosis and dangerous behavior.', example_en='Example: In a dissociated state, pain and risk perception are blunted, which can lead to unforeseen accidents.', body_en='[{"h": "What is it", "p": "Phencyclidine (PCP) is a potent dissociative substance that can cause perceptual distortion along with unpredictable agitation, aggression, and dissociation."}, {"h": "Why is it dangerous", "p": "At high doses, it can induce severe psychosis and dangerous behavior. In a dissociated state, pain and risk perception are blunted, which can lead to accidents causing harm to oneself or others."}, {"h": "What are its effects", "p": "PCP causes detachment from reality (dissociation), perceptual distortion, and unpredictable emotional and behavioral changes. Responses vary greatly between individuals and situations, making risk prediction difficult."}, {"h": "What to look for", "p": "PCP is characterized by unpredictability, aggression, and risk of psychosis. Acute intoxication can be an emergency requiring safety measures and sedation as priorities."}]'::jsonb, advanced_en='[{"h": "Dissociative mechanism", "p": "Like ketamine, PCP blocks NMDA receptors to produce dissociative effects. However, its action is stronger and longer-lasting, potentially causing severe psychosis and agitation."}, {"h": "Psychosis model", "p": "The symptoms induced by PCP resemble schizophrenia, and it has been used as a model in psychosis research. This suggests a link between dissociative substances and psychotic mechanisms."}, {"h": "Emergency response", "p": "Acute PCP intoxication is challenging to manage due to agitation and aggression. Sedation in a low-stimulation environment and ensuring safety are crucial."}]'::jsonb, updated_at=now() WHERE id='pcp';
UPDATE encyclopedia_terms SET definition_en='Personality disorders such as borderline and antisocial personality disorder commonly co-occur with addiction through difficulties in emotional regulation and impulse control. Problems with relationships and self-structure complicate treatment, requiring an integrated, long-term approach.', example_en='Example: Difficulty managing extreme emotional fluctuations leads to impulsive reliance on substances.', body_en='[{"h": "What Is It", "p": "Personality disorders are a group of disorders characterized by persistent and rigid patterns of thinking, feeling, and behaving that impair functioning. Borderline and antisocial personality disorders commonly co-occur with addiction."}, {"h": "How Are They Connected", "p": "Emotional dysregulation in borderline personality disorder and impulsivity and norm violation in antisocial personality disorder intertwine with addiction. Difficulty managing extreme emotional fluctuations or impulses may lead to reliance on substances."}, {"h": "Why Is Treatment Complex", "p": "Personality disorders involve problems with relationships and self-structure, making treatment particularly complex when co-occurring with addiction. An integrated, long-term approach is required."}, {"h": "What to Consider", "p": "Co-occurring personality disorder and addiction are often stigmatized, but both are treatable conditions. A long-term approach addressing emotional regulation and relationships is key to recovery."}]'::jsonb, advanced_en='[{"h": "Borderline Personality Disorder and DBT", "p": "Dialectical behavior therapy (DBT) has evidence for co-occurring borderline personality disorder and addiction. Skills in emotional regulation and distress tolerance are common to both conditions."}, {"h": "Antisocial Personality and Treatment Resistance", "p": "Antisocial personality disorder commonly co-occurs with addiction, and treatment engagement and retention are challenging. Approaches addressing motivation and relationships, along with realistic expectations, are needed."}, {"h": "Roots in Self and Relationships", "p": "Co-occurring personality disorder and addiction are understood from object relations and attachment perspectives as sharing a common root in vulnerability of self-structure and relational capacity. Long-term recovery within relationships is emphasized."}]'::jsonb, updated_at=now() WHERE id='personality-disorders';
UPDATE encyclopedia_terms SET definition_en='In psychoanalysis, the pleasure principle is the mind''s tendency to seek immediate pleasure and tension reduction, while the reality principle is the mature function that delays and regulates this pursuit in accordance with real-world constraints. Addiction can be understood as a state where the pleasure principle, which seeks immediate gratification, overwhelms the reality principle, which considers long-term consequences. This aligns with the modern psychological concept of impulsivity as a weakened ability to delay gratification.', example_en='Example: Repeatedly choosing to give up an important schedule tomorrow for the sake of immediate pleasure now.', body_en='[{"h": "What is it?", "p": "The pleasure principle is the psychological tendency to seek immediate pleasure and avoid pain, while the reality principle is the ability to delay and regulate gratification according to the demands of reality. These are Freudian concepts."}, {"h": "How is it connected to addiction?", "p": "Addiction can be seen as a state where the pleasure principle overwhelms the reality principle. Immediate gratification (from substances) pushes aside consideration of long-term consequences."}, {"h": "What does it suggest?", "p": "This perspective understands addiction as a ''weakening of the ability to delay gratification.'' It provides insight that an imbalance where present pleasure overpowers future costs is central to addiction."}, {"h": "Relationship with development", "p": "The reality principle is an ability formed during development. Cultivating this ability—learning to delay gratification and control impulses—becomes a key aspect of recovery and prevention."}]'::jsonb, advanced_en='[{"h": "Connection to delay discounting", "p": "The tension between the pleasure principle and the reality principle leads to the modern concept of ''delay discounting.'' The tendency to steeply devalue future rewards is prominent in addiction."}, {"h": "Regulation as an ego function", "p": "In psychoanalysis, the reality principle is a function of the ego, mediating between impulses and reality. Addiction is linked to a weakening of this mediating function (neurally, prefrontal control)."}, {"h": "Theoretical bridge", "p": "The pleasure principle/reality principle serves as a bridge between psychoanalytic concepts and neuroscientific discussions of reward and control circuits. This old concept resonates with modern understandings of addiction."}]'::jsonb, updated_at=now() WHERE id='pleasure-principle';
UPDATE encyclopedia_terms SET definition_en='The use of multiple substances together or alternately, increasing risk due to interactions and complicating treatment. A common pattern is using one substance to counteract the side effects of another.', example_en='Example: cycling between a stimulant to stay awake and a depressant to sleep.', body_en='[{"h": "What is it", "p": "Polysubstance use refers to the use of multiple substances together or alternately, increasing risk due to interactions and complicating treatment."}, {"h": "Why is it used", "p": "A common pattern is using one substance to counteract the side effects of another. A typical cycle involves using a stimulant to stay awake, then a depressant to sleep, and then seeking the stimulant again."}, {"h": "Why is it dangerous", "p": "Interactions between substances can create unpredictable risks, and concurrent use of depressants and opioids significantly increases the risk of overdose. The recent mixing of stimulants with fentanyl poses a new threat."}, {"h": "Treatment challenges", "p": "Dependence on multiple substances simultaneously complicates detoxification and treatment. Focusing on only one substance may lead to switching to another, requiring an integrated approach."}]'::jsonb, advanced_en='[{"h": "Intentional and unintentional concurrent use", "p": "Polysubstance use includes both intentional concurrent use to modulate effects and unintentional concurrent use when illicit drugs are adulterated with other substances. The latter (e.g., fentanyl adulteration) is central to the recent overdose crisis."}, {"h": "Challenges in treatment design", "p": "Individuals who use multiple substances often do not fit well into single-substance-focused treatment models. An integrated, individualized approach addressing risks for each substance is required."}, {"h": "Complexity of overdose", "p": "Overdoses involving multiple substances make it difficult to identify the causative agent and complicate response. The presence of adulterants like xylazine, which is not reversed by naloxone, further complicates management."}]'::jsonb, updated_at=now() WHERE id='polysubstance';
UPDATE encyclopedia_terms SET definition_en='The Portuguese Model is a policy approach adopted in 2001 that decriminalized the personal use and possession of all drugs, replacing criminal penalties with referral to treatment, health services, and social reintegration. Initiated as a public health response to a severe heroin crisis, it has become a prominent global example of a ''treatment instead of punishment'' paradigm.', example_en='When someone is caught possessing drugs, they are sent not to prison but to a committee composed of doctors, social workers, and legal professionals, who connect them to treatment and counseling.', body_en='[{"h": "What It Is", "p": "The Portuguese Model decriminalizes, not legalizes, drug use and possession. Drugs remain illegal, but small quantities for personal use are handled through administrative procedures rather than criminal penalties. Those caught meet with a committee of health and social experts, not a punishment board, and are directed to treatment and support."}, {"h": "Why It Started", "p": "In the 1990s, Portugal faced a severe crisis with a significant portion of the population dependent on heroin, and drug-related deaths and HIV infections among the highest in Europe. The traditional punitive approach of arrest, imprisonment, and stigmatization worsened the crisis, leading to a fundamental shift in 2001 that redefined the issue as a public health matter rather than a criminal one."}, {"h": "What Were the Results", "p": "After the shift, voluntary treatment admissions increased substantially, and drug-related deaths, HIV infections, and incarceration rates notably decreased. Drug use did not skyrocket, and social costs were reportedly reduced. However, debate continues over whether these outcomes are due to decriminalization alone or the concurrent expansion of treatment and social infrastructure."}, {"h": "What It Suggests", "p": "The key lesson is that decriminalization is not a panacea but works when combined with treatment and reintegration infrastructure. Removing punishment alone is insufficient; a health and social system must fill the gap. This is the aspect most often overlooked when other countries attempt to replicate the Portuguese model."}]'::jsonb, advanced_en='[{"h": "Debate Over Outcome Interpretation", "p": "While widely cited, the Portuguese model''s outcomes face criticism regarding causal rigor. Some note that certain indicators began improving before decriminalization, question statistical significance, and argue that confounding factors such as concurrent treatment expansion and economic changes were not adequately controlled. Recent reports also suggest that budget cuts and weakened treatment infrastructure have led to a partial resurgence of problems."}, {"h": "Combination of Decriminalization and Infrastructure", "p": "The core of the Portuguese case lies in the combination of decriminalization with health and social investment. The prevailing view is that outcomes resulted from simultaneously abolishing punishment (reducing penalties) and expanding treatment, housing, and employment support. The later Oregon case illustrates that introducing decriminalization alone, without this combination, can yield different results."}, {"h": "Status as an International Reference", "p": "The Portuguese Model has become a symbolic reference for the ''public health and human rights-based approach'' endorsed by UNODC, WHO, and human rights organizations. At the same time, it represents one axis of a global conflict, with punitive countries criticizing it under the banner of a ''drug-free society.'' The model thus reveals the global value clashes surrounding recovery policy."}]'::jsonb, updated_at=now() WHERE id='portugal-model';
UPDATE encyclopedia_terms SET definition_en='Refers to substances (e.g., colorless, odorless sedatives) that are misused to incapacitate victims. A victim-blaming approach is discouraged; instead, the focus should be on the perpetrator and prevention through awareness education.', example_en='Example: The risk of substances misused to incapacitate victims by being secretly mixed into drinks.', body_en='[{"h": "What is it", "p": "Predatory drugs refer to substances (e.g., colorless, odorless sedatives) that are misused to incapacitate victims."}, {"h": "How are they misused", "p": "They are secretly mixed into drinks to incapacitate the victim''s consciousness and resistance. GHB and certain sedatives are misused due to their colorless, odorless properties."}, {"h": "What is important", "p": "The core of this issue is focusing on the perpetrator, not blaming the victim. The perspective should be ''the misuse is a crime,'' not ''the victim should have been more careful.''"}, {"h": "How to respond", "p": "Prevention through awareness education and drink management is needed, along with a response focused on victim support and perpetrator punishment. A societal attitude that does not blame victims is crucial."}]'::jsonb, advanced_en='[{"h": "Perpetrator-focused perspective", "p": "The key to responding to predatory drug use is focusing on the perpetrator''s actions, not the victim''s behavior. Victim-blaming discourages reporting and causes secondary harm."}, {"h": "Difficulty of detection", "p": "Some substances are rapidly metabolized in the body, making post-incident detection difficult. This characteristic complicates evidence gathering and punishment, highlighting the importance of prompt response and evidence preservation."}, {"h": "Balance between prevention and support", "p": "Prevention education is necessary, but care must be taken not to shift responsibility onto victims. A balance between providing safety information and emphasizing perpetrator accountability is required."}]'::jsonb, updated_at=now() WHERE id='predatory-drugs';
UPDATE encyclopedia_terms SET definition_en='The use of medical drugs (opioid analgesics, stimulants, sedatives) in a manner different from their prescribed purpose or dosage. Because these are perceived as ''doctor-given medications,'' the risks are often underestimated, and this has been a key component of the opioid crisis. Sharing medications with family or friends is also a common route.', example_en='Example: Using leftover painkillers for relaxation rather than pain relief, leading to dependence.', body_en='[{"h": "What is it?", "p": "Prescription drug misuse refers to the use of medical drugs (opioid analgesics, stimulants, sedatives) in a manner different from their prescribed purpose or dosage. Because these are perceived as ''doctor-given medications,'' the risks are often underestimated."}, {"h": "How does it occur?", "p": "It can occur in various ways, such as taking more than the prescribed dose, sharing medications with family or friends (''diversion''), or using them for intoxication. Leftover medications at home are a common starting point."}, {"h": "Why is it dangerous?", "p": "Misuse of prescription drugs can lead to dependence and overdose. Misuse of opioid prescription drugs has been a key component of the opioid crisis, and misuse of sedatives and stimulants also carries serious risks."}, {"h": "Response", "p": "Key measures include safe prescribing, storage, and disposal; prescription monitoring; and education to correct the misconception that ''prescription drugs are safe.'' Balancing legitimate treatment needs with the risk of misuse is crucial."}]'::jsonb, advanced_en='[{"h": "The starting point of the opioid crisis", "p": "The oversupply and misuse of prescription opioids were the early stages of the North American opioid crisis. When regulations were tightened, some users shifted to heroin and fentanyl, a phenomenon known as the ''balloon effect.''"}, {"h": "The dual nature of prescription monitoring", "p": "Prescription drug monitoring programs reduce misuse and duplicate prescribing, but excessive monitoring can hinder legitimate pain patients'' access to treatment. Balancing surveillance and access is a policy challenge."}, {"h": "Management of medications in the home", "p": "Since leftover medications at home are a common starting point for misuse, safe storage and drug take-back/disposal programs are emphasized as practical prevention measures."}]'::jsonb, updated_at=now() WHERE id='prescription-misuse';
UPDATE encyclopedia_terms SET definition_en='Interventions aimed at preventing the onset, progression, and relapse of addiction. It is divided into universal prevention targeting the general population, selective prevention targeting at-risk groups, and indicated prevention targeting high-risk individuals who already show signs. Earlier intervention tends to be more effective and cost-efficient, and the core strategy is to reduce risk factors and enhance protective factors.', example_en='Example: Designing separate programs—universal media literacy education for all adolescents and individual counseling for students already showing signs of over-dependence (indicated).', body_en='[{"h": "What is it?", "p": "Prevention is an intervention that reduces risk before addiction occurs. It is categorized into universal, selective, and indicated prevention based on target population and timing."}, {"h": "What types are there?", "p": "It is divided into universal prevention for the general population, selective prevention for at-risk groups, and indicated prevention for those already showing early signs. A targeted approach is effective."}, {"h": "What is effective?", "p": "Simple ''scare tactic'' education has limited effectiveness; social skills, refusal skills, norm formation, and improving the risk environment are more effective. Both individual and environmental factors should be addressed."}, {"h": "Why is it important?", "p": "Prevention is more cost-effective than treating established addiction, and intervention during adolescence is particularly important. The key is to reduce risk factors and enhance protective factors."}]'::jsonb, advanced_en='[{"h": "Evidence-based prevention", "p": "Fear-arousing or information-only prevention may have weak or even adverse effects. Evidence-based prevention combining social-emotional skills, norm correction, and environmental intervention is effective."}, {"h": "Risk and protective factors", "p": "Prevention aims to reduce risk factors (e.g., trauma, peer influence) and enhance protective factors (e.g., stable relationships, sense of competence). Early developmental intervention is especially effective."}, {"h": "Environmental prevention", "p": "Beyond individual education, environmental prevention such as price, accessibility, and advertising regulations has a large population-level effect. It is important to address both individual responsibility and environmental design."}]'::jsonb, updated_at=now() WHERE id='prevention';
UPDATE encyclopedia_terms SET definition_en='A U.S. policy in the early 20th century that prohibited the manufacture and sale of alcohol. Although drinking decreased, it is often cited as a classic failure because it fueled illegal markets and organized crime. It serves as a historical reference illustrating the limits of prohibition-only policies.', example_en='Example: The historical lesson that total prohibition does not eliminate demand but rather drives it underground.', body_en='[{"h": "What is it?", "p": "Prohibition was a U.S. policy in the early 20th century that banned the manufacture and sale of alcohol. It is frequently cited as a historical example of the limits of total prohibition policies."}, {"h": "What happened?", "p": "Although drinking decreased somewhat, illegal alcohol markets and organized crime grew significantly. Because demand did not disappear while supply was criminalized, the underground market flourished."}, {"h": "What does it imply?", "p": "Prohibition is cited as a lesson that ''total prohibition does not eliminate demand but rather fuels underground markets and crime.'' It is a reference often invoked in today''s drug policy debates."}, {"h": "What should we consider?", "p": "The failure of Prohibition shows that the intentions and actual outcomes of prohibition policies can differ. However, careful application is needed, considering the differences between alcohol and other substances."}]'::jsonb, advanced_en='[{"h": "Unintended consequences of prohibition", "p": "Prohibition is a classic example of the unintended consequences of policy. Side effects included the growth of organized crime, dangerous bootleg liquor, and disrespect for the law."}, {"h": "Analogy to drug policy", "p": "Prohibition is often used as an analogy in critiques of the ''War on Drugs.'' However, due to differences between alcohol''s widespread use and illicit drugs, there is debate over the appropriateness of the analogy."}, {"h": "Arguments for regulated legalization", "p": "After Prohibition''s repeal, alcohol returned to a regulated, taxed legal market. This is cited as an argument for ''regulated legalization'' of some substances—a third way between prohibition and laissez-faire."}]'::jsonb, updated_at=now() WHERE id='prohibition';
UPDATE encyclopedia_terms SET definition_en='A concept referring to a state where the behavior of requesting more medication due to insufficient pain control appears similar to addiction, but is actually caused by undertreatment. However, this concept has been criticized for being misused to justify overprescribing, so it should be handled with caution.', example_en='Example: If the behavior of requesting medication disappears when pain is properly managed, it suggests that it was not addiction.', body_en='[{"h": "What is it", "p": "Pseudoaddiction is a concept referring to a state where the behavior of requesting more medication due to insufficient pain control appears similar to addiction, but is actually caused by undertreatment."}, {"h": "How to differentiate", "p": "If the behavior of requesting medication disappears when pain is properly managed, it suggests that it was not addiction but a sign of inadequate pain control. This is the core logic of pseudoaddiction."}, {"h": "Why is it important", "p": "The concept of pseudoaddiction was introduced to prevent the denial of treatment due to misinterpreting legitimate requests for medication from pain patients as addiction."}, {"h": "Criticism exists", "p": "However, this concept has been criticized for being misused to justify overprescribing of opioids. Therefore, it is now handled with caution and based on evidence."}]'::jsonb, advanced_en='[{"h": "Purpose and misuse", "p": "Pseudoaddiction originated from the legitimate purpose of protecting pain patients, but it has been criticized for being misused by pharmaceutical marketing and others to rationalize overprescribing. There are also concerns that the evidence base for the concept itself is weak."}, {"h": "Relationship with the opioid crisis", "p": "The misuse of the pseudoaddiction concept is cited as one of the backgrounds of the opioid crisis. The logic that ''even if it looks like addiction, it''s due to pain'' may have led to ignoring warning signs."}, {"h": "Need for balance", "p": "Pseudoaddiction illustrates the tension between pain treatment and addiction prevention. A balanced judgment is required that respects legitimate pain requests while not overlooking actual addiction risks."}]'::jsonb, updated_at=now() WHERE id='pseudoaddiction';
UPDATE encyclopedia_terms SET definition_en='A classic psychedelic that is the main component of hallucinogenic mushrooms, acting on the serotonin system to induce altered states of consciousness. Along with risks of recreational use, it is a representative substance being studied in controlled clinical settings for potential treatment of depression and addiction.', example_en='Example: The distinction between the risks of misusing wild mushrooms and the therapeutic use in standardized clinical research.', body_en='[{"h": "What is it", "p": "Psilocybin is a classic psychedelic that is the main component of hallucinogenic mushrooms, acting on the serotonin system to induce altered states of consciousness."}, {"h": "What are the risks", "p": "Misuse of wild mushrooms adds the risk of poisoning due to species misidentification. Similar to LSD, there are risks of unpredictable psychological reactions and accidents, and it is particularly dangerous for individuals with underlying mental disorders."}, {"h": "Therapeutic research", "p": "Psilocybin is a representative substance being actively studied in controlled clinical settings for potential treatment of treatment-resistant depression, anxiety, and addiction. Some regions are moving toward institutionalization."}, {"h": "What should be distinguished", "p": "Psilocybin therapy in clinical research includes standardized dosing, a safe environment, therapist accompaniment, and integrative psychotherapy. This is fundamentally different from self-administration of wild mushrooms."}]'::jsonb, advanced_en='[{"h": "Frontiers of therapeutic research", "p": "Psilocybin-assisted therapy is at the center of the psychedelic research renaissance, with positive signals reported in several clinical trials. However, methodological challenges remain, including difficulties with blinding and long-term effects."}, {"h": "Mechanism hypotheses", "p": "It has been hypothesized that psilocybin promotes neuroplasticity and makes rigid self- and world-perceptions more flexible, thereby producing therapeutic effects, but this has not been established."}, {"h": "Institutionalization and accessibility", "p": "Institutionalization in some regions raises new challenges of accessibility, equity, and safe implementation. Clearly distinguishing between therapeutic contexts and recreational use is key."}]'::jsonb, updated_at=now() WHERE id='psilocybin';
UPDATE encyclopedia_terms SET definition_en='An approach that combines hallucinogenic or psychedelic substances such as psilocybin and MDMA with structured psychotherapy to treat depression, PTSD, addiction, and other conditions. Multiple clinical trials have reported potential, and some regions are moving toward institutionalization, but regulatory decisions and evidence are still evolving, and a safe setting is emphasized as essential. The key is a controlled therapeutic context distinct from recreational use.', example_en='Example: A psilocybin-assisted therapy session conducted in a controlled clinical environment with a therapist present (a context entirely different from self-use).', body_en='[{"h": "What is it", "p": "Psychedelic-assisted therapy is an approach that combines hallucinogenic or psychedelic substances such as psilocybin and MDMA with structured psychotherapy to treat depression, PTSD, addiction, and other conditions. The key is a controlled therapeutic context distinct from recreational use."}, {"h": "How does it work", "p": "It is not the drug alone but is combined with preparation, accompaniment, and integration by trained therapists. Sessions conducted in a safe setting and follow-up therapy that integrates the experience into daily life form a complete set. The combination of ''set and setting'' and psychotherapy, rather than the substance itself, determines outcomes."}, {"h": "Potential for addiction treatment", "p": "Some clinical trials have reported potential for psychedelic-assisted therapy for alcohol and nicotine use disorders. The hypothesis being studied is that experiences that make rigid thought and behavior patterns more flexible and open new perspectives can serve as turning points in recovery."}, {"h": "Caution is needed", "p": "This is still a research stage, and regulatory decisions and evidence are evolving. Safe clinical settings and trained therapists are essential, and self-use carries entirely different risks. This area must be handled carefully, guarding against exaggerated expectations and recreational use."}]'::jsonb, advanced_en='[{"h": "Research status and regulation", "p": "Psilocybin- and MDMA-assisted therapy have shown potential in multiple clinical trials, and some regions are moving toward institutionalization, but regulatory approval status varies by country and substance and continues to change. Methodological challenges remain, including evidence quality, difficulty of blinding, and long-term safety."}, {"h": "Mechanism hypotheses", "p": "It is hypothesized that psychedelics promote neuroplasticity and temporarily make rigid self- and world-perceptions more flexible, enabling new insights and behavioral changes. However, the connection between this mechanism and therapeutic effects is not yet established."}, {"h": "Boundary with recreational use", "p": "The core of therapeutic use is controlled setting, professional accompaniment, and integration with psychotherapy, which is fundamentally different from recreational or self-use. Public interest risks blurring this boundary and encouraging self-use, so it is important to clearly distinguish between therapeutic context and recreational use."}]'::jsonb, updated_at=now() WHERE id='psychedelic-therapy';
UPDATE encyclopedia_terms SET definition_en='Posttraumatic stress disorder (PTSD) very commonly co-occurs with addiction, and self-medication to soothe intrusive and hyperarousal symptoms intertwines the two problems. Integrated treatment addressing both trauma and addiction is recommended.', example_en='Example: A pathway where one relies on alcohol or sedatives to suppress trauma nightmares and hyperarousal.', body_en='[{"h": "What is it", "p": "PTSD is a disorder characterized by persistent intrusive, avoidance, and hyperarousal symptoms after a traumatic experience, and it very commonly co-occurs with addiction."}, {"h": "How are they connected", "p": "A typical pathway is self-medication, where individuals rely on substances to alleviate the distress of intrusive memories, nightmares, and hyperarousal. The pain of trauma and addiction become intertwined."}, {"h": "Vicious cycle", "p": "Substances may temporarily dull PTSD symptoms, but in the long term, they hinder recovery and worsen symptoms. The two problems reinforce each other in a vicious cycle."}, {"h": "Implications for treatment", "p": "Integrated treatment addressing both trauma and addiction is recommended. Focusing on only one problem increases the risk of relapse, and a phased approach that ensures safety before addressing trauma is often used."}]'::jsonb, advanced_en='[{"h": "High comorbidity rates", "p": "PTSD and substance use disorder are a classic comorbid pair that significantly increase each other''s risk. This is especially prominent among combat veterans and victims of violence."}, {"h": "Integrated treatment models", "p": "Integrated models such as Seeking Safety have been developed to address both PTSD and addiction simultaneously. Key principles include prioritizing safety and avoiding retraumatization."}, {"h": "Trauma-informed perspective", "p": "The co-occurrence of PTSD and addiction highlights the need for a trauma-informed approach that asks ''What happened?'' rather than ''What is wrong?'' Addressing the root of suffering is essential for sustained recovery."}]'::jsonb, updated_at=now() WHERE id='ptsd-addiction';
UPDATE encyclopedia_terms SET definition_en='A continuous process of moving away from addiction and regaining health and life functioning. It goes beyond mere cessation of use to include the restoration of relationships, meaning, and self-efficacy, and an international perspective is spreading that views relapse not as failure but as part of the process. The prevailing view is that recovery is not a destination of cure but a journey of ongoing management and growth.', example_en='Example: The process of rebuilding oneself over several years, not only by stopping substance use but also by restoring broken relationships, establishing a new daily routine, and finding meaning in life.', body_en='[{"h": "What is it", "p": "Recovery is a continuous process of moving away from addiction and regaining health and life functioning. It goes beyond simply stopping substance use or behavior to include restoring relationships, meaning, and self-efficacy. Today, the prevailing view sees recovery not as a destination of cure but as a journey of ongoing management and growth."}, {"h": "How is it different from abstinence", "p": "Stopping use (abstinence) is only the starting point of recovery, not the whole. For recovery to be sustained, it must be accompanied by restoring broken relationships, rebuilding a disrupted daily life, and re-establishing meaning and purpose in life. Thus, what one has built matters more than what one has stopped in determining the substance of recovery."}, {"h": "How is relapse viewed", "p": "Recovery is not a straight line but a process with ups and downs, and relapse is often understood as part of that journey. Rather than stigmatizing relapse as a moral failure, treating it as a signal to learn what was lacking and readjust strategies helps recovery continue. This shift in perspective gives strength not to give up on recovery."}, {"h": "You are not alone", "p": "Recovery is not achieved by individual will alone. The more resources such as supportive relationships, stable daily life, and recovery communities are present, the more recovery is maintained. When recovery is seen not as an individual task but as a process supported by surrounding relationships and society, more sustainable outcomes emerge."}]'::jsonb, advanced_en='[{"h": "Expansion of the recovery concept", "p": "The definition of ''recovery'' has expanded beyond simple use control to encompass overall health and well-being. This expansion has become the theoretical foundation for the concept of recovery capital and recovery-oriented systems of care (ROSC), and indicators of success have broadened from abstinence rates to quality of life, social integration, and sustained well-being."}, {"h": "Natural recovery and diverse pathways", "p": "Not all recovery goes through professional treatment. A significant number recover without formal treatment (natural recovery), and recovery pathways vary, including 12-step programs, secular self-help, medication-assisted treatment, and faith communities. A characteristic of modern recovery discourse is acknowledging multiple pathways without presupposing a single right way."}, {"h": "Perspectives of individuals and communities", "p": "From the perspective of the recovery field, the core drivers of recovery are relationships, belonging, and the reconstruction of one''s own narrative. Recovery communities are spaces where people with shared experiences support each other and restore identity, and models that rebuild entire lives, such as faith-based or eco-based recovery villages, are gaining attention as expanded forms."}]'::jsonb, updated_at=now() WHERE id='recovery';
UPDATE encyclopedia_terms SET definition_en='The total amount of personal, social, and community resources that can be mobilized to initiate and sustain recovery. It includes networks, economic stability, supportive communities, self-efficacy, meaning and purpose, and the greater this capital, the higher the likelihood of sustained recovery. This perspective focuses on strengths and resources rather than individual pathology, highlighting the role of recovery communities.', example_en='Example: Even when facing similar difficulties, a person with a supportive community, stable job, and trusting relationships is more likely to maintain recovery than someone without these resources.', body_en='[{"h": "What Is It", "p": "Recovery capital is the total amount of personal, social, and community resources that can be mobilized to initiate and sustain recovery. It includes networks, economic stability, supportive communities, self-efficacy, meaning and purpose, and the greater this capital, the higher the likelihood of sustained recovery."}, {"h": "Types of Resources", "p": "It is commonly divided into three layers: personal capital (health, skills, self-efficacy), social capital (family, friends, supportive relationships), and community capital (recovery meetings, services, social acceptance). These resources interlock to support recovery."}, {"h": "Why It Matters", "p": "Even when facing similar difficulties, a person with a supportive community, stable job, and trusting relationships is more likely to maintain recovery than someone without these resources. Recovery capital reframes recovery not as a matter of individual pathology or willpower but as a question of ''available resources,'' directing attention to strengths."}, {"h": "How to Build It", "p": "Recovery capital is not fixed; it can be cultivated. Restoring relationships, securing stable housing and employment, joining a recovery community, and building self-efficacy through small successes all thicken recovery capital. Recovery-oriented systems of care (ROSC) aim precisely to build this capital."}]'::jsonb, advanced_en='[{"h": "Origin and Development of the Concept", "p": "Recovery capital was introduced by Granfield and Cloud, representing a strengths-based perspective that views recovery as an accumulation of resources and capacities rather than individual deficits. It later became the theoretical foundation for recovery-oriented systems of care (ROSC) and recovery management, and measurement tools such as the BARC-10 have been developed."}, {"h": "Mutual Reinforcement Dynamics", "p": "Recovery capital and recovery mutually reinforce each other. Early abstinence leads to positive outcomes such as relationship repair and stability, and the accumulated capital in turn sustains abstinence. How to trigger and maintain this virtuous cycle is a key design principle of recovery support."}, {"h": "Community Recovery Capital", "p": "Recovery capital accumulates not only at the individual level but also at the community level. Recovery communities and recovery villages build community recovery capital by providing belonging, meaning, roles, and a foundation for independence. This shifts the view of recovery from individual treatment to a matter of social infrastructure and provides the theoretical basis for faith-based and ecological recovery village models."}]'::jsonb, updated_at=now() WHERE id='recovery-capital';
UPDATE encyclopedia_terms SET definition_en='A perspective that places society''s response to addiction on a spectrum from punishment-centered to public health and recovery-centered approaches, comparing national approaches. Even for the same problem, outcomes vary greatly depending on the philosophy and infrastructure chosen, and the recent global trend is shifting from punishment to prevention, treatment, and recovery support.', example_en='For the same issue of small-scale possession, one country responds with incarceration while another with treatment referral, leading to entirely different social outcomes.', body_en='[{"h": "What is compared", "p": "Recovery policy is not singular but a spectrum. At one end is a hardline approach prioritizing supply reduction and criminal punishment (War on Drugs), and at the other end is a health approach prioritizing harm reduction and recovery support. Most countries lie somewhere in between, shifting with time and politics."}, {"h": "Where is the trend heading", "p": "Recent international trends are shifting the center of gravity toward prevention, treatment, and recovery support as the limitations of punishment-only approaches become evident. International organizations recommend public health and human rights-based approaches, and many countries are introducing systems that divert individuals to treatment instead of punishment. However, this shift is not linear but a winding process with setbacks, as seen in Oregon."}, {"h": "What determines outcomes", "p": "A key lesson is that outcomes are determined more by the infrastructure and sustainability supporting a policy than by its label (decriminalization, legalization, punishment). The same decriminalization yields results when accompanied by treatment and reintegration systems (Portugal), but backslides when introduced without infrastructure (Oregon). Policy does not operate in a vacuum but within material environments, resources, and culture."}, {"h": "Implications for Korea", "p": "Global comparison serves as a mirror for reflecting on Korea''s policy. Regardless of the approach chosen, the thickness of treatment and recovery infrastructure to replace or supplement punishment is key, and cases from various countries commonly show that sustainable results emerge when recovery is viewed not as an individual''s will but as a task society supports together."}]'::jsonb, advanced_en='[{"h": "Distinction between decriminalization, legalization, and harm reduction", "p": "Conceptual distinctions are important when comparing global policies. Decriminalization removes criminal penalties but maintains illegality; legalization permits a legal market; harm reduction reduces harm without requiring cessation of use. Confusing these leads to misreading the successes and limitations of each country''s case."}, {"h": "Conflict between evidence and values", "p": "Recovery policy is not determined solely by evidence. Moral values like ''drug-free society'' and pragmatic values like ''harm minimization'' conflict, and the same data can be interpreted to reach opposing conclusions. Policy comparison reveals not only effectiveness but also which values a society prioritizes."}, {"h": "Potential expansion to behavioral addictions", "p": "Existing recovery policy discussions have mainly focused on substances (drugs), but expansion to behavioral addictions such as gambling and gaming remains a challenge. Areas like gambling industry regulation, game user protection, and digital environment design require different approaches from substance policies, and international comparison in this area is still in its early stages."}]'::jsonb, updated_at=now() WHERE id='recovery-policy-global';
UPDATE encyclopedia_terms SET definition_en='Reinforcement is the process by which a consequence following a behavior increases the likelihood of that behavior recurring. Positive reinforcement increases behavior by adding something pleasant (e.g., pleasure, excitement), while negative reinforcement increases behavior by removing something unpleasant (e.g., anxiety, withdrawal, pain). Addiction often begins with positive reinforcement (seeking pleasure) and shifts to negative reinforcement (avoiding pain), and this transition accounts for the difference between initial use and later compulsive use.', example_en='Example: Initially drinking for pleasure (positive reinforcement), later drinking to relieve anxiety and withdrawal symptoms that occur without drinking (negative reinforcement).', body_en='[{"h": "What Is It", "p": "Reinforcement is a process that increases the likelihood of a behavior recurring. It is divided into positive reinforcement, which involves obtaining a reward, and negative reinforcement, which involves removing an aversive stimulus."}, {"h": "Positive Reinforcement", "p": "Positive reinforcement occurs when a behavior is followed by a reward (pleasure, euphoria), increasing the behavior. In early addiction, the pleasure from a substance reinforces use."}, {"h": "Negative Reinforcement", "p": "Negative reinforcement occurs when a behavior removes an aversive state (withdrawal, anxiety, pain), increasing the behavior. In later addiction, using a substance to avoid withdrawal or pain is negative reinforcement."}, {"h": "Implications", "p": "Addiction is a process in which the emphasis shifts from positive reinforcement (seeking pleasure) to negative reinforcement (avoiding pain). Understanding this transition is important for addressing later-stage addiction and recovery."}]'::jsonb, advanced_en='[{"h": "The Shift in Dual Reinforcement", "p": "The progression of addiction is described as a shift from positive reinforcement dominance to negative reinforcement dominance. This is linked to the allostasis and ''dark side'' theories, highlighting the chronic distress in later addiction."}, {"h": "Limitations of Punishment", "p": "Punishment (positive or negative) can suppress behavior, but in addiction, its effectiveness is limited and it often leads to stigma and avoidance. Therefore, alternative reinforcement is emphasized over punishment."}, {"h": "Restoration of Natural Rewards", "p": "Recovery can be seen as a process of replacing the artificial reinforcement of substances with reinforcement from natural rewards (relationships, achievement, meaning). Restoring alternative reinforcers is key to sustained recovery."}]'::jsonb, updated_at=now() WHERE id='reinforcement';
UPDATE encyclopedia_terms SET definition_en='Relapse refers to returning to substance use or behavior that had been stopped during the recovery process. It is understood as a common phenomenon in chronic diseases and is best treated not as a moral failure but as a signal to readjust treatment and strategies.', example_en='Example: A person who had maintained well for several months relapses under a major stressful situation. Instead of stigmatizing this as a failure, they analyze the causes and reinforce their plan.', body_en='[{"h": "What is it?", "p": "Relapse refers to returning to substance use or behavior that had been stopped during the recovery process. It is understood as a common phenomenon in chronic diseases and is best treated not as a moral failure but as a signal to readjust treatment and strategies."}, {"h": "Why does it happen?", "p": "High-risk situations, negative emotions (anxiety, depression, anger, loneliness), exposure to cues, and complacency are major triggers. Thoughts like ''just this once won''t hurt'', lack of skills to withstand cravings, and weakened supportive relationships lead to relapse. Relapse is usually not a sudden event but the result of a cumulative process."}, {"h": "How to handle it?", "p": "Stigmatizing relapse as a failure leads to shame and abandonment of recovery efforts. Instead, it is key to analyze ''what triggered the relapse'' and use it as a learning opportunity to reinforce the plan. Early intervention to prevent a single lapse from turning into a full relapse is also important."}, {"h": "Prevention", "p": "Identifying high-risk situations in advance and preparing coping strategies, skills to withstand cravings, maintaining supportive relationships, and a balanced lifestyle reduce relapse risk. Relapse prevention is not an adjunct to recovery but a core skill of recovery itself."}]'::jsonb, advanced_en='[{"h": "Distinction between lapse and relapse", "p": "Clinically, a distinction is made between a single lapse and a full return to previous patterns (relapse). The ''abstinence violation effect'' (AVE), where one thinks ''I''ve already failed, so it''s all over,'' is a psychological mechanism that turns a lapse into a relapse. Addressing this cognitive distortion is central to relapse prevention."}, {"h": "Chronic disease model and relapse", "p": "From the perspective of addiction as a chronic, relapsing disease, relapse rates are often compared to those of other chronic conditions like diabetes or hypertension. This framework reframes relapse not as treatment failure but as a signal that ongoing management is needed, supporting long-term care rather than one-time treatment."}, {"h": "Client perspective", "p": "For the individual, the greatest danger of relapse is not the relapse itself but the shame and self-stigma it brings. Learned helplessness—''I really can''t do it''—leads to giving up recovery efforts. Therefore, a non-judgmental attitude in the recovery community when dealing with relapse is crucial for sustained recovery."}]'::jsonb, updated_at=now() WHERE id='relapse';
UPDATE encyclopedia_terms SET definition_en='Relapse prevention is a cognitive-behavioral approach that reduces relapse by identifying high-risk situations and training coping skills. It covers craving management, refusal skills, cognitive restructuring, and balanced living, reframing relapse as a learning opportunity.', example_en='Example: Identifying ''which situations become risky'' in advance and training to set up coping plans for those moments.', body_en='[{"h": "What Is It", "p": "Relapse prevention is a cognitive-behavioral approach that reduces relapse by identifying high-risk situations and training coping skills. It covers craving management, refusal skills, restructuring distorted thoughts, and balanced living, reframing relapse not as failure but as a learning opportunity."}, {"h": "How It Works", "p": "First, concretely identify ''which situations become risky'' (places, people, emotions, times), and prepare coping plans in advance for what to do then. Key skills include understanding that cravings come like waves and subside, learning to endure them, refusing offers, and challenging thoughts like ''just this once.''"}, {"h": "Why It Matters", "p": "Stopping substance use through treatment and maintaining that state are different tasks. Relapse prevention addresses the skills to ''maintain'' recovery; without it, treatment effects easily collapse in high-risk situations. Thus, relapse prevention is treated not as an adjunct to recovery but as a core skill of recovery."}, {"h": "Life Balance", "p": "Extreme abstinence, overwork, or isolation can actually increase relapse risk. A balanced life with sleep, exercise, relationships, and meaningful activities itself forms the foundation for preventing relapse. Relapse prevention includes not only coping in crisis moments but also rebuilding everyday life."}]'::jsonb, advanced_en='[{"h": "Application of the Cognitive-Behavioral Model", "p": "Relapse prevention is rooted in Marlatt''s cognitive-behavioral relapse prevention model. It analyzes the chain of high-risk situation–coping response–self-efficacy–outcome expectancy, targeting which link to break. Addressing cognitive distortions such as the abstinence violation effect (AVE) is a characteristic of this approach."}, {"h": "Mindfulness-Based Expansion", "p": "Recently, approaches like mindfulness-based relapse prevention (MBRP) have been added, which involve observing cravings non-judgmentally and letting them pass rather than suppressing them. Evidence is accumulating that the skill of staying with cravings rather than fighting them weakens the automatic response chain that triggers cravings."}, {"h": "Perspective of the Person in Recovery", "p": "The essence of relapse prevention is ''not being alone in moments of crisis.'' Even with a plan, it is easy to break down in isolation, so supportive relationships and recovery communities that can be contacted immediately become core resources in the coping plan. Relapse prevention works when skills and relationships go together."}]'::jsonb, updated_at=now() WHERE id='relapse-prevention';
UPDATE encyclopedia_terms SET definition_en='A psychoanalytic concept referring to the unconscious tendency to repeat painful or harmful experiences. Proposed by Freud, it suggests that individuals repeat unresolved conflicts or trauma in an attempt to unconsciously control or resolve them. It provides a framework for understanding the self-destructive repetitiveness of addiction—returning to the same patterns despite knowing the harm.', example_en='Example: A pattern where, despite paying a heavy price each time a relapse occurs, the individual repeatedly seeks substances in the same way when a crisis arises.', body_en='[{"h": "What Is It", "p": "Repetition compulsion is a psychoanalytic concept referring to the unconscious tendency to repeat painful experiences or relationship patterns. It was introduced by Freud."}, {"h": "How Is It Connected to Addiction", "p": "The repetitive, self-destructive use in addiction is sometimes interpreted as a form of repetition compulsion. Repeating the same pattern despite knowing it is harmful aligns with this concept."}, {"h": "What Does It Suggest", "p": "This perspective views the repetition in addiction not merely as reward-seeking but as a reenactment of unresolved psychological conflicts or trauma. It focuses on the unconscious meaning behind the repetition."}, {"h": "Implications for Treatment", "p": "The repetition compulsion perspective suggests exploring the meaning behind repetitive patterns and making conscious what was unconsciously reenacted. Insight may help break the cycle of repetition."}]'::jsonb, advanced_en='[{"h": "Psychoanalytic Origins", "p": "Repetition compulsion is a concept Freud proposed as a phenomenon beyond the pleasure principle. It points to the existence of painful repetitions that cannot be explained by pleasure alone."}, {"h": "Trauma Reenactment", "p": "This concept is linked to the unconscious reenactment of trauma. The view that unresolved early experiences are repeatedly reenacted in relationships and behaviors aligns with trauma-based approaches."}, {"h": "Modern Reinterpretation", "p": "Today, repetition compulsion is sometimes reinterpreted alongside learning and neuroscience concepts such as automatization of habit circuits and conditioned responses. Psychodynamic meaning and behavioral mechanisms are discussed complementarily."}]'::jsonb, updated_at=now() WHERE id='repetition-compulsion';
UPDATE encyclopedia_terms SET definition_en='A hypothesis that the function of the brain''s reward circuit is diminished, preventing individuals from obtaining sufficient satisfaction from ordinary stimuli, leading them to seek stronger stimuli (addictive substances or behaviors) to compensate for this deficit. Proposed as a theoretical framework linking dopaminergic genetic vulnerability to addictive tendencies, it is used to explain why some people become addicted more easily. However, it has been criticized for oversimplifying addiction as a single-gene determinism.', example_en='Example: A person who rarely feels excitement from everyday pleasures becomes engrossed only in activities that provide intense stimulation.', body_en='[{"h": "What is it?", "p": "Reward Deficiency Syndrome refers to a concept where the brain''s reward system is blunted, making it difficult to derive satisfaction from normal stimuli. The hypothesis suggests that individuals seek stronger stimuli (substances or behaviors) to compensate for this deficit."}, {"h": "How is it explained?", "p": "When the reward circuit becomes blunted due to repeated use, natural rewards in daily life (food, relationships, achievements) feel dull. The vicious cycle of filling this void with stronger artificial rewards perpetuates addiction."}, {"h": "What does it imply?", "p": "This perspective reinterprets addiction not as ''pleasure seeking'' but as an attempt to barely restore a disrupted reward baseline to normal. It provides a framework for understanding anhedonia and craving in later-stage addiction."}, {"h": "Relationship with recovery", "p": "The anhedonia and emptiness in early recovery are linked to this reward blunting. Over time, the reward system recovers, but rebuilding experiences with natural rewards during this period is crucial."}]'::jsonb, advanced_en='[{"h": "Dopamine dysfunction", "p": "Reward Deficiency Syndrome is proposed to be associated with reduced dopamine receptor density and function. This decrease is hypothesized to lead to craving for strong stimuli and insensitivity to natural rewards."}, {"h": "Genetic and conceptual debates", "p": "The concept originated from claims linking specific gene variants, but there is debate over the consistency of evidence and the validity of the concept. Despite its appealing explanatory power, it should be approached with caution."}, {"h": "Connection to anhedonia", "p": "Reward deficiency is closely related to anhedonia, explaining the core suffering in later-stage addiction and early recovery. Restoring natural rewards is emphasized as key to overcoming this period."}]'::jsonb, updated_at=now() WHERE id='reward-deficiency';
UPDATE encyclopedia_terms SET definition_en='A policy framework that views addiction not as a one-time treatment event but as a long-term recovery journey, and supports prevention, treatment, continuing care, and long-term recovery through a connected community network. It shifts the focus from ''treat and discharge'' to ''treat, connect, and sustain,'' with person-centered and strengths-based approaches as core principles.', example_en='A community-based system that provides housing, employment, peer support, and medical care as an integrated network for individuals who have completed treatment, helping them maintain recovery in daily life.', body_en='[{"h": "What Is It", "p": "Recovery-Oriented Systems of Care (ROSC) is an approach that reorganizes addiction response around the ''lifelong recovery journey'' rather than ''acute treatment episodes.'' It views prevention, early intervention, treatment, continuing care, and long-term recovery as a continuum, and connects clinical services with non-clinical supports (housing, employment, peer support) through a community network."}, {"h": "How Is It Different", "p": "While traditional treatment focuses on indicators such as ''treatment completion rate,'' ''length of stay,'' and ''short-term abstinence,'' ROSC adds long-term outcomes like accumulation of recovery capital, community integration, employment and housing stability, and sustained well-being. The definition of success itself expands from ''symptom removal'' to ''life reconstruction.''"}, {"h": "Why Is It Important", "p": "The background is the recognition that treatment alone is insufficient. Without stable housing, relationships, and employment, treatment effects are difficult to maintain. ROSC redefines recovery not as a matter of individual will but as a matter of resources and relationships surrounding the individual, and designs society to collectively support those resources."}, {"h": "How Is It Implemented", "p": "Peer recovery coaches, recovery housing, employment and education linkages, family support, and local recovery communities are placed alongside clinical treatment. Several countries and state governments have adopted this framework, with Alberta, Canada being a representative example that institutionalized ROSC by establishing a dedicated agency and research center in 2024."}]'::jsonb, advanced_en='[{"h": "Integration with Recovery Capital", "p": "The theoretical heart of ROSC is ''recovery capital.'' Recovery goes beyond abstinence itself to the accumulation of resources such as health, relationships, and meaning. It is understood as a mutually reinforcing relationship where initial abstinence generates resources, and those resources in turn sustain abstinence. ROSC is based on the principle of placing support services that build this recovery capital alongside treatment."}, {"h": "Shift in Outcome Measurement", "p": "ROSC fundamentally changes outcome indicators. Instead of short-term abstinence rates, it measures long-term recovery trajectories, recovery capital development, community integration, employment and housing stability, and sustained well-being. This shift requires agencies to adopt longitudinal outcome measurement systems and is driving a trend where funding criteria are also reorganized accordingly."}, {"h": "Interface with Faith and Community", "p": "ROSC includes diverse local resources—not only medical and social services but also faith communities and recovery communities—as partners in recovery. In this respect, it naturally interfaces with models such as faith-based recovery communities or ecologically based recovery villages. The underlying perspective is that recovery is a community task, not an individual one."}]'::jsonb, updated_at=now() WHERE id='rosc';
UPDATE encyclopedia_terms SET definition_en='Scotland''s first safer drug consumption facility, ''The Thistle,'' opened in Glasgow in January 2025 as a three-year pilot project to address Europe''s worst drug death crisis. It circumvented UK laws criminalizing possession by relying on the Lord Advocate''s policy of not prosecuting possession within the facility.', example_en='A long-term injector at Glasgow''s The Thistle uses safely under supervision and is connected to wound care, infection testing, housing, and recovery services.', body_en='[{"h": "What is it", "p": "The Thistle, opened in January 2025 in Glasgow, is the UK''s first safer drug consumption facility. It allows users to consume their own drugs in a hygienic environment under the supervision of trained health and social care professionals, aiming to reduce overdose and infection risks and link users to treatment and recovery services."}, {"h": "Why was it created", "p": "Scotland has experienced Europe''s worst drug-related death rates, with deaths concentrated in areas of high social deprivation. Glasgow has long called for such a facility to address public injecting and HIV outbreaks."}, {"h": "How the legal barrier was overcome", "p": "The UK''s Misuse of Drugs Act, which criminalizes drug possession, long prevented the facility''s opening. In 2023, Scotland''s Lord Advocate stated that prosecuting possession for personal use within the facility would not be in the public interest, and formalized this policy in 2025, paving the way. However, the policy applies only inside the facility, not in surrounding areas."}, {"h": "An ongoing experiment", "p": "The Thistle is a three-year pilot funded by the Scottish Government, with independent evaluation underway. Early reports indicate many users have accessed the facility without medical emergencies, and some have been linked to housing and recovery services. However, concerns from nearby residents and criticism of insufficient investment in recovery services have also emerged."}]'::jsonb, advanced_en='[{"h": "''Gold standard'' service design", "p": "The Thistle is operated by a multidisciplinary team (nursing, psychology, social work, medical, harm reduction) trained in trauma-informed care, with the space designed incorporating lived experience. It features individual booths, post-use recovery areas, wound care and infection testing rooms, and aims to connect vulnerable groups to services without judgment."}, {"h": "Harm reduction vs. recovery debate", "p": "In Glasgow, tensions exist between those who see the facility as ''admitting failure'' (recovery-focused) and those who view it as part of a broader care system. The facility''s advocates emphasize it is ''not a standalone solution but part of a wider care continuum,'' and balanced investment in rehabilitation services is needed."}, {"h": "Evaluation and spread", "p": "The independent evaluation of this pilot will determine whether the model expands to other parts of the UK. Key factors include concerns about crime and disorder in surrounding areas, policy coherence outside the facility, and financial sustainability. Political patience while evidence accumulates is being tested."}]'::jsonb, updated_at=now() WHERE id='scotland-thistle';
UPDATE encyclopedia_terms SET definition_en='The exposure of non-smokers to tobacco smoke from others, which has been proven to cause clear health harms and has become the basis for smoke-free zones and indoor smoking regulations. It is a representative example of how individual actions can harm others.', example_en='Example: Smoke from a smoker harms the health of nearby non-smokers, leading to regulations in public places.', body_en='[{"h": "What is it?", "p": "Secondhand smoke is the exposure of non-smokers to tobacco smoke from others, which has been proven to cause clear health harms and has become the basis for smoke-free zones and indoor smoking regulations."}, {"h": "What does it demonstrate?", "p": "Secondhand smoke is a representative example of how an individual''s behavior (smoking) can harm the health of others. This ''harm to others'' has become a key rationale justifying smoking regulations."}, {"h": "What regulations did it lead to?", "p": "The proven harms of secondhand smoke led to strong policies such as smoke-free public places and indoor smoking bans. It shifted smoking from a matter of personal freedom to a public health issue."}, {"h": "What should we consider?", "p": "Secondhand smoke regulations illustrate how society balances individual freedom and the right to health of others when they conflict. New concerns such as thirdhand smoke (residue) are also emerging."}]'::jsonb, advanced_en='[{"h": "Harm-to-others principle", "p": "Secondhand smoke regulations have stronger justification than regulations on personal use because they target behaviors that harm others. This reflects the classic tension between freedom and preventing harm."}, {"h": "Policy success story", "p": "Secondhand smoke regulations and smoking bans are considered a public health success story that reduced smoking rates. It is a model pathway where evidence accumulation led to policy change."}, {"h": "Thirdhand smoke and new debates", "p": "Recently, the harms of tobacco residue left on surfaces and dust (thirdhand smoke) have been discussed. This shows that understanding of tobacco harms continues to expand."}]'::jsonb, updated_at=now() WHERE id='secondhand-smoke';
UPDATE encyclopedia_terms SET definition_en='Self-efficacy is the belief in one''s own ability to handle specific situations, as proposed by Bandura. In addiction recovery, the efficacy belief that ''I can refrain from using in tempting situations'' is a strong predictor of relapse. Accumulation of small success experiences, vicarious experiences, and supportive encouragement enhance self-efficacy, which is a key target of motivational interviewing and relapse prevention.', example_en='Example: Successfully navigating a crisis once leads to the belief ''I can endure it,'' which increases coping ability in subsequent temptations.', body_en='[{"h": "What is it?", "p": "Self-efficacy is the belief in one''s own ability to handle specific situations. It was proposed by Bandura."}, {"h": "Why is it important in addiction recovery?", "p": "The efficacy belief that ''I can refrain from using in tempting situations'' is a strong predictor of relapse. The more one believes in their coping ability, the better they navigate high-risk situations."}, {"h": "How to enhance it?", "p": "Accumulation of small success experiences, vicarious experiences (witnessing others'' recovery), supportive encouragement, and emotional management enhance self-efficacy. Successfully navigating a crisis once leads to the belief ''I can endure it.''"}, {"h": "What does it imply?", "p": "Recovery is not a matter of willpower but of belief in one''s ability to cope and actual skills. Building experiences that enhance self-efficacy becomes a core recovery strategy."}]'::jsonb, advanced_en='[{"h": "Key variable in relapse prevention", "p": "Self-efficacy is a key variable in Marlatt''s relapse prevention model. In high-risk situations, high self-efficacy leads to coping responses, while low self-efficacy easily leads to relapse."}, {"h": "Four sources", "p": "Bandura identified four sources of self-efficacy: mastery experiences, vicarious experiences, verbal persuasion, and emotional arousal states. Recovery support utilizes these sources to enhance self-efficacy."}, {"h": "Relationship with the abstinence violation effect", "p": "After a single lapse, if self-efficacy drops sharply, the abstinence violation effect (''I can''t do it after all'') amplifies relapse. The key is to prevent a lapse from leading to a collapse of self-efficacy."}]'::jsonb, updated_at=now() WHERE id='self-efficacy';
UPDATE encyclopedia_terms SET definition_en='The self-medication hypothesis is a psychodynamic perspective that views addiction not as a simple pursuit of pleasure, but as an attempt to self-regulate unbearable emotional pain. Refined by Khantzian, this hypothesis posits that individuals choose specific substances because they alleviate particular emotional states (e.g., anxiety, depression, anger, emptiness). It carries therapeutic implications that understanding the pain underlying problematic behavior is essential for sustainable recovery.', example_en='Example: A person with chronic anxiety may be drawn to sedatives or alcohol that dampen tension, while someone feeling lethargic may be attracted to stimulants that provide arousal, illustrating how substance choice varies.', body_en='[{"h": "What is it", "p": "The self-medication hypothesis is a psychodynamic perspective that views addiction not as a simple pursuit of pleasure, but as an attempt to self-regulate unbearable emotional pain."}, {"h": "How does it explain", "p": "It suggests that individuals choose substances that alleviate their specific emotional pain, such as anxiety, depression, anger, or emptiness. The reason a person is drawn to a particular substance is that it matches the emotion it relieves."}, {"h": "What does it imply", "p": "This perspective focuses on ''why this particular substance?'' and ''what is being soothed?'' It provides insight that unless the pain behind addiction is addressed, sustained recovery is difficult."}, {"h": "Therapeutic implications", "p": "The self-medication hypothesis supports integrated treatment that addresses the underlying emotional pain, trauma, and mental disorders driving substance use. It encourages looking at causes, not just symptoms."}]'::jsonb, advanced_en='[{"h": "Khantzian''s theory", "p": "The self-medication hypothesis is a psychodynamic theory refined by Khantzian and others, which posits that substance choice is not random but aligns with an individual''s specific emotional distress. It emphasizes the ''fit'' between the substance and the emotion."}, {"h": "Connection with comorbidity", "p": "This hypothesis provides a framework for explaining the high comorbidity between depression, anxiety, PTSD, and addiction. It suggests that attempts to alleviate the pain of mental disorders through substances lead to dual diagnosis."}, {"h": "Evidence and limitations", "p": "The self-medication hypothesis is clinically compelling but does not explain all addictions, and the direction of causality (whether pain drives use or use exacerbates pain) is complex. It is understood as complementary to reward and learning models."}]'::jsonb, updated_at=now() WHERE id='self-medication';
UPDATE encyclopedia_terms SET definition_en='A short prayer widely recited in 12-step recovery, asking for serenity to accept what cannot be changed, courage to change what can be changed, and wisdom to know the difference. It embodies the recovery attitude of acceptance and discernment of controllability.', example_en='Example: A recovery guideline that helps let go of obsession over uncontrollable things and focus on what can be done now.', body_en='[{"h": "What Is It", "p": "The Serenity Prayer is a short prayer widely recited in 12-step recovery, asking for serenity to accept what cannot be changed, courage to change what can be changed, and wisdom to know the difference."}, {"h": "What Does It Contain", "p": "It asks to let go of obsession over uncontrollable things, focus on what can be done now, and seek wisdom to discern the two. It embodies the recovery attitude of acceptance and discernment of controllability."}, {"h": "Why Is It Used in Recovery", "p": "In addiction recovery, clinging to uncontrollable things (past, others, outcomes) leads to pain and relapse. This prayer serves as a guideline to let go of that obsession and focus on what can be done."}, {"h": "What to Consider", "p": "The Serenity Prayer goes beyond religious formality, containing universal recovery wisdom of balance between acceptance and action. This attitude of discernment becomes the core of recovery practice."}]'::jsonb, advanced_en='[{"h": "Balance of Acceptance and Action", "p": "The core of this prayer is the balance between acceptance (what cannot be changed) and action (what can be changed), and the wisdom to discern the two. This aligns with the controllability distinction in cognitive behavioral therapy."}, {"h": "Spirituality and Universality", "p": "Although originating from a specific religious prayer, its wisdom is universally accepted beyond religion. The attitude is also usefully applied in secular recovery."}, {"h": "Discernment as Practice", "p": "Discerning what to accept and what to change is a daily practice in recovery. This prayer functions as a tool to remind one of that discernment in every moment."}]'::jsonb, updated_at=now() WHERE id='serenity-prayer';
UPDATE encyclopedia_terms SET definition_en='The concept that substance experiences are heavily influenced by an individual''s psychological state (set) and physical/social environment (setting), particularly important for hallucinogens. The same substance and dose can produce entirely different experiences depending on context.', example_en='Example: The experience in a safe, supportive environment versus an anxious environment can be completely different.', body_en='[{"h": "What Is It", "p": "Set and setting is the concept that substance experiences are heavily influenced by an individual''s psychological state (set) and physical/social environment (setting). It is especially important for hallucinogens."}, {"h": "Why It Matters", "p": "The same substance and dose can produce entirely different experiences depending on mindset and environment. Experiences in a safe, supportive setting versus an anxious environment can be drastically different."}, {"h": "Therapeutic Implications", "p": "The reason psychedelic-assisted therapy emphasizes controlled environments, preparation, and the presence of a therapist is due to the principle of set and setting. Context, rather than the substance itself, shapes the experience and outcome."}, {"h": "What It Suggests", "p": "Set and setting shows that addiction and drug experiences are not purely pharmacological but context-dependent. This aligns with why changing one''s environment is important for recovery."}]'::jsonb, advanced_en='[{"h": "Context Dependence", "p": "Set and setting demonstrates that drug effects result from an interaction between pharmacological and contextual factors. This principle connects to phenomena such as placebo effects and environment-dependent tolerance changes."}, {"h": "Principles of Treatment Design", "p": "Psychedelic therapy carefully designs set (preparation, expectations) and setting (safe space, companions). Controlled set and setting are essential conditions for therapeutic efficacy and safety."}, {"h": "Risks of Recreational Use", "p": "Use in uncontrolled set and setting (anxious state, dangerous environment) increases the risk of bad trips and accidents. This principle explains the dangers of unsupervised use."}]'::jsonb, updated_at=now() WHERE id='set-and-setting';
UPDATE encyclopedia_terms SET definition_en='Sexual addiction is repeated, out-of-control sexual thoughts, urges or behavior that harm functioning and relationships. ICD-11 classifies it as compulsive sexual behavior disorder within impulse-control disorders, and whether to call it an addiction is debated. It calls for careful handling that separates moral judgment from clinical pathology.', example_en='Repeated sexual behavior that clearly harms relationships and work, yet the person cannot stop and suffers as a result.', body_en='[{"h": "What it is", "p": "Sexual addiction refers to the inability to control sexual thoughts, urges, and behaviors, repeating them to the harm of one''s functioning and relationships. It is a domain requiring careful approach that separates moral judgment from pathology."}, {"h": "How to distinguish it", "p": "The core is not the frequency or type of sexual behavior but loss of control and the resulting real harm. It becomes a problem when repeated sexual behavior clearly damages relationships, work, and health, yet one cannot stop and suffers because of it. Not confusing personal values and culture with pathology is important."}, {"h": "What gets entangled", "p": "Sexual addiction is often entangled with emotional pain, loneliness, trauma, and depression and anxiety, and sexual behavior may function as a channel to soothe that pain. Shame is great, making it hard to ask for help, and this silence sustains the problem."}, {"h": "Response", "p": "Non-stigmatizing understanding and professional help are needed. Treatment addressing the underlying emotional pain and trauma, skills to manage the triggers of compulsive behavior, and recovering healthy intimacy become the goals. An approach including the partner and relationship often helps."}]'::jsonb, advanced_en='[{"h": "Diagnostic classification and naming debate", "p": "ICD-11 classifies this as ''compulsive sexual behavior disorder'' under impulse-control disorders, and scholarly opinion is divided on whether to call it ''addiction.'' Criticism that the name ''sexual addiction'' promotes pathologization and stigma clashes with advocacy that it reflects clinical reality."}, {"h": "Boundaries with morality and culture", "p": "Because judgments about sexual behavior are heavily shaped by culture and values, what counts as ''excessive'' is itself contested. Religious and moral guilt risks being confused with actual loss of control, so diagnosis must rest on functional impairment and loss of control rather than cultural norms."}, {"h": "Comorbidity and underlying factors", "p": "Compulsive sexual behavior commonly co-occurs with trauma, attachment injury, and depression and anxiety. From this view, sexual behavior is often understood as an attempt to fill deficits in emotional regulation and attachment, and treatment addressing the relational and emotional structure beneath, not just the surface behavior, is emphasized."}]'::jsonb, updated_at=now() WHERE id='sexual-addiction';
UPDATE encyclopedia_terms SET definition_en='Short-form video describes the compulsive viewing driven by endless autoplay and algorithmic recommendation, where each clip delivers an immediate reward. ''Dopamine'' is popular shorthand for this reward loop, and ''dopamine fasting'' emerged as a loosely evidenced backlash. It is best understood as a cultural and behavioral phenomenon affecting attention and time-use rather than a clinical diagnosis.', example_en='Meaning to watch for ten minutes, then losing two hours to autoplay and feeling drained and unfocused afterward.', body_en='[{"h": "What it is", "p": "Short-form and dopamine culture refers to the phenomenon where endless autoplay of short videos and algorithmic recommendation deliver repeated instant rewards, inducing compulsive viewing. More accurately, it is understood as a cultural and behavioral phenomenon affecting attention and time use, rather than a clinical diagnosis."}, {"h": "How it works", "p": "Before one clip ends the next plays automatically, and the algorithm learns from the user''s reactions to serve ever more captivating videos. Because each clip delivers a short, strong stimulus instantly, ''just a little'' stretches into long stretches. ''Dopamine'' is used as a popular term for this instant-reward loop."}, {"h": "Why it is discussed", "p": "There is concern that getting used to short, strong stimulation may make long, slow immersion—reading, deep conversation, study—feel comparatively boring. Emptiness after viewing and declining concentration are commonly reported. Yet it is prudent to treat this as a matter of habit and attention rather than declaring it a clinical ''addiction.''"}, {"h": "Response", "p": "Small environmental and habit adjustments—turning off autoplay, setting viewing time, noticing unconscious scrolling—are effective. Popular discourse like ''dopamine fasting'' has emerged, but its scientific basis is loose, so a perspective of restoring balance rather than eliminating stimulation is more realistic."}]'::jsonb, advanced_en='[{"h": "''Dopamine'' as a scientific expression", "p": "The popular terms ''dopamine addiction'' and ''dopamine fasting'' are neuroscientifically inaccurate simplifications. Dopamine relates to reward prediction, motivation, and salience rather than pleasure itself, and quitting a particular activity does not ''reset dopamine.'' The gap between the term''s popular spread and its scientific reality characterizes this topic."}, {"h": "Evidence on attention and cognition", "p": "Research on how overconsumption of short videos affects sustained attention, delay of gratification, and learning is ongoing, and conclusions are not yet settled. There are many correlational studies and limited evidence on causation and long-term effects, so cautious interpretation is required over strong assertions."}, {"h": "Design and autonomy", "p": "Autoplay and recommendation algorithms are designed to make the user''s decision to stop difficult. This phenomenon is therefore better seen as an interaction of design and individual habit than a matter of individual willpower. Designs that return control to users (autoplay off by default, etc.) are discussed as alternatives."}]'::jsonb, updated_at=now() WHERE id='short-form-video';
UPDATE encyclopedia_terms SET definition_en='A self-help program based on cognitive-behavioral and motivational enhancement approaches, emphasizing self-directed tools and scientific methods instead of the 12-step spiritual framework. It serves as a secular alternative alongside the 12-step program, broadening recovery options.', example_en='Example: A person who does not resonate with spiritual approaches continues recovery in a self-help group centered on cognitive-behavioral tools.', body_en='[{"h": "What is it", "p": "SMART Recovery is a self-help program based on cognitive-behavioral and motivational enhancement approaches, emphasizing self-directed tools and scientific methods instead of the 12-step spiritual framework. It serves as a secular alternative alongside the 12-step program, broadening recovery options."}, {"h": "What is different", "p": "While the 12-step program emphasizes admitting powerlessness and a spiritual dimension, SMART emphasizes self-efficacy—the belief that one can manage change—and practical tools. Participants learn and apply tools in four areas: motivation enhancement, coping with urges, managing thoughts/feelings/behaviors, and living a balanced life."}, {"h": "Who is it for", "p": "It is an alternative for those who do not resonate with spiritual approaches or prefer self-directed, cognitive methods. A distinctive feature is its focus on problem-solving and graduation rather than a lifelong ''in recovery'' identity. It is not exclusive with the 12-step program; some people use both."}, {"h": "How is it run", "p": "In meetings led by trained facilitators, participants practice cognitive-behavioral tools together. Extensive online resources and tools are provided. The program is designed to apply to various addictive behaviors, not limited to specific substances."}]'::jsonb, advanced_en='[{"h": "Significance of a secular alternative", "p": "The emergence of SMART shows that recovery does not converge into a single framework (the 12-step program). It lowers the threshold for recovery for those who feel uncomfortable with spiritual approaches or have different religious backgrounds, representing the modern trend of diversifying recovery pathways."}, {"h": "Evidence base and limitations", "p": "SMART is rooted in evidence-based principles of cognitive-behavioral and motivational enhancement, but large-scale studies on the program''s long-term effectiveness are relatively scarce compared to the 12-step program. As a self-help program, outcomes are influenced by participation levels and facilitator competence."}, {"h": "Complementary perspective", "p": "It is productive to view the 12-step program and SMART as complementary rather than competitive. Since different paths suit different people, offering multiple options itself is a strength of the recovery system. Recovery policies also move toward coexistence of diverse pathways rather than imposing a single model."}]'::jsonb, updated_at=now() WHERE id='smart-recovery';
UPDATE encyclopedia_terms SET definition_en='Problematic smartphone use is loss of control over phone use that harms daily life, sleep, relationships or safety. The prevailing view is that specific apps—social media, games, video—are the real problem rather than the device itself, sometimes with anxiety when separated from the phone (nomophobia).', example_en='Repeatedly checking the phone while driving or mid-conversation, and feeling intense anxiety when the battery dies.', body_en='[{"h": "What it is", "p": "Smartphone overdependence refers to the inability to control smartphone use, harming daily life, sleep, relationships, and safety. The dominant view holds that the essence lies not in the device itself but in specific activities within it—gaming, social media, video."}, {"h": "How it appears", "p": "One checks the screen repeatedly for no reason, cannot put the phone down even during conversation, meals, or driving, and reacts instantly to notifications. Nomophobia—feeling anxious when separated from the device—may accompany it. The habit of reaching for the phone right before sleep and immediately upon waking erodes sleep."}, {"h": "Why it is a problem", "p": "Constant checking scatters attention, lowering concentration and productivity, and harms sleep quality. Even in face-to-face situations, attention drawn to the phone lowers relationship quality. There are also risks tied directly to safety, such as using while driving. The essence of the problem is the reversal of the device from a tool that helps life into an object that dominates it."}, {"h": "Response", "p": "Specifying ''what'' control is lost over and targeting that app comes first. Minimizing notifications, separating from the device in certain times and places (no phones at the table or in the bedroom), reviewing screen time, and providing alternative activities all help. Rather than blaming the device, addressing the activities within it and the emotional needs they fill is key."}]'::jsonb, advanced_en='[{"h": "Not the ''device'' but the ''activity''", "p": "Studies suggest the real substance of the problem is not the smartphone itself but specific activities on it (social media, gaming, video). The expression ''smartphone addiction'' is therefore a convenience, and actual intervention is more effective when done at the activity level."}, {"h": "Limits of measurement and concept", "p": "Smartphone overdependence scales are criticized for insufficiently separating usage amount from pathology. In an era where the smartphone has become an essential tool for work, relationships, and life, setting the criteria for what counts as ''overdependence'' is tricky."}, {"h": "Nomophobia and anxiety", "p": "Anxiety when separated from the device (nomophobia) is understood less as an independent disorder than as a manifestation, via the smartphone, of dependence on connection, information, and safety together with underlying anxiety. This view suggests addressing underlying needs and anxiety rather than controlling the device."}]'::jsonb, updated_at=now() WHERE id='smartphone-addiction';
UPDATE encyclopedia_terms SET definition_en='A recovery residence or recovery community is an alcohol- and drug-free communal living environment and local recovery community that provides a stable setting for early recovery. Structure and peer support help individuals navigate the high-risk period for relapse.', example_en='Example: Instead of returning directly to a high-risk environment after treatment, an individual prepares for stable reintegration into society by living in a recovery residence.', body_en='[{"h": "What Is It", "p": "A recovery residence or recovery community is an alcohol- and drug-free communal living environment and local recovery community that provides a stable setting for early recovery. Structure and peer support help individuals navigate the high-risk period for relapse."}, {"h": "Why Is It Needed", "p": "Even after completing treatment, returning directly to a previous high-risk environment makes relapse likely. Recovery residences serve as a bridge, allowing individuals to prepare for social reintegration in a stable, substance-free living environment. This approach reflects the impact of the physical environment on recovery maintenance."}, {"h": "How Is It Operated", "p": "Residents manage daily life under shared rules (maintaining abstinence, mutual support, shared responsibilities), with peer support and gradual preparation for independence. Compared to treatment facilities, the environment is more autonomous and closer to everyday life, helping to integrate recovery into daily living."}, {"h": "What Does It Provide", "p": "It provides safe housing, peer relationships with shared goals, and a foundation for moving toward employment and education. This model demonstrates in practice that recovery depends not only on individual will but also on a stable environment and supportive relationships."}]'::jsonb, advanced_en='[{"h": "Housing as Recovery Capital", "p": "Stable housing is a core component of recovery capital. Housing instability can lead to a vicious cycle of relapse, homelessness, and re-incarceration, whereas stable recovery housing provides a foundation to break this cycle. In this regard, recovery residences are understood as a social recovery infrastructure beyond individual treatment."}, {"h": "Evidence and Quality Management", "p": "Evidence supports that recovery residences contribute to abstinence maintenance and relapse reduction, but quality varies widely across facilities, and regulations or standards are often lacking. Certification and standardization to ensure safety and operational quality are noted as challenges."}, {"h": "Expansion to Recovery Villages", "p": "The principles of recovery residences extend to faith-based or ecologically based recovery villages. Combining housing with employment (social enterprises), agricultural/ecological daily life, and communal belonging creates an integrated model that leads recovery toward a full reconstruction of daily life. This aligns with the community-based recovery orientation of a Recovery-Oriented System of Care (ROSC)."}]'::jsonb, updated_at=now() WHERE id='sober-living';
UPDATE encyclopedia_terms SET definition_en='Bandura''s theory that people learn by observing and imitating others'' behaviors and their consequences. In addiction, observing substance use or gambling in peers, family, or media, and seeing it rewarded, leads to learning of use behaviors and expectations. It provides the theoretical basis for prevention education, peer intervention, and media regulation.', example_en='Example: A teenager repeatedly seeing friends happily socializing over drinks learns the expectation that ''alcohol = social pleasure.''', body_en='[{"h": "What is it?", "p": "Social learning theory is a theory that people learn by observing and imitating others'' behaviors and seeing their consequences. It was proposed by Bandura."}, {"h": "How does it work in addiction?", "p": "Observing and imitating substance use by family or peers, and seeing it rewarded, leads to learning of use. Peer influence is a particularly strong factor in initiating substance use during adolescence."}, {"h": "What does it imply?", "p": "It shows that addiction is not just an individual problem but is learned within a social environment. Role models, peers, and media significantly influence use behaviors."}, {"h": "Implications for prevention", "p": "The social learning perspective emphasizes the importance of peer and media environments, refusal skills training, and healthy role models. It provides a basis for prevention targeting not only individuals but also social contexts."}]'::jsonb, advanced_en='[{"h": "Observational learning and modeling", "p": "Social learning emphasizes that learning occurs through observing others without direct experience. Simply seeing substance use being rewarded can form use expectations and behaviors."}, {"h": "Connection to self-efficacy", "p": "Bandura''s theory extends to the concept of self-efficacy. The belief ''I can resist temptation'' influences behavior and is a key target in relapse prevention."}, {"h": "Media and norms", "p": "The social learning perspective highlights how media portrayals of substances and social norms affect use. Cultural messages that normalize drinking and smoking are part of the learning environment."}]'::jsonb, updated_at=now() WHERE id='social-learning';
UPDATE encyclopedia_terms SET definition_en='Social media addiction is compulsive, out-of-control checking and use of social platforms that harms daily life and mental health. Not a formal diagnosis, it is widely studied because attention-economy design—notifications, infinite scroll, likes, intermittent rewards—targets the brain''s reward system. Social comparison, fear of missing out (FOMO), and links to adolescent mental health are central concerns.', example_en='Reflexively opening an app the moment you wake and just before sleep, scrolling endlessly until focus and rest fall apart.', body_en='[{"h": "What it is", "p": "Social media addiction refers to compulsively checking and using social platforms without control, harming daily life and mental health. Though not an official diagnosis, it is widely studied given that the ''attention economy'' design of notifications, infinite scroll, likes, and intermittent rewards targets the brain''s reward system."}, {"h": "How it works", "p": "Social media combines unpredictable rewards (who might have reacted) with social approval (likes, followers) to reinforce repeated checking. Infinite scroll removes stopping points, and notifications constantly pull attention. As a result, ''a quick check'' stretches into long stretches, and fear of missing out (FOMO) prompts reconnection."}, {"h": "Why it is a problem", "p": "Excessive use erodes sleep, concentration, and face-to-face relationships. In particular, social comparison—measuring oneself against others'' edited lives—is linked to anxiety, depression, and lowered self-esteem, and its relation to adolescent mental health is a major issue. The paradox at its core is that a tool meant for connection becomes instead a source of isolation and comparison."}, {"h": "Response", "p": "The goal is use that restores relationships rather than total disconnection. Turning off notifications, managing use time, blocking during certain hours, training to notice unconscious checking habits, and recovering face-to-face relationships and offline activities all help. Healthily meeting the needs for recognition and belonging that social media had filled, elsewhere, is the fundamental response."}]'::jsonb, advanced_en='[{"h": "Diagnostic status and measurement", "p": "Social media addiction is not listed in standard diagnostic systems and is studied through various self-report scales. The criteria separating ''problematic use'' from ''addiction'' and the relation between usage amount and functional impairment remain under discussion, and prevalence estimates swing widely due to the heterogeneity of instruments."}, {"h": "Debate over the direction of causation", "p": "The correlation between social media use and worsening adolescent mental health is repeatedly observed, but the direction and size of causation are debated. Whether use causes depression, depressed people use more, or a third factor explains both remains unresolved, and there are counterarguments that effect sizes are exaggerated."}, {"h": "The attention economy and design responsibility", "p": "Platforms are designed to maximize time spent, and discussion is growing over responsibility for the effects of this design on vulnerable users. Beyond a view that emphasizes only individual restraint, structural responses such as user-protection design, transparency, and age policies are rising as policy agendas."}]'::jsonb, updated_at=now() WHERE id='social-media-addiction';
UPDATE encyclopedia_terms SET definition_en='The Transtheoretical Model (Stages of Change), developed by Prochaska and DiClemente, posits that behavioral change occurs through multiple stages rather than all at once. The stages are precontemplation (no awareness of problem), contemplation, preparation, action, and maintenance. Relapse is understood not as failure but as part of this cycle. The model emphasizes that interventions should be tailored to the individual''s current stage for effectiveness.', example_en='Example: Rather than imposing an action plan on someone in the precontemplation stage who does not yet acknowledge the problem, one should first address their ambivalence and guide them to the next stage.', body_en='[{"h": "What Is It", "p": "The Stages of Change model views behavioral change as occurring through multiple stages rather than all at once. It is divided into precontemplation, contemplation, preparation, action, and maintenance stages."}, {"h": "Each Stage", "p": "The progression is: precontemplation (no awareness of problem), contemplation (ambivalence), preparation (decision to change), action (attempting change), and maintenance (sustaining change). Relapse is understood as part of this cycle."}, {"h": "Why Is It Important", "p": "Since individuals are at different stages of change, interventions must match their stage. Demanding action from someone who does not yet acknowledge the problem only increases resistance."}, {"h": "Implications for Treatment", "p": "The Stages of Change model, combined with motivational interviewing, provides a rationale for tailoring approaches to each stage. Identifying ''which stage is the person in now'' is the starting point for intervention."}]'::jsonb, advanced_en='[{"h": "Transtheoretical Model", "p": "The Stages of Change is part of Prochaska and DiClemente''s Transtheoretical Model, which also includes processes of change, decisional balance, and self-efficacy. It is an integrative framework that encompasses multiple therapy theories."}, {"h": "Nonlinear Progression", "p": "Change does not follow a straight line through stages but progresses in a spiral pattern, moving back and forth. Relapse is not failure but a part of the cycle, providing learning for the next attempt."}, {"h": "Criticism and Utility", "p": "Although the model''s stage divisions have been criticized as arbitrary, it is widely used for its practical value in tailoring interventions to an individual''s readiness. It is particularly useful when combined with motivational interviewing."}]'::jsonb, updated_at=now() WHERE id='stages-of-change';
UPDATE encyclopedia_terms SET definition_en='A psychologist who criticized the disease model and argued that addiction should be understood as a learned, contextual experience. He emphasized a pluralistic perspective on addiction and the possibility of natural recovery, sparking debate.', example_en='Example: A perspective that challenges the view ''once an addict, always an addict'' and highlights the diversity of recovery.', body_en='[{"h": "Who is he?", "p": "Stanton Peele is a psychologist who criticized the disease model and argued that addiction should be understood as a learned, contextual experience."}, {"h": "What does he argue?", "p": "He views addiction not as a fixed brain disease but as a learned experience within an individual''s life context, which can naturally resolve. He emphasizes a pluralistic understanding of addiction."}, {"h": "Why is it important?", "p": "Peele''s critique challenges the notion that ''once an addict, always an addict,'' highlighting the diversity of recovery and the possibility of natural recovery. He provided a significant counterargument to the disease model."}, {"h": "What should we consider?", "p": "Although controversial, Peele''s perspective reminds us of the limitations of reducing addiction to pure biology. It contributes to an integrated understanding that considers brain changes alongside learning, context, and agency."}]'::jsonb, advanced_en='[{"h": "A leading critic of the disease model", "p": "Peele is a leading voice in criticizing the disease model. He argues that the disease concept overly biologizes addiction and obscures individual agency and the potential for recovery."}, {"h": "Emphasis on natural recovery", "p": "Peele emphasizes that many people recover without formal treatment (natural recovery). This is presented as an empirical counterargument to the narrative that ''addiction is a lifelong disease.''"}, {"h": "Productivity of the debate", "p": "Although controversial, Peele''s perspective creates a productive tension that checks the excesses of the disease model and illuminates the diversity of recovery. Today''s integrated perspectives are partly a product of this debate."}]'::jsonb, updated_at=now() WHERE id='stanton-peele';
UPDATE encyclopedia_terms SET definition_en='A social prejudice that views addiction as a moral failing, which increases the affected person''s shame and acts as a major barrier to seeking help and treatment, hindering recovery. Disease- and recovery-oriented language and narratives help reduce stigma.', example_en='Example: A person hides their problem and does not seek help due to the perception that they ''lack willpower.''', body_en='[{"h": "What is it", "p": "Stigma is a social prejudice that views addiction as a moral failing, increasing the affected person''s shame and acting as a major barrier to seeking help and treatment, hindering recovery."}, {"h": "How does it work", "p": "The perception of ''lacking willpower'' makes the person feel ashamed, leading them to hide the problem and avoid seeking help. Delayed treatment due to fear of stigma is a common pathway."}, {"h": "What harm does it cause", "p": "Stigma blocks access to treatment, makes recovery more difficult, and influences policy. It can lead to viewing people with addiction as subjects of punishment rather than health care, hindering a public health approach."}, {"h": "How to reduce it", "p": "Disease- and recovery-oriented language and narratives, along with person-first expressions (e.g., ''person with addiction'' instead of ''addict''), help reduce stigma. Stories of people in recovery can counter stigma."}]'::jsonb, advanced_en='[{"h": "Levels of stigma", "p": "Stigma is divided into social stigma (prejudice from others), self-stigma (internalized shame), and structural stigma (discrimination in institutions and policies). Recovery requires addressing these multiple levels together."}, {"h": "Power of language", "p": "Recognizing that terms like ''addict'' or ''clean/dirty'' reinforce stigma, a shift to person-centered, non-stigmatizing language is internationally recommended. Language influences attitudes and policy."}, {"h": "Perspective of affected individuals", "p": "For people in recovery, stigma is one of the biggest barriers to recovery. Recovery communities, where individuals share their stories and support each other, provide a space to reclaim identity and counter stigma."}]'::jsonb, updated_at=now() WHERE id='stigma';
UPDATE encyclopedia_terms SET definition_en='A class of substances that activate the central nervous system, increasing alertness, energy, and confidence by enhancing dopamine and norepinephrine activity. Includes cocaine, amphetamines, methamphetamine, caffeine, and nicotine. Overuse can lead to cardiovascular risks and acute psychosis. The ''high-crash'' cycle drives repeated use.', example_en='Example: Using a stimulant to stay awake all night, then experiencing a severe crash when the effect wears off, leading to a cycle of repeated use.', body_en='[{"h": "What Are Stimulants?", "p": "Stimulants are a class of substances that activate the central nervous system, increasing alertness, energy, and confidence by enhancing dopamine and norepinephrine activity. They include cocaine, amphetamines, methamphetamine, caffeine, and nicotine."}, {"h": "How Do They Work?", "p": "Stimulants amplify the brain''s arousal and reward signals, producing a brief, intense high. When the effect ends, a rapid crash occurs, and the desire to bridge this gap leads to repeated use—a typical pattern of stimulant use."}, {"h": "Risks", "p": "Overuse can cause cardiovascular risks (arrhythmia, cardiac arrest, stroke) and acute psychosis (paranoia, hallucinations). Long-term use leads to cognitive impairment and severe physical debilitation."}, {"h": "Treatment Gap", "p": "Unlike opioids and alcohol, there are no approved effective medications for stimulant use disorder. Therefore, behavioral treatments such as contingency management are the most evidence-based interventions."}]'::jsonb, advanced_en='[{"h": "Dopamine Reuptake and Release", "p": "Stimulants either block dopamine reuptake (cocaine) or promote dopamine release (amphetamines), causing a surge in synaptic dopamine. This rapid amplification induces strong reward but also triggers neuroadaptation and damage."}, {"h": "Rise of the Stimulant Crisis", "p": "Overshadowed by the opioid crisis, stimulant problems are re-emerging with increased methamphetamine and cocaine overdoses, as well as combined use with opioids. The lack of effective medications complicates the response."}, {"h": "Treatment and Cognitive Enhancement Debate", "p": "Some stimulants are used as ADHD medications, but non-medical ''cognitive enhancement'' misuse is a concern. The boundary between therapeutic use and abuse, along with prescription management, remains a contentious issue."}]'::jsonb, updated_at=now() WHERE id='stimulants';
UPDATE encyclopedia_terms SET definition_en='A state in which repeated use of psychoactive substances such as alcohol, nicotine, opioids, stimulants, and sedatives alters the brain''s reward and motivation circuits, leading to loss of control over use. DSM-5-TR integrates this into substance use disorder and classifies severity as mild, moderate, or severe based on the number of symptoms including impaired control, social impairment, risky use, and pharmacological indicators (tolerance, withdrawal). Although each substance has different mechanisms and risk profiles, they share the core feature of loss of control.', example_en='Example: Different substances such as nicotine, alcohol, and opioids all exhibit the same disorder structure: ''even when trying to quit, one repeatedly uses, and life falls apart as a result.''', body_en='[{"h": "What is it", "p": "Substance addiction is a state in which repeated use of psychoactive substances such as alcohol, nicotine, opioids, stimulants, and sedatives alters the brain''s reward and motivation circuits, leading to loss of control over use. Although each substance has different mechanisms and risks, the core feature is loss of control—''knowing it is harmful but being unable to stop.''"}, {"h": "How is it diagnosed", "p": "DSM-5-TR replaces the dichotomy of abuse and dependence with a unified ''substance use disorder'' and classifies severity as mild, moderate, or severe based on the number of symptoms including impaired control, social impairment, risky use, and pharmacological indicators (tolerance, withdrawal). The focus of diagnosis is not the amount of use but functional impairment and loss of control."}, {"h": "How does it progress", "p": "It typically begins with experimental or social use, gradually increasing in amount (tolerance), leading to discomfort upon cessation (withdrawal), and progressing to compulsive use despite harmful consequences. The shift from initial pleasure-seeking to later pain avoidance is a typical trajectory of substance addiction."}, {"h": "Recovery", "p": "Substance addiction is understood as a chronic, relapsing condition, managed through a combination of medication, psychotherapy, self-help groups, and social support. Effective treatments vary by substance (e.g., medication-assisted treatment for opioids), so individualized approaches, adequate duration, and ongoing care are key to recovery."}]'::jsonb, advanced_en='[{"h": "Common mechanisms", "p": "Different substances ultimately activate the brain''s reward circuit (mesolimbic dopamine pathway) and, with repeated exposure, cause neuroadaptation leading to tolerance, withdrawal, and craving. This common mechanism is the basis for grouping various substances under a single ''substance use disorder.'' However, differences in pharmacological and risk profiles among substances are also clinically important."}, {"h": "Understanding as a spectrum", "p": "Substance addiction is understood not as a binary ''present/absent'' but as a continuum of severity. This supports early intervention and stepped care, suggesting that different interventions are needed from mild use disorder to severe dependence."}, {"h": "Stigma and language", "p": "Substance addiction is often misunderstood as a moral failing, so person-centered language such as ''person with substance use disorder'' is recommended instead of stigmatizing terms like ''addict.'' There is growing recognition that language shifts influence treatment access and recovery attitudes."}]'::jsonb, updated_at=now() WHERE id='substance-addiction';
UPDATE encyclopedia_terms SET definition_en='A supervised consumption site (SCS) is a harm reduction facility where individuals can use pre-obtained drugs under the supervision of trained professionals in a hygienic environment. It aims to reduce overdose deaths and infections, and to connect vulnerable users with treatment and social services. Over 100 such facilities operate worldwide.', example_en='A person who previously injected unsafely in public can now use the drug safely at a supervised site and receive immediate emergency response in case of overdose.', body_en='[{"h": "What It Is", "p": "Supervised consumption sites are facilities where individuals can use pre-obtained drugs under the supervision of trained health professionals in a hygienic environment. They are also known as overdose prevention sites, supervised injection facilities, or drug consumption rooms. The facilities do not supply drugs."}, {"h": "What It Does", "p": "It immediately reverses overdoses, prevents infections (HIV, hepatitis) through clean equipment, and provides guidance on safer use. Above all, it serves as a nonjudgmental point of contact for vulnerable users who are not reached by existing services, linking them to treatment, housing, and medical care."}, {"h": "Why It Is Controversial", "p": "Opposition centers on moral criticism that it condones or encourages drug use, as well as concerns about neighborhood disorder. However, evidence shows that these facilities do not increase drug use and reduce overdose deaths and infections. They are particularly effective in areas where public drug use is already prevalent."}, {"h": "Global Spread", "p": "Supervised consumption sites operate in over 100 locations worldwide, including Europe, Canada, and Australia. In 2025, a site opened in Glasgow, UK, and in 2024, one opened in Bogotá, South America. Adoption and rollback vary depending on each country''s legal and political environment, making this a frontline harm reduction policy."}]'::jsonb, advanced_en='[{"h": "Scope and Limitations of Evidence", "p": "Systematic reviews report that supervised consumption sites contribute to reductions in overdose deaths, infection prevention, service linkage, and cost savings. However, the impact on local crime and public order, as well as recent rollbacks in some jurisdictions, highlight the context-dependent nature of effectiveness, revealing a significant gap between evidence and political acceptability."}, {"h": "Diversity of Models", "p": "Operational models vary by site. Some, like those in Vancouver and Sydney, manage overdoses on-site, while others in certain countries are required to call emergency services. The nature and outcomes of a facility differ depending on the extent to which it integrates syringe exchange, drug checking, and recovery linkage."}, {"h": "Position Within the Recovery System", "p": "Supervised consumption sites are meaningful only when designed as part of a broader care continuum that includes prevention, treatment, and recovery. The key is to ensure that this life-saving point of contact leads to subsequent treatment and recovery, aligning with the continuous care emphasized by recovery-oriented systems of care (ROSC)."}]'::jsonb, updated_at=now() WHERE id='supervised-consumption';
UPDATE encyclopedia_terms SET definition_en='A drug policy introduced by Switzerland in the 1990s during a severe drug and HIV crisis, which balances four pillars: prevention, treatment, harm reduction, and law enforcement. It is a representative case of shifting from a punishment-oriented abstinence approach to a pragmatic public health strategy, reaffirmed by a national referendum.', example_en='Heroin-assisted treatment (HAT), where chronic heroin users who did not respond to conventional treatment are prescribed pharmaceutical-grade heroin in a medically controlled environment.', body_en='[{"h": "What is it?", "p": "The Swiss Four-Pillar Model is a national policy that balances four axes—prevention, treatment, harm reduction, and law enforcement—in addressing drug problems. The key is that it does not lean toward any single pillar but builds all four together, aiming to reduce harm and help people rather than wage a ''war on drugs.''"}, {"h": "Why was it started?", "p": "In the 1980s–1990s, Switzerland faced a severe crisis with open drug scenes (e.g., Zurich''s ''Needle Park''), soaring HIV infections, and overdose deaths. As existing abstinence-oriented punitive policies failed to cope, innovative public health programs at the local level (low-threshold methadone, needle exchange, safe consumption sites, heroin prescription) emerged and later evolved into national policy."}, {"h": "Prescribing heroin?", "p": "The most controversial element was heroin-assisted treatment (HAT), which prescribed pharmaceutical-grade heroin in a medically controlled environment to chronic users who did not respond to other treatments. Contrary to fears of ''encouraging use,'' results showed reductions in illegal heroin use, related crime, infections, and deaths, along with improved social functioning (housing, employment)."}, {"h": "Results and consolidation", "p": "Decades of meticulous monitoring and evaluation confirmed decreases in overdose deaths, HIV infections, and drug-related crime, as well as improved treatment access. Open drug scenes virtually disappeared. These outcomes broadened public support, leading to the Four-Pillar policy being reaffirmed by a national referendum and codified into law. It is a prime example of building social consensus through evidence."}]'::jsonb, advanced_en='[{"h": "Evidence for HAT", "p": "Heroin-assisted treatment has been compared to oral methadone in randomized controlled trials, demonstrating its specific value. EMCDDA and Cochrane reviews confirm improvements in health and social functioning and reductions in illicit use and crime. However, it is provided only under strict criteria (long-term use, failure of prior treatments), and despite the evidence, only a few countries have implemented it."}, {"h": "Conditions for success", "p": "The lesson from Switzerland lies in the ''integration'' of the four pillars. Balance—not just harm reduction or punishment—combined with local experimentation, rigorous evaluation, public debate, and broad popular support enabled the policy to take root. Some analyses suggest that Switzerland''s federal system and consensus democracy facilitated this gradual shift."}, {"h": "The paradox of success", "p": "Interestingly, as the policy succeeded and drug problems became less visible, the momentum for continued reform and willingness to allocate financial support weakened. The Swiss case shows that maintaining and advancing policy after the crisis subsides is another challenge."}]'::jsonb, updated_at=now() WHERE id='swiss-four-pillars';
UPDATE encyclopedia_terms SET definition_en='Synanon is an early therapeutic community that emerged in the 1950s, characterized by intense peer confrontation. It greatly influenced the therapeutic community movement but later became controversial due to its authoritarian transformation, serving as a historical example that illustrates both the potential and risks of community-based recovery.', example_en='Example: A historical case that simultaneously demonstrates the strong influence of community treatment and the risk of its authoritarian degeneration.', body_en='[{"h": "What Is It", "p": "Synanon is an early therapeutic community that emerged in the 1950s, characterized by intense peer confrontation. It greatly influenced the therapeutic community movement but later became controversial due to its authoritarian transformation."}, {"h": "What Did It Do", "p": "It attempted recovery through strong mutual confrontation (''the game'') within communal living. It pioneered a model where the peer community, rather than professionals, became the agent of treatment."}, {"h": "What Was the Problem", "p": "Despite its early innovative impact, Synanon later degenerated into a closed, authoritarian group, becoming embroiled in controversies over control and abuse. It is a case where the power of community turned into danger."}, {"h": "What Did It Leave Behind", "p": "Synanon simultaneously demonstrates the potential and risks of community-based recovery. It inspired the therapeutic community movement while leaving lessons that caution against the dangers of power and control."}]'::jsonb, advanced_en='[{"h": "Roots of the Therapeutic Community", "p": "Synanon is an important root of the modern therapeutic community movement. The idea that the peer community itself can serve as a tool for recovery has been carried forward into numerous subsequent programs."}, {"h": "Light and Shadow of Community", "p": "Synanon''s history shows that a strong community has a dual nature of support and control. The power that provides belonging and change can, if unchecked, degenerate into oppression."}, {"h": "A Lesson to Heed", "p": "Synanon''s degeneration warns of the dangers when recovery communities become closed, charismatic-authoritarian, and lack external oversight. It is a case that prompts reflection on the conditions for a healthy community."}]'::jsonb, updated_at=now() WHERE id='synanon';
UPDATE encyclopedia_terms SET definition_en='A long-term treatment model that supports recovery through peer interaction and structured daily life in a communal living setting. The community itself is used as a tool for change, and it overlaps with faith-based and ecologically based recovery communities.', example_en='Example: Rehabilitating within a community where members live together, share roles, and support each other''s recovery.', body_en='[{"h": "What Is It", "p": "A therapeutic community is a long-term treatment model that supports recovery through peer interaction and structured daily life in a communal living setting. The community itself is used as a tool for change, and it overlaps with faith-based and ecologically based recovery communities."}, {"h": "How Does It Work", "p": "Members live together, share roles and responsibilities, and learn new ways of life through a structured daily routine and mutual peer feedback. Individual change is supported and validated within the community, operating on the principle that ''the community is the therapist.'' It is typically a long-term process lasting several months or more."}, {"h": "Why Is It Effective", "p": "It provides a stable environment and sense of belonging during the early stages of recovery, when isolation is common, and allows individuals to reconstruct their identity with the support of peers who share similar experiences. Instead of immediately returning to a risky environment, it offers time and space to build a foundation for recovery."}, {"h": "Modern Forms", "p": "Traditional therapeutic communities have expanded into various forms, including faith-based recovery communities and ecological/agricultural recovery villages. This long-term community model that rebuilds entire lives is gaining attention as an approach that restores work, relationships, and meaning beyond treatment."}]'::jsonb, advanced_en='[{"h": "History and Light and Shadow", "p": "The therapeutic community movement began in the 1950s–60s with places like Synanon and had a significant impact, but some became controlling and closed, revealing risks. This history shows both the powerful potential of community-based recovery and the need to guard against the dangers of power and control."}, {"h": "Evidence and Application", "p": "Therapeutic communities have shown effectiveness particularly for severe, chronic users and populations involved with correctional facilities. However, as a long-term, high-intensity intervention, dropout rates and costs are challenges, and improvements toward enhancing voluntariness and individualization are needed."}, {"h": "Expansion to Faith and Ecological Communities", "p": "Modern recovery villages combine therapeutic community principles with faith-based meaning, agricultural/ecological daily life, and social enterprise-based self-sufficiency. This represents an expansion of perspective that views recovery not as individual treatment but as rebuilding life and community belonging, aligning with the community-based accumulation of recovery capital emphasized by recovery-oriented systems of care (ROSC)."}]'::jsonb, updated_at=now() WHERE id='therapeutic-community';
UPDATE encyclopedia_terms SET definition_en='An adaptive phenomenon in which increasingly larger amounts or stronger stimuli are needed to achieve the same effect. It occurs as the nervous system lowers its responsiveness in response to repeated exposure, becoming the starting point of a vicious cycle where usage and risk both increase. It appears not only with substances but also in behavioral addictions, such as gambling stakes or gaming time. Clinically, it is important that if tolerance has developed and one suddenly returns to a previous dose, the risk of overdose increases.', example_en='Example: A person taking opioids for pain relief gradually requires higher doses to achieve the same analgesic effect.', body_en='[{"h": "What is it", "p": "Tolerance is a phenomenon in which increasingly larger amounts are needed to achieve the same effect. It results from the body''s and nervous system''s adaptation to repeated exposure."}, {"h": "Why is it dangerous", "p": "As tolerance increases usage, the risk of overdose also rises. Especially with opioids, increased dosage raises the risk of respiratory depression."}, {"h": "Relationship with withdrawal", "p": "When tolerance develops, reducing or stopping use leads to withdrawal. Tolerance and withdrawal are two faces of physical dependence and often occur together."}, {"h": "What is good to know", "p": "Tolerance itself is not addiction. Even if tolerance develops to a prescribed medication, it may not be addiction if there is no loss of control. It is important to distinguish between tolerance and addiction."}]'::jsonb, advanced_en='[{"h": "Result of neuroadaptation", "p": "Tolerance results from the brain adjusting its receptors and signaling systems in response to repeated exposure. This adaptation forms the biological basis for withdrawal and craving."}, {"h": "Tolerance reduction and overdose", "p": "After a period of abstinence, tolerance decreases. If one then resumes use at the previous dose, it can lead to fatal overdose. This ''relapse after tolerance reduction'' is a common pathway to overdose death."}, {"h": "Distinction between dependence and addiction", "p": "Tolerance is an indicator of physical dependence, not identical to addiction. This distinction is clinically important to avoid unfairly stigmatizing pain patients."}]'::jsonb, updated_at=now() WHERE id='tolerance';
UPDATE encyclopedia_terms SET definition_en='This area demonstrates that adverse childhood experiences (ACEs) such as abuse, neglect, and domestic violence significantly increase the risk of addiction in adulthood. Large-scale studies show that higher ACE scores are clearly associated with increased risk of substance use disorder, and trauma is understood to alter emotional regulation and stress responses, leading to self-medicating substance use. It provides the basis for a trauma-informed approach that asks ''What happened to you?'' rather than ''What is wrong with you?''', example_en='Example: A person who experienced repeated emotional neglect in childhood becomes dependent on substances in adulthood during extreme stress.', body_en='[{"h": "What It Is", "p": "Adverse childhood experiences (ACEs) and trauma are powerful risk factors for addiction. Early adversities such as abuse, neglect, and household dysfunction significantly increase later vulnerability to addiction."}, {"h": "How They Are Connected", "p": "Attempts to soothe the emotional pain, hyperarousal, and shame left by trauma often lead to substance use. Addiction functions as a coping mechanism (self-medication) for the distress caused by trauma."}, {"h": "ACE Research", "p": "Large-scale ACE studies show that the more adverse childhood experiences a person has, the proportionally higher their risk for later addiction, mental illness, and physical disease. This provides evidence that early experiences affect lifelong health."}, {"h": "Implications for Treatment", "p": "Integrated treatment addressing both trauma and addiction is recommended. Without addressing trauma, addiction treatment is difficult to sustain, and vice versa."}]'::jsonb, advanced_en='[{"h": "Trauma-Informed Care", "p": "A trauma-informed approach that asks ''What happened to you?'' instead of ''What is wrong with you?'' is spreading in addiction treatment. It emphasizes safety, trust, and choice to avoid re-traumatization."}, {"h": "Neurobiological Pathways", "p": "Early trauma alters the stress response system (HPA axis) and brain development, leaving vulnerabilities in emotional regulation and impulse control. These changes serve as biological mediators of addiction vulnerability."}, {"h": "Shame and Recovery", "p": "Shame lies at the core of addiction intertwined with trauma. A non-judgmental approach that addresses stigma and shame is a prerequisite for recovery, aligning with person-centered and community perspectives."}]'::jsonb, updated_at=now() WHERE id='trauma-addiction';
UPDATE encyclopedia_terms SET definition_en='A comprehensive term for medical, psychological, and social interventions aimed at alleviating and managing addiction. It includes detoxification, pharmacotherapy (e.g., opioid agonist therapy), cognitive-behavioral therapy, motivational interviewing, self-help groups, and social support, tailored to the individual. Continuous care is key; outcomes depend more on integrated approaches and sufficient duration than on any single treatment.', example_en='Example: An integrated treatment plan that uses medication to reduce craving, cognitive-behavioral therapy to develop coping skills, and self-help groups for support.', body_en='[{"h": "What is it", "p": "Treatment is a comprehensive term for medical, psychological, and social interventions aimed at alleviating and managing addiction. It includes detoxification, pharmacotherapy, cognitive-behavioral therapy, motivational interviewing, self-help groups, and social support, tailored to the individual. Outcomes depend more on integrating multiple approaches and ensuring sufficient duration than on any single treatment."}, {"h": "What are the stages", "p": "It begins with safe detoxification during the acute phase, followed by psychotherapy and pharmacotherapy to address craving and relapse, and then ongoing care to maintain recovery in daily life. If detoxification is not followed by subsequent treatment, relapse is likely; it is important not to mistake the start of treatment for its end."}, {"h": "What determines effectiveness", "p": "Individualized tailoring, integrated treatment of co-occurring mental disorders, sufficient treatment duration, and continued post-treatment support determine outcomes. Combining medication to reduce craving with psychotherapy to build coping skills and self-help groups for support is more effective than any single approach."}, {"h": "Access issues", "p": "Effective treatment is useless if it is not accessible. Cost, waiting times, geographic disparities, and stigma are barriers to entering treatment. Accessibility is as important as treatment quality and is a key policy challenge."}]'::jsonb, advanced_en='[{"h": "Spectrum of evidence-based treatments", "p": "Addiction treatment comprises several evidence-based approaches, including cognitive-behavioral therapy, motivational interviewing, contingency management, and medication-assisted treatment. Effective combinations vary by substance and individual; finding what works for whom is a clinical challenge. The gap between evidence-based treatments and real-world practice remains a persistent issue."}, {"h": "Need for integrated treatment", "p": "Addiction often co-occurs with depression, anxiety, trauma, and other conditions; treating only one increases relapse risk. Integrated treatment that addresses both addiction and co-occurring disorders is recommended, implying that treatment systems must be linked with mental health and primary care."}, {"h": "Voluntariness and the debate on compulsory treatment", "p": "Treatment effectiveness is closely tied to the individual''s motivation. This makes the justification and effectiveness of compulsory treatment through the criminal justice system controversial. Internationally, voluntary, evidence-based treatment is recommended as a principle. How to set the boundary between punishment and treatment is a policy issue."}]'::jsonb, updated_at=now() WHERE id='treatment';
UPDATE encyclopedia_terms SET definition_en='A mutual-aid recovery program that began with Alcoholics Anonymous (AA) and has expanded to various addictions. It centers on admitting powerlessness, self-reflection, amends, peer support, and service, with sponsors and meeting communities supporting recovery. It is widely used globally and intersects with faith-based recovery communities.', example_en='Example: A participant attends regular meetings, shares their story, receives guidance from a sponsor, and works through the steps to sustain recovery.', body_en='[{"h": "What Is It", "p": "The Twelve-Step program is a mutual-aid recovery program that began with Alcoholics Anonymous (AA) and has expanded to various addictions. It centers on admitting powerlessness, self-reflection, amends, peer support, and service, with sponsors and meeting communities supporting recovery."}, {"h": "How It Works", "p": "Participants attend regular meetings, share their stories, and work through the steps under the guidance of a sponsor who has already recovered. It starts with acknowledging that one cannot control their addiction through willpower alone, and progresses to restoring relationships and helping others through service. The nonjudgmental support of peers with shared experiences is a key driving force."}, {"h": "What Makes It Special", "p": "The strength of the Twelve Steps lies in the fact that help comes not from professionals but from peers with shared experiences. The structure of recovered individuals guiding newcomers provides sustainability, high accessibility, and a sense of belonging and identity restoration. It is also free and widely available."}, {"h": "Limitations and Diversity", "p": "The spiritual framework of the Twelve Steps does not suit everyone. For those who find it uncomfortable, secular alternatives such as SMART Recovery exist, and there is growing recognition that there is no single path to recovery. It is important to acknowledge multiple pathways together."}]'::jsonb, advanced_en='[{"h": "Origins and Expansion", "p": "AA was founded in 1935 by Bill Wilson and Robert Smith, and later expanded into numerous Twelve-Step fellowships such as NA (Narcotics Anonymous) and GA (Gamblers Anonymous). Carl Jung''s views on spiritual awakening are known to have influenced its early formation. This is an example of one person''s recovery experience becoming the foundation of a global recovery movement."}, {"h": "Evidence of Effectiveness", "p": "Although long criticized for relying on anecdotal evidence, recent controlled studies report that Twelve-Step facilitation therapy performs as well as or better than other treatments in maintaining abstinence. However, effectiveness depends heavily on participation and sense of belonging, and it does not work equally for everyone."}, {"h": "Intersection with Faith Communities", "p": "The spiritual dimension of the Twelve Steps naturally aligns with faith-based recovery communities. Elements such as admitting powerlessness, reliance on a higher power, and recovery within a community resonate with religious recovery narratives. In this regard, the Twelve Steps can serve as a bridge between secular treatment and faith communities."}]'::jsonb, updated_at=now() WHERE id='twelve-step';
UPDATE encyclopedia_terms SET definition_en='Refers to devices that heat a liquid containing nicotine and other substances to produce an aerosol for inhalation, and the act of using them. There is a direct conflict between the claim that they serve as a harm reduction tool to help adult smokers quit and the concern that they act as a gateway to nicotine addiction for adolescents. The rapid spread of high-nicotine products (pod systems) and nicotine pouches, as well as cases of lung injury associated with certain additives, have intensified regulatory debates.', example_en='Example: A person switches to e-cigarettes to quit smoking but ends up being exposed to nicotine more frequently and in larger amounts, leading to continued dependence.', body_en='[{"h": "What Is It", "p": "E-cigarettes and vaping refer to devices that heat a liquid containing nicotine and other substances to produce an aerosol for inhalation, and the act of using them. Because they do not involve combustion, they contain fewer harmful substances and are discussed as a smoking cessation aid, but there is also significant concern about adolescent uptake."}, {"h": "Harm Reduction or Gateway", "p": "There is a direct conflict between the claim that they are a relatively less harmful alternative to help adult smokers quit and the concern that they serve as a gateway to nicotine addiction for adolescents. Both claims have partial evidence, making policy balance difficult."}, {"h": "What Are the Problems", "p": "The rapid spread of high-nicotine pod products and nicotine pouches has increased adolescent nicotine exposure, and cases of acute lung injury associated with certain additives have been reported. Long-term health effects have not yet been fully elucidated."}, {"h": "Regulation", "p": "Countries respond with flavor bans, age restrictions, nicotine concentration limits, and advertising restrictions. Balancing the dual goals of supporting smoking cessation and protecting adolescents is a key challenge."}]'::jsonb, advanced_en='[{"h": "Uncertainty of Evidence", "p": "Evidence on the effectiveness of e-cigarettes for smoking cessation and their long-term safety is still evolving. While relative harm reduction is acknowledged, they are not ''harmless,'' and for non-smoking adolescents, they may pose net harm, leading to differing assessments by target group."}, {"h": "EVALI and Product Diversification", "p": "The 2019 cases of acute lung injury (EVALI) associated with specific additives (e.g., vitamin E acetate) highlighted the importance of regulating product ingredients. The spread of new smokeless products such as nicotine pouches continues to expand the scope of regulation."}, {"h": "Relationship with Tobacco Policy", "p": "E-cigarettes have introduced a new variable into decades of accumulated tobacco control policy. There is criticism that the tobacco industry strategically uses harm reduction arguments, creating a complex interplay of public health, industry, and regulatory interests."}]'::jsonb, updated_at=now() WHERE id='vaping-ecigarettes';
UPDATE encyclopedia_terms SET definition_en='A tough drug policy stance centered on supply disruption and criminal punishment, which dominated global drug policy for decades. Amid criticism that its effects on reducing use are limited relative to increased incarceration and social costs, a shift toward health-centered approaches is being discussed.', example_en='Example: Despite strengthened punishment, use has not significantly decreased, leading to discussions on shifting toward treatment and prevention.', body_en='[{"h": "What is it?", "p": "The War on Drugs is a tough drug policy stance centered on supply disruption and criminal punishment, which dominated global drug policy for decades."}, {"h": "What did it do?", "p": "It strongly cracked down on the production, distribution, and use of drugs as crimes and strengthened penalties. Declared in the United States in 1971, it spread worldwide and became the dominant paradigm of drug policy."}, {"h": "What criticisms does it face?", "p": "There is significant criticism that its effects on reducing use are limited relative to soaring incarceration rates and enormous social costs. Unequal punishment across specific races and classes is also pointed out as a problem."}, {"h": "What is it shifting toward?", "p": "As its limitations become apparent, a shift from punishment-centered to prevention, treatment, and harm reduction-centered approaches is being discussed. Health-centered approaches in Portugal and Switzerland are attracting attention as alternatives."}]'::jsonb, advanced_en='[{"h": "Legacy of mass incarceration", "p": "The War on Drugs left a legacy of mass incarceration and its associated social costs. In particular, racial and class inequalities in criminal punishment are criticized as issues of justice."}, {"h": "Balloon effect", "p": "Supply disruption produced a ''balloon effect,'' where production and distribution move to other regions rather than eliminating the problem. This shows the structural limitations of enforcement-centered approaches."}, {"h": "Debate on paradigm shift", "p": "Although a shift toward health-centered approaches is discussed, it sharply conflicts with perspectives emphasizing the deterrent effect of punishment. Drug policy is a representative arena where evidence and values collide."}]'::jsonb, updated_at=now() WHERE id='war-on-drugs';
UPDATE encyclopedia_terms SET definition_en='A set of physical and psychological symptoms that occur when reducing or stopping the use of an addictive substance. The pattern varies greatly by substance; some, like alcohol or benzodiazepine withdrawal, can involve seizures or delirium and become medical emergencies. It is a rebound phenomenon resulting from the brain''s adapted balance being disrupted, and the motivation to avoid withdrawal distress becomes a powerful force driving continued use. Withdrawal-like reactions such as agitation, anxiety, and irritability are also reported in behavioral addictions like gambling and gaming.', example_en='Example: A person who drinks coffee daily experiences relatively mild withdrawal symptoms such as headache, irritability, and poor concentration for two days after suddenly stopping.', body_en='[{"h": "What It Is", "p": "Withdrawal refers to the physical and psychological symptoms that occur when reducing or stopping the use of a substance on which dependence has developed. Symptoms typically appear in the opposite direction of the substance''s effects."}, {"h": "Why It Drives Relapse", "p": "The motivation to avoid the discomfort of withdrawal sustains substance use. In early recovery, withdrawal is a major trigger for relapse, and in later stages of addiction, avoidance of withdrawal, rather than pleasure, often drives continued use."}, {"h": "Dangerous Withdrawal", "p": "Withdrawal from alcohol, benzodiazepines, and barbiturates can be life-threatening due to seizures and delirium, requiring medical supervision. In contrast, opioid withdrawal, though severe, is usually not life-threatening."}, {"h": "How It Is Managed", "p": "Withdrawal is managed differently depending on the substance. Safe detoxification, substitute medications, and symptom relief are used. Getting through withdrawal is only the beginning of recovery and must be followed by ongoing treatment."}]'::jsonb, advanced_en='[{"h": "Homeostatic Rebound", "p": "Withdrawal is understood as a rebound phenomenon in which the nervous system, having adapted to the substance, loses balance and swings in the opposite direction when the substance is removed. A typical example is the hyperexcitation of the brain after chronic use of depressants."}, {"h": "Acute and Protracted Withdrawal", "p": "After acute withdrawal, symptoms such as anxiety, insomnia, and anhedonia may persist for a prolonged period, known as protracted withdrawal syndrome (PAWS). This period carries a high risk of relapse and requires long-term support."}, {"h": "Withdrawal and Allostasis", "p": "Repeated withdrawal experiences alter the brain''s stress systems, leading to allostasis—a lowering of the baseline state. This explains the ''pain avoidance'' motivation in later stages of addiction."}]'::jsonb, updated_at=now() WHERE id='withdrawal';
UPDATE encyclopedia_terms SET definition_en='Work addiction (workaholism) is compulsive over-immersion in work at the expense of rest, health and relationships, with anxiety or guilt when away from work. Not a formal diagnosis, it is examined in burnout and addiction research and is easily overlooked because it is socially praised. The pathology lies in compulsive loss of control, not in achievement itself.', example_en='Unable to switch off even on days off, feeling anxious, and failing to cut work hours as health and family suffer.', body_en='[{"h": "What it is", "p": "Work addiction refers to compulsively immersing oneself in work at the sacrifice of rest, health, and relationships, and feeling anxiety and guilt when away from work. The core is not achievement itself but compulsion that has lost control."}, {"h": "How it differs from passion", "p": "Loving work differs from being addicted to it. Healthy immersion allows rest when not working, but work addiction cannot stop because rest brings anxiety and guilt. One cannot reduce working hours even as health and relationships collapse, and tries to prove self-worth through work."}, {"h": "Why it is hard to notice", "p": "Work addiction is easily praised socially. Packaged as diligence and dedication, neither the person nor those around them see it as a problem. Yet beneath it, burnout, worsening sleep and health, and alienation from family progress. Social recognition delaying problem awareness is the feature of this addiction."}, {"h": "Response", "p": "Becoming aware of what work substitutes for (avoiding anxiety, self-worth, a sense of control) is the starting point. Setting boundaries between work and rest, practicing finding self-worth outside performance, managing burnout and anxiety, and recovering relationships all work together. The influence of an organizational culture that glorifies long hours must also be considered."}]'::jsonb, advanced_en='[{"h": "Diagnostic status and relation to burnout", "p": "Work addiction is not an official diagnosis and is discussed overlapping with burnout, compulsion, and anxiety. If burnout is the ''result'' of exhaustion, work addiction is closer to the ''process'' racing toward that exhaustion. Their relationship, boundary, and measurement are research issues."}, {"h": "Heterogeneity of motivation", "p": "The motivations of work addiction are not singular. Different underlying motives—achievement orientation, perfectionism, anxiety avoidance, self-esteem compensation—manifest as similar behavior. Because of this heterogeneity, ''working a lot'' alone cannot define pathology."}, {"h": "Cultural and structural context", "p": "Work addiction is reinforced not only by individual disposition but by a culture that treats long hours as virtue, by performance-ism, and by an always-connected work environment. In societies with high work hours and competitive pressure such as Korea, its social implications are especially large, demanding structural discussion beyond individual treatment."}]'::jsonb, updated_at=now() WHERE id='work-addiction';
COMMIT;
-- 확인: 영어 채워진 개수
SELECT category, count(*) FILTER (WHERE definition_en <> '') AS with_en, count(*) AS total FROM encyclopedia_terms GROUP BY category ORDER BY category;
